<template>
  <section class="cat" :aria-label="$t('results.categories.title')">
    <!-- Три рейтинга: выполнение плана прибыли, сток, оборачиваемость -->
    <div class="cat__bars">
      <article v-for="panel in barPanels" :key="panel.id" class="cat__panel">
        <panel-head :icon="panel.icon" :title="$t(panel.title)" :period="period">
          <div v-if="panel.aside" class="cat__aside">
            <b>{{ panel.aside.value }}</b>
            <span>{{ panel.aside.label }}</span>
          </div>
        </panel-head>

        <p v-if="!panel.rows.length" class="cat__empty">{{ $t('results.categories.empty') }}</p>

        <ol v-else class="cat__list">
          <li
            v-for="row in panel.rows"
            :key="row.name"
            class="cat__row"
            :class="{ 'cat__row--hover': hovered === row.name }"
            @pointerenter="hovered = row.name"
            @pointerleave="hovered = null"
          >
            <span class="cat__name" :title="row.name">{{ row.name }}</span>
            <span class="cat__track" aria-hidden="true">
              <i v-if="panel.target !== null" class="cat__target" :style="{ left: `${panel.target}%` }"></i>
              <i class="cat__bar" :class="{ 'cat__bar--over': row.over }" :style="{ width: `${row.width * progress}%`, background: row.color }"></i>
            </span>
            <span class="cat__value">{{ row.text }}</span>
          </li>
        </ol>

        <p v-if="panel.note" class="cat__note">{{ panel.note }}</p>
      </article>
    </div>

    <!-- Структура дохода и прибыли по категорийным менеджерам -->
    <div class="cat__maps">
      <article v-for="map in maps" :key="map.id" class="cat__panel cat__panel--map">
        <panel-head :icon="map.icon" :title="$t(map.title)" :period="period">
          <div class="cat__aside">
            <b>{{ money(map.total) }}</b>
            <span>{{ $t('kpi.uah') }}</span>
          </div>
        </panel-head>

        <p v-if="!map.items.length" class="cat__empty">{{ $t('results.categories.empty') }}</p>

        <template v-else>
          <treemap-chart class="cat__treemap" :items="map.items" :label="$t(map.title)" :value-label="$t(map.valueLabel)" />

          <ul class="cat__legend">
            <li v-for="item in map.items" :key="item.id">
              <i :style="{ background: item.color }" aria-hidden="true"></i>
              {{ item.label }}
            </li>
          </ul>
        </template>
      </article>
    </div>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiCashMultiple, mdiChartPie, mdiPackageVariantClosed, mdiRotate3dVariant, mdiBullseyeArrow } from '@mdi/js'
import PanelHead from '@/components/PanelHead.vue'
import TreemapChart from '@/components/TreemapChart.vue'
import { useResultsStore } from '@/stores/results'
import { useScopeStore } from '@/stores/scope'
import { CAT_COLORS, catPlanColor as planColor } from '@/utils/resultsColors'
import { animateProgress } from '@/utils/tween'
import numberFormatMixin from '@/mixins/numberFormat'

// Цвета и правила — из прежней страницы итогов (results-page-map.md, ResultsPage.vue)
// Строка «СП» — не категорийный менеджер, в блок не входит
const EXCLUDED = 'СП'

// Сток: самый большой — насыщенный, остальные — приглушённые
const STOCK_MAX = 'rgba(13, 148, 136, 0.92)'
const STOCK_REST = 'rgba(20, 184, 166, 0.75)'
// Оборачиваемость: больше 100 дней — тёмно-фиолетовый, остальные светлее
const TURNOVER_LIMIT = 100
const TURNOVER_HIGH = 'rgba(67, 56, 202, 0.85)'
const TURNOVER_REST = 'rgba(99, 102, 241, 0.70)'

// Выброс (например, 1097 % у нового направления) сжал бы остальные столбики до точек: если наибольшее значение
// больше второго в OUTLIER раз, шкала строится по второму, а столбик-выброс обрезается со знаком разрыва
const OUTLIER = 1.6

const isNumber = (value) => typeof value === 'number' && Number.isFinite(value)

// Шкала не меньше 105 %: иначе, если все категории ниже плана, лидер с 85 % дотянулся бы до отметки 100 %
function scaleMax(values) {
  const sorted = [...values].sort((a, b) => b - a)
  const max = sorted.length > 1 && sorted[1] > 0 && sorted[0] > sorted[1] * OUTLIER ? sorted[1] * 1.12 : sorted[0] || 1
  return Math.max(1.05, max)
}

export default {
  name: 'ResultsCategories',

  mixins: [numberFormatMixin],

  components: { PanelHead, TreemapChart },

  data() {
    return {
      // Категория под курсором: подсвечивается во всех трёх рейтингах
      hovered: null,
      progress: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    locale() {
      return this.$i18n.locale
    },

    managers() {
      return useResultsStore()
        .rowsOf('cat_managers', this.period)
        .filter((row) => row.manager && row.manager !== EXCLUDED)
    },

    // Цвет закреплён за менеджером (по месту в доходе), поэтому в обеих структурах он один и тот же
    colors() {
      const order = [...this.managers].sort((a, b) => (b.revenue || 0) - (a.revenue || 0))
      return Object.fromEntries(order.map((row, index) => [row.manager, CAT_COLORS[index % CAT_COLORS.length]]))
    },

    barPanels() {
      const plan = this.managers.filter((row) => isNumber(row.plan_pct) && row.plan_pct > 0).sort((a, b) => b.plan_pct - a.plan_pct)
      const planMax = scaleMax(plan.map((row) => row.plan_pct))
      const stock = this.managers.filter((row) => isNumber(row.stock) && row.stock > 0).sort((a, b) => b.stock - a.stock)
      const stockMax = stock.length ? stock[0].stock : 1
      const turnover = this.managers.filter((row) => isNumber(row.turnover) && row.turnover > 0).sort((a, b) => b.turnover - a.turnover)
      const turnoverMax = turnover.length ? turnover[0].turnover : 1
      const stockTotal = stock.reduce((sum, row) => sum + row.stock, 0)

      return [
        {
          id: 'plan',
          title: 'results.categories.plan',
          icon: mdiBullseyeArrow,
          // Пунктир — 100 % плана
          target: Math.min(100, (1 / planMax) * 100),
          note: plan.some((row) => row.plan_pct > planMax) ? this.$t('results.categories.outlier') : '',
          rows: plan.map((row) => ({
            name: row.manager,
            width: Math.min(100, (row.plan_pct / planMax) * 100),
            over: row.plan_pct > planMax,
            color: planColor(row.plan_pct),
            text: this.percent(row.plan_pct * 100),
          })),
        },
        {
          id: 'stock',
          title: 'results.categories.stock',
          icon: mdiPackageVariantClosed,
          target: null,
          aside: { value: this.millions(stockTotal), label: this.$t('results.categories.stockTotal') },
          rows: stock.map((row) => ({
            name: row.manager,
            width: (row.stock / stockMax) * 100,
            color: row.stock === stockMax ? STOCK_MAX : STOCK_REST,
            text: this.money(row.stock),
          })),
        },
        {
          id: 'turnover',
          title: 'results.categories.turnover',
          icon: mdiRotate3dVariant,
          target: null,
          aside: { value: this.$t('results.categories.days'), label: this.$t('results.categories.over', { n: TURNOVER_LIMIT }) },
          rows: turnover.map((row) => ({
            name: row.manager,
            width: (row.turnover / turnoverMax) * 100,
            color: row.turnover > TURNOVER_LIMIT ? TURNOVER_HIGH : TURNOVER_REST,
            text: this.money(row.turnover),
          })),
        },
      ]
    },

    maps() {
      const build = (field, positive) =>
        this.managers
          .filter((row) => isNumber(row[field]) && (positive ? row[field] > 0 : row[field] !== 0))
          .sort((a, b) => b[field] - a[field])
          .map((row) => ({ id: row.manager, label: row.manager, value: row[field], color: this.colors[row.manager] }))

      const revenue = build('revenue', false)
      const profit = build('profit', true)
      return [
        { id: 'revenue', title: 'results.categories.revenue', valueLabel: 'results.stores.revenue', icon: mdiCashMultiple, items: revenue, total: revenue.reduce((sum, item) => sum + item.value, 0) },
        { id: 'profit', title: 'results.categories.profit', valueLabel: 'results.categories.profitValue', icon: mdiChartPie, items: profit, total: profit.reduce((sum, item) => sum + item.value, 0) },
      ]
    },
  },

  watch: {
    period: {
      immediate: true,
      handler() {
        if (this.stopTween) this.stopTween()
        this.stopTween = animateProgress((progress) => (this.progress = progress), { delay: 150 })
      },
    },
  },

  beforeUnmount() {
    if (this.stopTween) this.stopTween()
  },

}
</script>

