<template>
  <budget-bars
    :label="$t(`budget.profit.${kind}`)"
    :rows="rows"
    :series="series"
    format="money"
    :stats-start="[{ id: 'total', label: $t('budget.profit.total'), color: tone.color, value: `${money(total)} ${$t('kpi.uah')}`, loss: total < 0 }]"
    :stats-end="[{ id: 'losses', label: $t('budget.profit.losses'), color: tone.loss, value: String(losses) }]"
  />
</template>

<script>
import { mapState } from 'pinia'
import BudgetBars from '@/components/BudgetBars.vue'
import numberFormatMixin from '@/mixins/numberFormat'
import { useBudgetStore } from '@/stores/budget'
import { useScopeStore } from '@/stores/scope'
import { SPECIAL, n, rowOpProfit } from '@/utils/budget'

// Цвета — как на прежней странице: прибуток від діяльності синий, чистий прибуток зелёный; убыток — красный
const KINDS = {
  op: { color: 'rgba(99, 102, 241, 0.85)', loss: 'rgba(239, 68, 68, 0.85)', value: (row) => rowOpProfit(row) },
  net: { color: 'rgba(34, 197, 94, 0.85)', loss: 'rgba(239, 68, 68, 0.7)', value: (row) => n(row.net_profit) },
}

// Не сравнивается с обычными магазинами на этих графиках (как на прежней странице)
const EXCLUDED = 'Інтернет Магазин'

// Прибуток від діяльності (op) или чистий прибуток (net) магазинов за месяц — два отдельных блока, как на прежней
// странице (opProfitRows / netProfitRows): магазины без служебных строк и без Інтернет-магазину, от большего к меньшему.
// Прибуток від діяльності = валовая прибыль минус операционные расходы; чистий прибуток — готовое значение (net_profit)
export default {
  name: 'BudgetProfitBars',

  components: { BudgetBars },

  mixins: [numberFormatMixin],

  props: {
    kind: {
      type: String,
      default: 'op',
      validator: (value) => value in KINDS,
    },
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    tone() {
      return KINDS[this.kind]
    },

    stores() {
      return useBudgetStore()
        .rowsOf(this.period)
        .filter((row) => !SPECIAL.has(row.store) && row.store !== EXCLUDED)
        .map((row) => ({ store: row.store, revenue: n(row.revenue), value: this.tone.value(row) }))
        .sort((a, b) => b.value - a.value)
    },

    total() {
      return this.stores.reduce((sum, row) => sum + row.value, 0)
    },

    losses() {
      return this.stores.filter((row) => row.value < 0).length
    },

    series() {
      const { color, loss } = this.tone
      return [{ id: this.kind, label: this.$t(`budget.profit.${this.kind}`), color: (value) => (value < 0 ? loss : color) }]
    },

    rows() {
      return this.stores.map((row) => ({
        label: row.store,
        values: [row.value],
        extra: [`${this.$t('budget.profit.revenue')}: ${this.money(row.revenue)} ${this.$t('kpi.uah')}`],
      }))
    },
  },
}
</script>
