import { defineStore } from 'pinia'
import { watch } from 'vue'
import { useAccessStore } from '@/stores/access'
import { useCompanyStore } from '@/stores/company'
import { useManagersStore } from '@/stores/managers'
import { useBudgetStore } from '@/stores/budget'
import { useResultsStore } from '@/stores/results'

// Страницы со своими данными: имя страницы (имя маршрута) → хранилище её данных, строка и заголовок прелоадера
const PAGES = {
  results: { store: useResultsStore, titleKey: 'loader.results', loaderTitleKey: 'loader.titleResults' },
  budget: { store: useBudgetStore, titleKey: 'loader.budget', loaderTitleKey: 'loader.titleBudget' },
}
export const PAGE_NAMES = Object.keys(PAGES)

// Ожидание данных страницы: { [page]: { promise, finish } } — одно на все переходы, пока данные не пришли
const pending = {}

// loading — ждём ответ, ready — данные есть, error — данных нет, пробуем снова
function statusOf(ready, failed) {
  if (ready) return 'ready'
  return failed ? 'error' : 'loading'
}

// Учёт основных источников данных, без которых дашборд не открывается: компания (если у пользователя есть доступ к главной)
// и каждый менеджер, страница которого ему доступна. Менеджер, например, загружает только свою таблицу.
// Общий прелоадер показывает их состояние, пока все они не ответят. Источник, который не отвечает или отвечает с ошибкой,
// перезапрашивается, пока не даст ответ; пропустить его нельзя. Курс валют и погода второстепенные: они не входят
// в этот список, каждый из них загружается сам и не задерживает открытие дашборда.
// Данные отдельных страниц (итоги, бюджет) грузятся при первом переходе на страницу: тогда прелоадер показывается снова,
// уже с этим источником в списке, и страница открывается только после его загрузки.
export const useSourcesStore = defineStore('sources', {
  state: () => ({
    started: false,
    // Все основные данные пришли, прелоадер закрыт
    finished: false,
    // Запрошенные данные страниц: 'results', 'budget'
    pages: [],
    // Что показывает прелоадер: main — основные источники (и данные страниц, если сайт открыли сразу на странице),
    // имя страницы — отдельный прелоадер её данных при переходе на страницу, когда основные данные уже на экране
    mode: 'main',
  }),

  getters: {
    list() {
      if (this.mode !== 'main') return [this.pageSource(this.mode)]
      const company = useCompanyStore()
      const managers = useManagersStore()
      const access = useAccessStore()
      const allowed = access.allowedManagers.map((manager) => manager.id)

      const list = []
      if (access.canViewCompany) {
        list.push({ id: 'company', group: 'main', titleKey: 'loader.company', status: statusOf(company.loaded, company.failed) })
      }
      for (const manager of managers.list.filter((item) => allowed.includes(item.id))) {
        list.push({
          id: `manager:${manager.id}`,
          group: 'managers',
          title: manager.name,
          color: manager.color,
          status: manager.status === 'idle' ? 'loading' : manager.status,
        })
      }
      this.pages.forEach((page) => list.push(this.pageSource(page)))
      return list
    },

    // Строка прелоадера с данными страницы page
    pageSource() {
      return (page) => {
        const store = PAGES[page].store()
        return { id: page, group: 'pages', titleKey: PAGES[page].titleKey, status: statusOf(store.loaded, store.failed) }
      }
    },

    // Заголовок прелоадера
    titleKey() {
      return this.mode === 'main' ? 'loader.title' : PAGES[this.mode].loaderTitleKey
    },

    readyCount() {
      return this.list.filter((source) => source.status === 'ready').length
    },

    progress() {
      return this.list.length ? this.readyCount / this.list.length : 1
    },

    allReady() {
      // Пустой список (у пользователя нет ни одного источника) тоже считается загруженным, иначе прелоадер не закрылся бы
      return this.readyCount === this.list.length
    },

    hasFailed() {
      return this.list.some((source) => source.status === 'error')
    },

    // Прелоадер виден с момента входа, пока все основные данные не пришли
    visible: (state) => state.started && !state.finished,
  },

  actions: {
    // Запускает загрузку основных источников. Повторный вызов ничего не делает: таблицы не перечитываются
    start() {
      if (this.started) return
      this.started = true
      this.finished = false
      const access = useAccessStore()
      if (access.canViewCompany) useCompanyStore().load()
      useManagersStore().loadAll(access.allowedManagers.map((manager) => manager.id))
    },

    // Роль сменилась, пока дашборд открыт (сверка с таблицей, вход в другой вкладке): догружаем источники,
    // которые стали доступны. Уже загруженные не перечитываются, прелоадер заново не показывается
    sync() {
      if (!this.started) return
      const access = useAccessStore()
      const company = useCompanyStore()
      if (access.canViewCompany && !company.loaded) company.load()
      const managers = useManagersStore()
      const idle = access.allowedManagers.filter((manager) => {
        const source = managers.sources[manager.id]
        return !source || source.status === 'idle'
      })
      managers.loadAll(idle.map((manager) => manager.id))
    },

    // Данные страницы page («Підсумки», «Бюджет»): показывает прелоадер с ними и возвращает промис, который выполнится,
    // когда данные придут. Пока не придут, запрос повторяется (как у основных источников)
    needPage(page) {
      const store = PAGES[page].store()
      if (store.loaded) return Promise.resolve()
      if (!this.pages.includes(page)) this.pages.push(page)
      // Основные данные уже показаны: прелоадер только для этой страницы, без строк прошлой загрузки
      if (this.finished) this.mode = page
      this.finished = false
      store.load()
      if (!pending[page]) {
        let resolve
        const promise = new Promise((done) => (resolve = done))
        const stop = watch(
          () => store.loaded,
          (loaded) => loaded && pending[page] && pending[page].finish(),
        )
        pending[page] = {
          promise,
          finish() {
            stop()
            delete pending[page]
            resolve()
          },
        }
      }
      return pending[page].promise
    },

    // Ушли со страницы page, пока её данные грузятся: её прелоадер закрывается, загрузка останавливается
    // (при следующем заходе начнётся заново)
    leavePage(page) {
      if (!pending[page]) return
      pending[page].finish()
      PAGES[page].store().cancelRetry()
      this.pages = this.pages.filter((item) => item !== page)
      if (this.mode === page) {
        this.mode = 'main'
        this.finished = true
      }
    },

    // Выход из аккаунта: останавливаем повторы, при следующем входе данные загрузятся заново
    stop() {
      useCompanyStore().reset()
      useManagersStore().reset()
      PAGE_NAMES.forEach((page) => {
        if (pending[page]) pending[page].finish()
        PAGES[page].store().reset()
      })
      this.started = false
      this.finished = false
      this.pages = []
      this.mode = 'main'
    },

    finish() {
      this.finished = true
    },
  },
})
