<template>
  <article class="btm">
    <!-- Сводка -->
    <ul class="btm__stats">
      <li>
        <span>{{ $t('budget.treemap.count') }}</span>
        <b>{{ items.length }}</b>
      </li>
      <li>
        <span>{{ $t('budget.treemap.total') }}</span>
        <b>{{ compact(total) }}</b>
      </li>
      <li>
        <span>{{ $t('budget.treemap.top3') }}</span>
        <b>{{ percent(topShare * 100) }}</b>
      </li>
    </ul>

    <treemap-chart
      class="btm__stage"
      :class="{ 'btm__stage--all': phone && expanded }"
      :items="tileItems"
      :label="$t(`budget.treemap.${kind}Title`)"
      :min-area="minArea"
      :label-sizes="labelSizes"
      value-first
    >
      <!-- Подсказка: место, сумма, доля и показатель магазина (маржа или доля расходов в доходе) -->
      <template #tip="{ item }">
        <span class="btm__tip-rank">#{{ item.rank }}</span>
        <strong class="btm__tip-name">{{ item.label }}</strong>
        <span class="btm__tip-row">
          {{ $t(`budget.treemap.${kind}`) }}
          <b>{{ money(item.value) }} {{ $t('kpi.uah') }}</b>
        </span>
        <span class="btm__tip-row">
          {{ $t('budget.treemap.share') }}
          <b>{{ percent(item.share * 100) }}</b>
        </span>
        <span v-if="item.extra !== null" class="btm__tip-row">
          {{ $t(kind === 'revenue' ? 'budget.treemap.margin' : 'budget.treemap.ofRevenue') }}
          <b>{{ percent(item.extra * 100) }}</b>
        </span>
      </template>
    </treemap-chart>

    <!-- Телефон: плитками крупнейшие объекты, остальные — строкой; по кнопке показываются все -->
    <div v-if="phone && rest" class="btm__rest">
      <template v-if="!expanded">
        <span>{{ $t('budget.treemap.others', { n: rest.count }) }}</span>
        <b>{{ compact(rest.value) }}</b>
        <small>{{ percent(rest.share * 100) }}</small>
      </template>
      <button type="button" class="btm__more" :aria-expanded="expanded" @click="expanded = !expanded">
        {{ $t(expanded ? 'budget.treemap.collapse' : 'budget.treemap.showAll') }}
        <v-icon :icon="expanded ? mdiChevronUp : mdiChevronDown" size="16" />
      </button>
    </div>
  </article>
</template>

<script>
import { mapState } from 'pinia'
import { mdiChevronDown, mdiChevronUp } from '@mdi/js'
import TreemapChart from '@/components/TreemapChart.vue'
import numberFormatMixin from '@/mixins/numberFormat'
import { useBudgetStore } from '@/stores/budget'
import { useScopeStore } from '@/stores/scope'
import { FOT_ROW, n, rowExpenses, rowMargin } from '@/utils/budget'

// Палитры прежней страницы: цвет по порядку плитки (не по рангу), доходы — сине-фиолетовые, расходы — красно-оранжевые
const COLORS = {
  revenue: [
    '#4f46e5', '#2563eb', '#0891b2', '#059669', '#7c3aed',
    '#b45309', '#be185d', '#0d9488', '#1d4ed8', '#6d28d9',
    '#047857', '#b91c1c', '#0369a1', '#4338ca', '#0e7490',
    '#065f46', '#7e22ce', '#92400e', '#1e40af', '#166534',
    '#831843', '#1e3a8a', '#134e4a', '#3730a3', '#78350f',
  ],
  expenses: [
    '#dc2626', '#ea580c', '#d97706', '#b45309', '#92400e',
    '#9f1239', '#7f1d1d', '#c2410c', '#a16207', '#78350f',
    '#6366f1', '#7c3aed', '#0891b2', '#059669', '#1d4ed8',
    '#be185d', '#0d9488', '#4338ca', '#0e7490', '#166534',
    '#64748b', '#334155', '#1e293b', '#4b5563', '#374151',
  ],
}
// Наименьшая доля площади плитки: самые маленькие объекты иначе были бы тоньше промежутка и пропали бы
const MIN_AREA = 0.003
// Телефон: сколько крупнейших объектов показывать плитками, пока не нажата кнопка «Показати всі»
const PHONE_TILES = 15
// Минимальный размер плитки для подписей: полная (название, сумма, доля), название с суммой, только сумма
const LABELS = [
  { id: 'full', w: 118, h: 76 },
  { id: 'name', w: 72, h: 42 },
  { id: 'value', w: 64, h: 22 },
]

// Treemap дохода или расходов по объектам (магазины, офис, склады) за выбранный месяц.
// Все строки, кроме строки ФОТ, с положительной суммой, от большей к меньшей
export default {
  name: 'BudgetTreemap',

  components: { TreemapChart },

  mixins: [numberFormatMixin],

  props: {
    // revenue — доход, expenses — операционные расходы
    kind: {
      type: String,
      default: 'revenue',
      validator: (value) => ['revenue', 'expenses'].includes(value),
    },
  },

  data() {
    return {
      minArea: MIN_AREA,
      labelSizes: LABELS,
      // Телефон: показаны все объекты
      expanded: false,
      mdiChevronDown,
      mdiChevronUp,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    // Объекты месяца: сумма, доля, место и показатель для подсказки
    items() {
      const revenue = this.kind === 'revenue'
      const rows = useBudgetStore()
        .rowsOf(this.period)
        .filter((row) => row.store !== FOT_ROW)
        .map((row) => {
          const value = revenue ? n(row.revenue) : rowExpenses(row)
          // Доход: маржинальность; расходы: их доля в доходе объекта (если доход есть)
          const extra = revenue ? rowMargin(row) : n(row.revenue) > 0 ? value / n(row.revenue) : null
          return { store: row.store, value, extra }
        })
        .filter((item) => item.value > 0)
        .sort((a, b) => b.value - a.value)
      const total = rows.reduce((sum, item) => sum + item.value, 0)
      return rows.map((item, index) => ({ ...item, share: total ? item.value / total : 0, rank: index + 1 }))
    },

    total() {
      return this.items.reduce((sum, item) => sum + item.value, 0)
    },

    topShare() {
      return this.items.slice(0, 3).reduce((sum, item) => sum + item.share, 0)
    },

    // Телефон (как в стилях: уже 600px)
    phone() {
      return this.$vuetify.display.xs
    },

    // Объекты, которые на телефоне не показаны плитками (null — показаны все)
    rest() {
      if (this.items.length <= PHONE_TILES + 1) return null
      const list = this.items.slice(PHONE_TILES)
      return { count: list.length, value: list.reduce((sum, item) => sum + item.value, 0), share: list.reduce((sum, item) => sum + item.share, 0) }
    },

    tileItems() {
      const palette = COLORS[this.kind]
      const list = this.phone && this.rest && !this.expanded ? this.items.slice(0, PHONE_TILES) : this.items
      return list.map((item, index) => ({
        id: item.store,
        label: item.store,
        value: item.value,
        share: item.share,
        rank: item.rank,
        extra: item.extra,
        color: palette[index % palette.length],
      }))
    },
  },
}
</script>

