<template>
  <div class="glass" :class="{ 'glass--ready': ready }">
    <!-- Легенда: нажатие скрывает или возвращает ряд (как в Chart.js) -->
    <ul class="glass__legend">
      <li v-for="item in series" :key="item.id">
        <button
          type="button"
          class="glass__legend-item"
          :class="{ 'glass__legend-item--off': off.includes(item.id) }"
          :aria-pressed="!off.includes(item.id)"
          @click="toggle(item.id)"
        >
          <i :style="{ background: item.color }" aria-hidden="true"></i>
          {{ item.label }}
        </button>
      </li>
    </ul>

    <div class="glass__plot" :style="{ height: `${height}px` }">
      <!-- Сетка и подписи шкалы -->
      <div class="glass__grid" aria-hidden="true">
        <div v-for="tick in ticks" :key="tick.value" class="glass__tick" :style="{ bottom: `${tick.pct}%` }">
          <span>{{ tickFormat(tick.value) }}</span>
        </div>
      </div>

      <!-- Группы (периоды или категории): столбцы рядов вплотную друг к другу -->
      <div class="glass__groups">
        <div v-for="column in columns" :key="column.group" class="glass__group">
          <div
            v-for="bar in column.bars"
            :key="bar.id"
            class="glass__slot"
            :class="{ 'glass__slot--off': off.includes(bar.id) }"
            :style="{ '--c': bar.color }"
            @pointerenter="hover = bar.key"
            @pointerleave="hover = null"
          >
            <div
              v-if="bar.value !== null"
              class="glass__tube"
              :class="{ 'glass__tube--hover': hover === bar.key }"
              :style="{ height: `${ready ? pct(bar.value) : 0}%` }"
              role="img"
              :aria-label="`${column.group}, ${bar.label}: ${bar.full}`"
            >
              <span class="glass__label">{{ bar.text }}</span>
              <span class="glass__liquid" aria-hidden="true">
                <i v-for="bubble in bar.bubbles" :key="bubble.key" class="glass__bubble" :style="bubble.style"></i>
              </span>
              <span class="glass__shine" aria-hidden="true"></span>
              <span class="glass__side" aria-hidden="true"></span>
              <span class="glass__top" aria-hidden="true"></span>

              <!-- Подсказка с полным значением -->
              <span v-if="hover === bar.key" class="glass__tip">
                <b>{{ bar.label }}</b>
                {{ bar.full }}
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div class="glass__axis" aria-hidden="true">
      <span v-for="group in groups" :key="group">{{ group }}</span>
    </div>
  </div>
</template>

<script>
// Стеклянные 3D-столбцы: прямоугольный блок из стекла (передняя, боковая и верхняя грани), доверху залитый яркой
// жидкостью цвета ряда, с бликом и пузырьками.
// groups — подписи групп по оси (периоды или категории); series — [{ id, label, color }];
// values[ряд][группа] — число или null. Нажатие на пункт легенды скрывает ряд: оставшиеся столбцы сдвигаются,
// шкала пересчитывается по видимым значениям — всё плавно, через CSS
export default {
  name: 'GlassBars',

  props: {
    groups: {
      type: Array,
      required: true,
    },
    series: {
      type: Array,
      required: true,
    },
    values: {
      type: Array,
      required: true,
    },
    // Подпись над столбцом, подпись шкалы и полное значение в подсказке
    valueFormat: {
      type: Function,
      required: true,
    },
    tickFormat: {
      type: Function,
      required: true,
    },
    fullFormat: {
      type: Function,
      required: true,
    },
    height: {
      type: Number,
      default: 240,
    },
  },

  data() {
    return {
      // Скрытые ряды (id)
      hidden: [],
      hover: null,
      // Столбцы «наливаются» после появления на странице
      ready: false,
    }
  },

  computed: {
    // Скрытые ряды, которые сейчас есть на графике (ряд мог пропасть при смене данных — он не считается скрытым)
    off() {
      return this.hidden.filter((id) => this.series.some((item) => item.id === id))
    },

    // Столбцы по группам: значение, подписи и пузырьки считаются один раз
    columns() {
      return this.groups.map((group, groupIndex) => ({
        group,
        bars: this.series.map((item, seriesIndex) => {
          const raw = (this.values[seriesIndex] || [])[groupIndex]
          const value = typeof raw === 'number' ? raw : null
          return {
            id: item.id,
            key: `${groupIndex}:${item.id}`,
            label: item.label,
            color: item.color,
            value,
            text: value === null ? '' : this.valueFormat(value),
            full: value === null ? '' : this.fullFormat(value),
            bubbles: this.bubbles(seriesIndex, groupIndex),
          }
        }),
      }))
    },

    // Верх шкалы — «круглое» число над наибольшим видимым значением
    scale() {
      const visible = this.series.map((item, index) => (this.off.includes(item.id) ? [] : this.values[index] || [])).flat()
      const max = Math.max(0, ...visible.filter((value) => typeof value === 'number'))
      if (!max) return { top: 1, step: 0.25 }
      const raw = (max * 1.08) / 4
      const power = 10 ** Math.floor(Math.log10(raw))
      const mantissa = raw / power
      const step = (mantissa <= 1 ? 1 : mantissa <= 2 ? 2 : mantissa <= 2.5 ? 2.5 : mantissa <= 5 ? 5 : 10) * power
      return { top: step * 4, step }
    },

    ticks() {
      return [0, 1, 2, 3, 4].map((index) => ({ value: this.scale.step * index, pct: (this.scale.step * index * 100) / this.scale.top }))
    },
  },

  mounted() {
    // Сначала столбцы пустые (высота 0), затем плавно поднимаются до значений
    requestAnimationFrame(() => requestAnimationFrame(() => (this.ready = true)))
    // В фоновой вкладке кадры не идут — через полсекунды столбцы показываются в любом случае
    this.readyTimer = setTimeout(() => (this.ready = true), 500)
  },

  beforeUnmount() {
    clearTimeout(this.readyTimer)
  },

  methods: {
    pct(value) {
      return Math.max(1.5, (Math.max(0, value) / this.scale.top) * 100)
    },

    toggle(id) {
      // Последний видимый ряд не скрывается — иначе график пустой
      if (this.off.includes(id)) this.hidden = this.off.filter((item) => item !== id)
      else if (this.off.length < this.series.length - 1) this.hidden = [...this.off, id]
    },

    // Пузырьки: размер, место и скорость — постоянные для каждого столбца (не меняются при перерисовке)
    bubbles(seriesIndex, groupIndex) {
      const seed = seriesIndex * 7 + groupIndex * 13
      return [0, 1, 2, 3].map((index) => {
        const n = seed + index * 31
        return {
          key: index,
          style: {
            left: `${15 + ((n * 37) % 60)}%`,
            width: `${3 + (n % 4)}px`,
            height: `${3 + (n % 4)}px`,
            animationDuration: `${3.2 + ((n * 7) % 30) / 10}s`,
            animationDelay: `${-((n * 11) % 40) / 10}s`,
          },
        }
      })
    },
  },
}
</script>

