<template>
  <section class="cmp-metrics" :aria-label="$t('compare.metrics')">
    <compare-metric-chart v-for="(metric, index) in metrics" :key="metric.id" :metric="metric" :periods="periods" :rows="rows" :index="index" />
  </section>
</template>

<script>
import { mapState } from 'pinia'
import CompareMetricChart from '@/components/CompareMetricChart.vue'
import { useCompareStore } from '@/stores/compare'
import { channelMetrics, metricsFor } from '@/utils/compare'

// Показатели главной по выбранным периодам: карточка с графиком на каждый показатель, две в ряд.
// channels — вместо общих показателей каналы продаж (интернет-магазин, мономаркет)
export default {
  name: 'CompareMetrics',

  components: { CompareMetricChart },

  props: {
    channels: {
      type: Boolean,
      default: false,
    },
  },

  computed: {
    ...mapState(useCompareStore, ['periods', 'rowOf']),

    metrics() {
      return this.channels ? channelMetrics() : metricsFor()
    },

    // Строки таблицы выбранной области по периодам
    rows() {
      return this.periods.map((time) => this.rowOf(time))
    },
  },
}
</script>

<style lang="scss" scoped>
.cmp-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: $spacer * 5;
  width: 100%;
