<template>
  <section class="yoy" :aria-label="$t('results.yoy.title')">
    <article v-for="panel in panels" :key="panel.id" class="yoy__panel">
      <panel-head :icon="panel.icon" :title="$t(panel.title)" :period="period">
        <div class="yoy__total" :class="panel.total === null ? null : panel.total >= 0 ? 'yoy__total--up' : 'yoy__total--down'">
          <span>{{ $t('results.yoy.network') }}</span>
          <b>{{ signed(panel.total) }}</b>
        </div>
      </panel-head>

      <div class="yoy__summary">
        <span class="yoy__count yoy__count--up">▲ {{ $t('results.yoy.grew', { n: panel.grew }) }}</span>
        <span class="yoy__count yoy__count--down">▼ {{ $t('results.yoy.fell', { n: panel.fell }) }}</span>
        <!-- Шкала цвета: от худшего значения через порог (жёлтый) к лучшему -->
        <span class="yoy__hint">
          <span>{{ signed(panel.low) }}</span>
          <i class="yoy__scale" :style="{ background: panel.scale }" aria-hidden="true"></i>
          <span>{{ signed(panel.high) }}</span>
        </span>
      </div>

      <p v-if="!panel.rows.length" class="yoy__empty">{{ $t('results.yoy.empty') }}</p>

      <ol v-else class="yoy__list">
        <template v-for="row in panel.visible" :key="row.store || row.gap">
          <!-- Пропуск между лучшими и худшими, пока список свёрнут -->
          <li v-if="row.gap" class="yoy__gap">
            <button type="button" class="yoy__more" @click="expanded = true">
              {{ $t('results.yoy.showAll', { n: panel.rows.length }) }}
            </button>
          </li>

          <li
            v-else
            class="yoy__row"
            :class="{ 'yoy__row--hover': hovered === row.store }"
            :style="{ '--tone': row.rgb }"
            @pointerenter="hovered = row.store"
            @pointerleave="hovered = null"
          >
            <span class="yoy__rank">{{ row.rank }}</span>
            <span class="yoy__name" :title="row.store">{{ row.store }}</span>
            <span class="yoy__track" aria-hidden="true">
              <i class="yoy__zero" :style="{ left: `${panel.zero}%` }"></i>
              <i class="yoy__bar" :style="barStyle(panel, row.value)"></i>
            </span>
            <span class="yoy__value">{{ signed(row.value) }}</span>
          </li>
        </template>
      </ol>

      <button v-if="expanded && panel.collapsible" type="button" class="yoy__more yoy__more--end" @click="expanded = false">
        {{ $t('results.yoy.collapse') }}
      </button>
    </article>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiAccountGroupOutline, mdiCashMultiple } from '@mdi/js'
import PanelHead from '@/components/PanelHead.vue'
import { RESULTS } from '@/configurations'
import { useResultsStore } from '@/stores/results'
import { useScopeStore } from '@/stores/scope'
import { centeredGradientRgb, gradientRgb } from '@/utils/color'
import { numberFormat } from '@/utils/format'
import { animateProgress } from '@/utils/tween'

// Итоговая строка таблицы yoy — вся сеть, а не магазин
const TOTAL_ROW = 'Ітогові'
// В свёрнутом списке: сколько лучших и сколько худших магазинов показать
const TOP = 10
const BOTTOM = 5

// field — столбец таблицы yoy (рост в долях: 0,22 → +22 %); good — рост в процентах, на котором цвет жёлтый:
// ниже — от красного к жёлтому, выше — от жёлтого к зелёному (как в прежней версии страницы)
const PANELS = [
  { id: 'revenue', title: 'results.yoy.revenue', icon: mdiCashMultiple, field: 'revenue_yoy', good: RESULTS.YOY_GOOD.REVENUE },
  { id: 'traffic', title: 'results.yoy.traffic', icon: mdiAccountGroupOutline, field: 'traffic_yoy', good: RESULTS.YOY_GOOD.TRAFFIC },
]

export default {
  name: 'ResultsYoy',

  components: { PanelHead },

  data() {
    return {
      // Раскрыт ли полный список. Раскрываются обе панели сразу: они стоят рядом и должны быть одной высоты
      expanded: false,
      // Магазин под курсором: подсвечивается сразу в обеих панелях
      hovered: null,
      progress: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    locale() {
      return this.$i18n.locale
    },

    panels() {
      const rows = useResultsStore().rowsOf('yoy', this.period)
      const totalRow = rows.find((row) => row.store === TOTAL_ROW)

      return PANELS.map((panel) => {
        const list = rows
          .filter((row) => row.store !== TOTAL_ROW && typeof row[panel.field] === 'number')
          .map((row) => ({ store: row.store, value: row[panel.field] * 100 }))
          .sort((a, b) => b.value - a.value)

        // Шкала от наименьшего до наибольшего значения, ноль всегда на шкале
        const min = Math.min(0, ...list.map((row) => row.value))
        const max = Math.max(0, ...list.map((row) => row.value))
        const span = max - min || 1
        // Цвет — по реальному разбросу значений (как в прежней версии), шкала столбиков — от нуля
        const low = list.length ? list[list.length - 1].value : 0
        const high = list.length ? list[0].value : 0
        const colored = list.map((row, index) => ({ ...row, rank: index + 1, rgb: centeredGradientRgb(row.value, low, high, panel.good) }))
        const collapsible = colored.length > TOP + BOTTOM + 1
        const visible =
          collapsible && !this.expanded ? [...colored.slice(0, TOP), { gap: `gap-${panel.id}` }, ...colored.slice(-BOTTOM)] : colored
        // Полоса легенды: те же цвета, жёлтый — в точке порога
        const center = high > low ? Math.min(100, Math.max(0, ((panel.good - low) / (high - low)) * 100)) : 50
        const scale = `linear-gradient(90deg, rgb(${gradientRgb(0)}), rgb(${gradientRgb(0.5)}) ${center}%, rgb(${gradientRgb(1)}))`
        const total = totalRow && typeof totalRow[panel.field] === 'number' ? totalRow[panel.field] * 100 : null

        return {
          ...panel,
          rows: colored,
          visible,
          collapsible,
          min,
          span,
          low,
          high,
          scale,
          zero: (-min / span) * 100,
          total,
          grew: list.filter((row) => row.value > 0).length,
          fell: list.filter((row) => row.value < 0).length,
        }
      })
    },
  },

  watch: {
    period: {
      immediate: true,
      handler() {
        if (this.stopTween) this.stopTween()
        this.stopTween = animateProgress((progress) => (this.progress = progress), { delay: 150 })
      },
    },
  },

  beforeUnmount() {
    if (this.stopTween) this.stopTween()
  },

  methods: {
    signed(value) {
      if (value === null) return '—'
      const text = numberFormat(this.$i18n.locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(Math.abs(value))
      return `${value > 0 ? '+' : value < 0 ? '−' : ''}${text}%`
    },

    // Столбик от нуля вправо (рост) или влево (падение)
    barStyle(panel, value) {
      const width = (Math.abs(value) / panel.span) * 100 * this.progress
      return value >= 0 ? { left: `${panel.zero}%`, width: `${width}%` } : { right: `${100 - panel.zero}%`, width: `${width}%` }
    },
  },
}
</script>

