// Раскладка treemap по алгоритму squarified: прямоугольники максимально близки к квадрату, поэтому их легче
// сравнивать и в них помещается подпись. items — [{ value, ... }] с value > 0, в любом порядке.
// Возвращает [{ item, x, y, w, h }] в координатах width × height, от большего значения к меньшему.
function squarify(items, width, height) {
  const list = items.filter((item) => item.value > 0).sort((a, b) => b.value - a.value)
  const total = list.reduce((sum, item) => sum + item.value, 0)
  if (!total || width <= 0 || height <= 0) return []

  const scale = (width * height) / total
  const cells = list.map((item) => ({ item, area: item.value * scale }))
  const result = []
  let rect = { x: 0, y: 0, w: width, h: height }
  let row = []

  for (let index = 0; index < cells.length; ) {
    const side = Math.min(rect.w, rect.h)
    const next = [...row, cells[index]]
    if (!row.length || worst(next, side) <= worst(row, side)) {
      row = next
      index += 1
    } else {
      rect = place(row, rect, result)
      row = []
    }
  }
  if (row.length) place(row, rect, result)
  return result
}

// Худшее соотношение сторон в ряду: чем ближе к 1, тем квадратнее прямоугольники
function worst(row, side) {
  const sum = row.reduce((acc, cell) => acc + cell.area, 0)
  const max = Math.max(...row.map((cell) => cell.area))
  const min = Math.min(...row.map((cell) => cell.area))
  return Math.max((side * side * max) / (sum * sum), (sum * sum) / (side * side * min))
}

// Кладёт ряд вдоль короткой стороны и возвращает оставшийся прямоугольник
function place(row, rect, result) {
  const sum = row.reduce((acc, cell) => acc + cell.area, 0)
  if (rect.w >= rect.h) {
    const width = sum / rect.h
    let y = rect.y
    for (const cell of row) {
      const h = cell.area / width
      result.push({ item: cell.item, x: rect.x, y, w: width, h })
      y += h
    }
    return { x: rect.x + width, y: rect.y, w: rect.w - width, h: rect.h }
  }
  const height = sum / rect.w
  let x = rect.x
  for (const cell of row) {
    const w = cell.area / height
    result.push({ item: cell.item, x, y: rect.y, w, h: height })
    x += w
  }
  return { x: rect.x, y: rect.y + height, w: rect.w, h: rect.h - height }
}

// Плитки treemap для отрисовки: раскладка squarified с промежутками gap между плитками и подписью по размеру плитки.
//  items    — [{ value, ... }], value > 0
//  minArea  — наименьшая доля площади плитки: крошечные доли (0,01 %) иначе были бы тоньше промежутка и пропали бы.
//             Размер такой плитки чуть больше настоящей пропорции; value в результате — настоящее
//  labels   — [{ id, w, h }] от крупной подписи к мелкой: у плитки подпись первого правила, в которое она помещается
// Возвращает [{ item, x, y, w, h, label }], где w и h — размер плитки без промежутка.
export function layoutTiles(items, width, height, { gap = 3, minArea = 0, labels = [] } = {}) {
  const total = items.reduce((sum, item) => sum + item.value, 0)
  const sized = items.map((item) => ({ item, value: Math.max(item.value, total * minArea) }))
  // Раскладка на область шире на промежуток: у крайних плиток промежуток уходит за край, и они стоят ровно по краям
  return squarify(sized, width + gap, height + gap)
    .filter(({ w, h }) => w > gap + 1 && h > gap + 1)
    .map(({ item: { item }, x, y, w, h }) => {
      const inner = { w: w - gap, h: h - gap }
      const label = (labels.find((rule) => inner.w >= rule.w && inner.h >= rule.h) || {}).id || null
      return { item, x, y, w: inner.w, h: inner.h, label }
    })
}
