<template>
  <section class="bkpi" :aria-label="$t('budget.kpi.title')">
    <!-- Четыре показателя P&L сети: доход, валовая прибыль, расходы, чистая прибыль -->
    <div class="bkpi__cards">
      <article
        v-for="(card, index) in cards"
        :key="card.id"
        class="bkpi-card"
        :class="`bkpi-card--${card.tone}`"
        :style="{ '--i': index }"
      >
        <span class="bkpi-card__ring" aria-hidden="true"></span>

        <header class="bkpi-card__head">
          <span class="bkpi-card__icon" aria-hidden="true">
            <v-icon :icon="card.icon" size="20" />
          </span>
          <h3 class="bkpi-card__label">{{ $t(card.label) }}</h3>
        </header>

        <strong class="bkpi-card__value">
          {{ money(card.value * progress) }}
          <small>{{ $t('kpi.uah') }}</small>
        </strong>

        <!-- Изменение к прошлому месяцу -->
        <footer v-if="card.delta" class="bkpi-card__foot">
          <span class="bkpi-card__delta" :class="`bkpi-card__delta--${card.delta.mood}`">
            <span aria-hidden="true">{{ card.delta.arrow }}</span>
            {{ card.delta.text }}
          </span>
          <span class="bkpi-card__prev">{{ $t('budget.kpi.vsPrev', { period: previousPeriod }) }}</span>
        </footer>
      </article>
    </div>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiAlertOctagonOutline, mdiCashMinus, mdiCashMultiple, mdiStarCircleOutline, mdiTrendingUp } from '@mdi/js'
import numberFormatMixin from '@/mixins/numberFormat'
import { useBudgetStore } from '@/stores/budget'
import { useScopeStore } from '@/stores/scope'
import { networkTotals } from '@/utils/budget'
import { animateProgress } from '@/utils/tween'

// Изменение меньше 0,1 % — «без изменений»: стрелка не дёргается на шуме
const NEUTRAL = 0.1

export default {
  name: 'BudgetKpi',

  mixins: [numberFormatMixin],

  data() {
    return {
      // Ход анимации появления от 0 до 1: «набегают» числа
      progress: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),
    ...mapState(useBudgetStore, ['rows', 'periods']),

    totals() {
      return this.rows ? networkTotals(useBudgetStore().rowsOf(this.period)) : null
    },

    // Прошлый месяц в порядке таблицы
    previousPeriod() {
      const index = this.periods.findIndex((item) => item.time === this.period)
      return index > 0 ? this.periods[index - 1].time : ''
    },

    previousTotals() {
      return this.previousPeriod ? networkTotals(useBudgetStore().rowsOf(this.previousPeriod)) : null
    },

    // Карточки. Цвета — как на прежней странице: синий, зелёный, оранжевый; чистая прибыль фиолетовая, убыток красный.
    // less — показатель, у которого рост плохой (расходы)
    cards() {
      if (!this.totals) return []
      const { revenue, profit, expenses, net } = this.totals
      const past = this.previousTotals || {}
      return [
        { id: 'revenue', label: 'budget.kpi.revenue', icon: mdiCashMultiple, tone: 'blue', value: revenue, delta: this.delta(revenue, past.revenue) },
        { id: 'profit', label: 'budget.kpi.profit', icon: mdiTrendingUp, tone: 'green', value: profit, delta: this.delta(profit, past.profit) },
        { id: 'expenses', label: 'budget.kpi.expenses', icon: mdiCashMinus, tone: 'orange', value: expenses, delta: this.delta(expenses, past.expenses, true) },
        {
          id: 'net',
          label: net >= 0 ? 'budget.kpi.net' : 'budget.kpi.loss',
          icon: net >= 0 ? mdiStarCircleOutline : mdiAlertOctagonOutline,
          tone: net >= 0 ? 'purple' : 'red',
          value: net,
          delta: this.delta(net, past.net),
        },
      ]
    },

    // Меняется, когда пришли другие значения: тогда анимация проигрывается заново
    signature() {
      return this.totals ? `${this.period}|${this.totals.revenue}|${this.totals.net}` : ''
    },
  },

  watch: {
    signature: {
      immediate: true,
      handler(value) {
        if (this.stopTween) this.stopTween()
        if (value) this.stopTween = animateProgress((progress) => (this.progress = progress), { delay: 150 })
      },
    },
  },

  beforeUnmount() {
    if (this.stopTween) this.stopTween()
  },

  methods: {
    // Изменение к прошлому месяцу: в процентах, а если прошлое значение не положительное (была прибыль — стал убыток
    // или наоборот) — суммой. mood: good / bad / flat; для расходов (less) рост — плохо
    delta(current, previous, less = false) {
      if (typeof previous !== 'number') return null
      const diff = current - previous
      const byPercent = previous > 0 && current >= 0
      const size = byPercent ? (diff / previous) * 100 : diff
      if (diff === 0 || (byPercent && Math.abs(size) < NEUTRAL)) {
        return { arrow: '●', mood: 'flat', text: byPercent ? this.percent(0) : this.compact(0) }
      }
      const up = diff > 0
      const sign = up ? '+' : '−'
      const text = byPercent ? `${sign}${this.percent(Math.abs(size))}` : `${sign}${this.compact(Math.abs(diff))}`
      return { arrow: up ? '▲' : '▼', mood: up !== less ? 'good' : 'bad', text }
    },
  },
}
</script>

