<template>
  <section class="credit" :aria-label="$t('results.credit.title')">
    <!-- Сводка: всего и соотношение оплаты частями и кредитных программ -->
    <div class="credit__summary">
      <div class="credit__total">
        <span class="credit__label">{{ $t('results.credit.total') }}</span>
        <strong class="credit__money">
          {{ money(total * progress) }}
          <small>{{ $t('kpi.uah') }}</small>
        </strong>
      </div>

      <div class="credit__split">
        <div class="credit__track" role="img" :aria-label="splitLabel">
          <i
            v-for="group in groups"
            :key="group.id"
            class="credit__part"
            :style="{ '--accent': group.accent, width: `${group.share * 100 * progress}%` }"
          ></i>
        </div>

        <ul class="credit__legend">
          <li v-for="group in groups" :key="group.id" class="credit__legend-item" :style="{ '--accent': group.accent }">
            <i class="credit__swatch" aria-hidden="true"></i>
            <span class="credit__legend-name">{{ $t(group.title) }}</span>
            <b>{{ money(group.total) }}</b>
            <span class="credit__legend-share">{{ percent(group.share * 100) }}</span>
          </li>
        </ul>
      </div>
    </div>

    <!-- Рейтинг банков в каждой группе -->
    <div class="credit__lists">
      <article
        v-for="group in groups"
        :key="group.id"
        class="credit__panel"
        :style="{ '--accent': group.accent }"
      >
        <panel-head :icon="group.icon" :title="$t(group.title)" :period="period">
          <div class="credit__head-sum">
            <b>{{ money(group.total) }}</b>
            <span>{{ $t('kpi.uah') }} · {{ $t('results.credit.banks', { n: group.items.length }) }}</span>
          </div>
        </panel-head>

        <p v-if="!group.items.length" class="credit__empty">{{ $t('results.credit.empty') }}</p>

        <ol v-else class="credit__list">
          <li
            v-for="(item, index) in group.items"
            :key="item.name"
            class="credit__row"
            :class="{ 'credit__row--leader': index === 0 }"
            :style="{ '--i': index }"
          >
            <span class="credit__rank">{{ index + 1 }}</span>
            <span class="credit__name" :title="item.fullName">{{ item.name }}</span>
            <span class="credit__bar" aria-hidden="true">
              <i :style="{ width: `${(item.sum / group.max) * 100 * progress}%` }"></i>
            </span>
            <span class="credit__sum">{{ money(item.sum) }}</span>
            <span class="credit__meta">
              <span class="credit__share">{{ percent(item.share * 100) }}</span>
              <span
                v-if="item.delta !== null"
                class="credit__delta"
                :class="item.delta >= 0 ? 'credit__delta--up' : 'credit__delta--down'"
                :title="$t('results.credit.vsPrev')"
              >
                <span aria-hidden="true">{{ item.delta >= 0 ? '▲' : '▼' }}</span>
                {{ Math.abs(Math.round(item.delta)) }}%
              </span>
              <span v-else-if="item.isNew" class="credit__delta credit__delta--new">{{ $t('results.credit.new') }}</span>
            </span>
          </li>
        </ol>
      </article>
    </div>

    <p v-if="previous" class="credit__note">{{ $t('results.credit.deltaNote', { period: previous }) }}</p>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiBankOutline, mdiCreditCardClockOutline } from '@mdi/js'
import PanelHead from '@/components/PanelHead.vue'
import { useResultsStore } from '@/stores/results'
import { useScopeStore } from '@/stores/scope'
import { animateProgress } from '@/utils/tween'
import numberFormatMixin from '@/mixins/numberFormat'

// Две группы строк таблицы credits. В одной строке таблицы бывают обе: кредит банка и его оплата частями.
//  name / sum — столбцы названия и суммы; prefix — повтор названия группы в названии банка («ОЧ Приват»), его не показываем;
//  accent — цвет группы (RGB через запятую)
const GROUPS = [
  { id: 'parts', title: 'results.credit.parts', icon: mdiCreditCardClockOutline, name: 'oc_bank', sum: 'oc_sum', prefix: /^ОЧ\s+/i, accent: '139, 92, 246' },
  { id: 'programs', title: 'results.credit.programs', icon: mdiBankOutline, name: 'bank', sum: 'credit_sum', prefix: null, accent: '245, 158, 11' },
]

const isSum = (value) => typeof value === 'number' && Number.isFinite(value)
// «-» в столбце банка означает, что кредитной программы в этой строке нет
const hasName = (value) => typeof value === 'string' && value.trim() !== '' && value.trim() !== '-'

// Банки группы за период: { fullName, name, sum }, по убыванию суммы
function collect(rows, group) {
  return rows
    .filter((row) => hasName(row[group.name]) && isSum(row[group.sum]))
    .map((row) => {
      const fullName = row[group.name]
      return { fullName, name: group.prefix ? fullName.replace(group.prefix, '') : fullName, sum: row[group.sum] }
    })
    .sort((a, b) => b.sum - a.sum)
}

export default {
  name: 'ResultsCredit',

  mixins: [numberFormatMixin],

  components: { PanelHead },

  data() {
    return {
      progress: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),
    ...mapState(useResultsStore, ['periods']),

    locale() {
      return this.$i18n.locale
    },

    // Предыдущий период по порядку таблицы: с ним сравниваются суммы банков
    previous() {
      const index = this.periods.findIndex((item) => item.time === this.period)
      return index > 0 ? this.periods[index - 1].time : ''
    },

    groups() {
      const store = useResultsStore()
      const rows = store.rowsOf('credits', this.period)
      const before = this.previous ? store.rowsOf('credits', this.previous) : []
      const lists = GROUPS.map((group) => ({ group, items: collect(rows, group), past: collect(before, group) }))
      const all = lists.reduce((sum, list) => sum + list.items.reduce((acc, item) => acc + item.sum, 0), 0)

      return lists.map(({ group, items, past }) => {
        const total = items.reduce((acc, item) => acc + item.sum, 0)
        const pastSums = Object.fromEntries(past.map((item) => [item.fullName, item.sum]))
        return {
          ...group,
          total,
          share: all ? total / all : 0,
          max: items.length ? items[0].sum : 1,
          items: items.map((item) => {
            const was = pastSums[item.fullName]
            return {
              ...item,
              share: total ? item.sum / total : 0,
              delta: isSum(was) && was !== 0 ? (item.sum / was - 1) * 100 : null,
              isNew: !!this.previous && was === undefined,
            }
          }),
        }
      })
    },

    total() {
      return this.groups.reduce((sum, group) => sum + group.total, 0)
    },

    splitLabel() {
      return this.groups.map((group) => `${this.$t(group.title)}: ${this.percent(group.share * 100)}`).join(', ')
    },

    // Меняется, когда пришли другие данные: анимация проигрывается заново
    signature() {
      return `${this.period}|${this.total}`
    },
  },

  watch: {
    signature: {
      immediate: true,
      handler() {
        if (this.stopTween) this.stopTween()
        this.stopTween = animateProgress((progress) => (this.progress = progress), { delay: 150 })
      },
    },
  },

  beforeUnmount() {
    if (this.stopTween) this.stopTween()
  },

}
</script>

