import { createRouter, createWebHistory } from 'vue-router'
import { MANAGERS, managerPermission, PERMISSIONS } from '@/configurations'
import { useAccessStore } from '@/stores/access'
import { PAGE_NAMES, useSourcesStore } from '@/stores/sources'
import DashboardLayout from '@/layouts/DashboardLayout.vue'
import HomeView from '@/views/HomeView.vue'
import BudgetView from '@/views/BudgetView.vue'
import CompareView from '@/views/CompareView.vue'
import ResultsView from '@/views/ResultsView.vue'

// meta.public — страница доступна без входа.
// meta.title — ключ перевода заголовка страницы в шапке
// meta.permission — страница доступна только с этим правом: { permission: PERMISSIONS.<ПРАВО> }
// Страница менеджера /manager/:id проверяется правом managerPermission(id): оно вычисляется из адреса, поэтому новый
// менеджер из MANAGERS получает свою страницу без правок здесь.
const routes = [
  {
    path: '/login',
    name: 'login',
    component: () => import('@/views/LoginView.vue'),
    meta: { public: true },
  },
  {
    // Все закрытые страницы живут внутри общего макета: шапка, сайдбар, подвал
    path: '/',
    component: DashboardLayout,
    children: [
      {
        path: '',
        name: 'home',
        component: HomeView,
        meta: { title: 'home.title', permission: PERMISSIONS.DASHBOARD_VIEW },
      },
      {
        // Страница менеджера: те же блоки, что на главной, но по данным менеджера и его магазинов
        path: 'manager/:id',
        name: 'manager',
        component: HomeView,
      },
      {
        path: 'compare',
        name: 'compare',
        component: CompareView,
        meta: { title: 'nav.compare', permission: PERMISSIONS.COMPARE_VIEW },
      },
      {
        // Страницы подключены сразу, а не лениво: ленивый компонент внутри <transition mode="out-in"> оставляет пустую страницу
        path: 'budget',
        name: 'budget',
        component: BudgetView,
        meta: { title: 'nav.budget', permission: PERMISSIONS.BUDGET_VIEW },
      },
      {
        path: 'results',
        name: 'results',
        component: ResultsView,
        meta: { title: 'nav.results', permission: PERMISSIONS.RESULTS_VIEW },
      },
      {
        path: 'forbidden',
        name: 'forbidden',
        component: () => import('@/views/ForbiddenView.vue'),
        meta: { title: 'forbidden.title' },
      },
    ],
  },
  {
    path: '/:pathMatch(.*)*',
    redirect: '/',
  },
]

const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes,
  // Новая страница открывается с самого верха; кнопки «назад/вперёд» возвращают на прежнее место
  scrollBehavior: (to, from, saved) => saved || { left: 0, top: 0 },
})

// Право на страницу: явное из meta или, для страницы менеджера, право на этого менеджера.
// Неизвестный менеджер (нет в MANAGERS) — страницы не существует.
function permissionOf(to) {
  if (to.name === 'manager') {
    return MANAGERS.some((manager) => manager.id === to.params.id) ? managerPermission(to.params.id) : null
  }
  return to.meta.permission
}

// Можно ли текущему пользователю оставаться на странице. Нужна и при смене роли без перехода (сверка с таблицей,
// вход под другой ролью в соседней вкладке), поэтому вынесена из охранника.
export function canOpen(to) {
  const access = useAccessStore()
  if (to.meta.public) return true
  if (!access.isAuthenticated) return false
  if (to.name === 'manager' && !MANAGERS.some((manager) => manager.id === to.params.id)) return false
  // «Нет доступа» — только для тех, кому больше некуда идти; у остальных адрес ведёт на их «домашнюю» страницу
  if (to.name === 'forbidden') return access.homeRoute.name === 'forbidden'
  return access.can(permissionOf(to))
}

// Куда вести после входа: на страницу из ?redirect=, если это закрытая страница самого сайта и она доступна,
// иначе на «домашнюю» страницу роли. Внешние адреса отбрасываются, чтобы ссылкой нельзя было увести наружу.
export function afterLoginRoute(query) {
  const access = useAccessStore()
  const { redirect } = query
  if (typeof redirect === 'string' && redirect.startsWith('/') && !redirect.startsWith('//')) {
    const route = router.resolve(redirect)
    if (route.matched.length && !route.meta.public && canOpen(route)) return route.fullPath
  }
  return access.homeRoute
}

router.beforeEach(async (to, from) => {
  const access = useAccessStore()
  // Любая страница ждёт сверки входа с таблицей: роль в браузере можно подменить, роль из таблицы — нет.
  // Пока идёт сверка, App.vue показывает заставку.
  await access.restoreSession()

  // Уходим со страницы со своими данными, пока они грузятся (например, «Назад»): её прелоадер закрывается
  PAGE_NAMES.filter((page) => page !== to.name).forEach((page) => useSourcesStore().leavePage(page))

  if (to.meta.public) {
    return to.name === 'login' && access.isAuthenticated ? afterLoginRoute(to.query) : true
  }

  if (!access.isAuthenticated) {
    return { name: 'login', query: to.fullPath === '/' ? {} : { redirect: to.fullPath } }
  }

  // Несуществующий менеджер, страница без права и «Нет доступа» при наличии доступных страниц ведут
  // на «домашнюю» страницу пользователя
  if (!canOpen(to)) return access.homeRoute

  // Итоги и бюджет открываются только с загруженными данными: пока они грузятся, виден прелоадер.
  // Ждать в охраннике можно только при переходе внутри дашборда: прелоадер — часть макета. При открытии сайта сразу
  // на этой странице или со страницы входа макета ещё нет — тогда страница рисуется под общим прелоадером,
  // в котором её данные стоят отдельной строкой
  if (PAGE_NAMES.includes(to.name)) {
    const loading = useSourcesStore().needPage(to.name)
    const insideDashboard = from.matched.some((record) => record.components && record.components.default === DashboardLayout)
    if (insideDashboard) await loading
  }
  return true
})

export default router
