<template>
  <!-- Язык интерфейса: в сайдбаре над карточкой пользователя. Широкий сайдбар — плашка с названием языка, список
       раскрывается вверх; узкий (только иконки) — круглая кнопка с кодом, список сбоку -->
  <v-menu :location="rail ? 'end' : 'top'" :offset="rail ? 12 : 8" transition="scale-transition">
    <template #activator="{ props, isActive }">
      <button
        v-bind="props"
        type="button"
        class="lang"
        :class="{ 'lang--open': isActive, 'lang--rail': rail }"
        :aria-label="`${$t('common.language')}: ${current.title}`"
      >
        <span class="lang__badge">
          <v-icon :icon="mdiTranslate" size="16" />
        </span>
        <template v-if="!rail">
          <span class="lang__text">
            <span class="lang__caption">{{ $t('common.language') }}</span>
            <transition name="lang-swap" mode="out-in">
              <span :key="locale" class="lang__current">{{ current.title }}</span>
            </transition>
          </span>
          <span class="lang__code">{{ locale.toUpperCase() }}</span>
          <v-icon :icon="mdiChevronUp" size="18" class="lang__arrow" />
        </template>
        <v-tooltip v-else activator="parent" location="end" :text="`${$t('common.language')}: ${current.title}`" />
      </button>
    </template>

    <v-card class="lang__card" rounded="xl" elevation="8" min-width="220">
      <ul class="lang__list" role="listbox" :aria-label="$t('common.language')">
        <li
          v-for="(item, index) in locales"
          :key="item.code"
          class="lang__item"
          :class="{ 'lang__item--active': item.code === locale }"
          :style="{ '--i': index }"
          role="option"
          tabindex="0"
          :aria-selected="item.code === locale"
          @click="setLocale(item.code)"
          @keydown.enter.prevent="setLocale(item.code)"
          @keydown.space.prevent="setLocale(item.code)"
        >
          <span class="lang__short">{{ item.code.toUpperCase() }}</span>
          <span class="lang__title">{{ item.title }}</span>
          <v-icon :icon="mdiCheck" size="18" class="lang__check" />
        </li>
      </ul>
    </v-card>
  </v-menu>
</template>

<script>
import { mapActions, mapState } from 'pinia'
import { mdiCheck, mdiChevronUp, mdiTranslate } from '@mdi/js'
import { useSettingsStore } from '@/stores/settings'

// Цвета плашки берутся из переменных сайдбара (--sb-*), поэтому она сама подстраивается под светлую и тёмную тему
export default {
  name: 'LanguageSwitcher',

  props: {
    // Узкий сайдбар: только круглая кнопка
    rail: {
      type: Boolean,
      default: false,
    },
  },

  data() {
    return {
      mdiCheck,
      mdiChevronUp,
      mdiTranslate,
    }
  },

  computed: {
    ...mapState(useSettingsStore, ['locale', 'locales']),

    current() {
      return this.locales.find((item) => item.code === this.locale) || { code: this.locale, title: this.locale.toUpperCase() }
    },
  },

  methods: {
    ...mapActions(useSettingsStore, ['setLocale']),
  },
}
</script>

