import { defineStore } from 'pinia'
import { useAccessStore } from '@/stores/access'
import { useCompanyStore } from '@/stores/company'
import { useManagersStore } from '@/stores/managers'
import { MAX_PERIODS, defaultPeriods, isMonth } from '@/utils/compare'

// Выбор на странице «Порівняння»: что сравнивается (вся сеть, РМ или магазин РМ), какие периоды и показатель
// деталізації. Данные — те же таблицы, что у главной и страниц РМ (уже загружены при входе).
export const useCompareStore = defineStore('compare', {
  state: () => ({
    // null — вся сеть; иначе id менеджера
    managerId: null,
    // null — все магазины менеджера (его итог); иначе название магазина (столбец company)
    store: null,
    // Выбранные периоды; null — по умолчанию (три последних полных месяца), [] — ничего не выбрано
    picked: null,
    // Показатель деталізації (id из KPI_METRICS)
    metric: 'products',
  }),

  getters: {
    // Менеджеры, доступные пользователю, с их таблицами
    managers() {
      const sources = useManagersStore().sources
      return useAccessStore().allowedManagers.map((manager) => ({ ...manager, source: sources[manager.id] || null }))
    },

    manager() {
      return this.managers.find((item) => item.id === this.managerId) || null
    },

    network() {
      return !this.manager
    },

    // Таблица выбранного менеджера (null — вся сеть)
    source() {
      return this.manager ? this.manager.source : null
    },

    // Данные выбранной области загружены
    ready() {
      if (this.network) return useCompanyStore().rows.length > 0
      return !!this.source && this.source.status === 'ready'
    },

    // Периоды выбранной области в порядке таблицы
    times() {
      if (this.network) return useCompanyStore().rows.map((row) => row.time)
      return this.source ? this.source.times : []
    },

    // Магазины менеджера: по последнему периоду, в котором они есть, в порядке таблицы
    stores() {
      if (!this.source) return []
      const names = []
      for (const time of [...this.source.times].reverse()) {
        for (const row of this.source.stores[time] || []) if (!names.includes(row.company)) names.push(row.company)
      }
      return names
    },

    // Выбранные периоды в порядке таблицы (те, что есть в этой области). По умолчанию — три последних месяца;
    // если ни одного выбранного периода нет в таблице новой области — тоже по умолчанию; пустой выбор остаётся пустым
    periods() {
      if (this.picked === null) return defaultPeriods(this.times)
      const picked = this.picked.filter((time) => this.times.includes(time))
      if (!picked.length && this.picked.length) return defaultPeriods(this.times)
      return this.times.filter((time) => picked.includes(time))
    },

    // Три последних полных месяца — быстрый выбор
    lastMonths() {
      return defaultPeriods(this.times.filter(isMonth))
    },

    // Среди выбранных есть и полные месяцы, и нарастающий итог месяца: суммы несопоставимы по длительности
    mixed() {
      return this.periods.some(isMonth) && this.periods.some((time) => !isMonth(time))
    },

    // Строка таблицы выбранной области за период time; store — строка конкретного магазина менеджера
    rowOf() {
      return (time, store = this.store) => {
        if (!time) return null
        if (this.network) return useCompanyStore().rows.find((row) => row.time === time) || null
        if (!this.source) return null
        if (!store) return this.source.totals[time] || null
        return (this.source.stores[time] || []).find((row) => row.company === store) || null
      }
    },
  },

  actions: {
    // Другая область: магазин сбрасывается, периоды остаются (если их нет в новой таблице — по умолчанию)
    setManager(id) {
      this.managerId = id
      this.store = null
    },

    setStore(store) {
      this.store = store
    },

    // Период включается или выключается (можно снять все); больше MAX_PERIODS не выбрать
    togglePeriod(time) {
      const current = [...this.periods]
      if (current.includes(time)) {
        this.picked = current.filter((item) => item !== time)
      } else if (current.length < MAX_PERIODS) {
        this.picked = [...current, time]
      }
    },

    setPeriods(times) {
      this.picked = times.slice(-MAX_PERIODS)
    },

    setMetric(id) {
      this.metric = id
    },
  },
})
