import { numberFormat } from '@/utils/format'
import { CATEGORIES, CHANNEL_METRICS, KPI_METRICS, completion, growth, statusOf } from '@/utils/kpi'

// Сравнение периодов (страница «Порівняння»): показатели главной и страниц РМ — те же поля таблиц.

// Цвета рядов графиков (яркая «жидкость» в стеклянных столбцах): план голубой, факт фиолетовый, прошлый год оранжевый
export const SERIES_COLORS = {
  plan: '#0ea5e9',
  fact: '#7c3aed',
  past: '#f97316',
}

// Сколько периодов можно выбрать сразу: больше — столбцы и подписи не помещаются
export const MAX_PERIODS = 3

// Изменение меньше этого (в процентах или процентных пунктах) — «без изменений»: при одном знаке после запятой
// оно выглядит как 0,0
const NEUTRAL = 0.05

const isNumber = (value) => typeof value === 'number' && Number.isFinite(value)

// Полный месяц в таблицах записан как «серп.26», нарастающий итог месяца — как «01-20.09»
export const isMonth = (time) => /^[^\d-]+\.\d{2}$/.test(time)

// Свой облик карточки каждого показателя: цвет (RGB через запятую) и узор в углу
const METRIC_LOOK = {
  products: { accent: '245, 158, 11', pattern: 'rings' },
  noIphone: { accent: '20, 184, 166', pattern: 'checker' },
  services: { accent: '236, 72, 153', pattern: 'crosshatch' },
  traffic: { accent: '14, 165, 233', pattern: 'waves' },
  conversion: { accent: '16, 185, 129', pattern: 'triangles' },
  check: { accent: '99, 102, 241', pattern: 'zigzag' },
  items: { accent: '249, 115, 22', pattern: 'grid' },
  credit: { accent: '168, 85, 247', pattern: 'lines' },
}

// Показатели сравнения — карточки главной. percent — значение уже в процентах (конверсия, кредит):
// разница — в процентных пунктах
export function metricsFor() {
  return KPI_METRICS.map((metric) => ({ ...metric, ...METRIC_LOOK[metric.id], percent: metric.suffix === '%' }))
}

// Каналы продаж (интернет-магазин, мономаркет) — есть только у всей сети, показываются отдельным блоком.
// Цвет и узор — как у карточек каналов на главной (accent, pattern в CHANNEL_METRICS)
export function channelMetrics() {
  return CHANNEL_METRICS.map((metric) => ({ ...metric, channel: true, percent: false }))
}

export { CATEGORIES }

// Периоды по умолчанию: три последних полных месяца (если полных месяцев нет — последние периоды таблицы)
export function defaultPeriods(times) {
  const months = times.filter(isMonth)
  return (months.length ? months : times).slice(-3)
}

// Направление изменения: up / down / flat
export function trendOf(size) {
  if (!isNumber(size) || Math.abs(size) < NEUTRAL) return 'flat'
  return size > 0 ? 'up' : 'down'
}

// Значения показателя по периодам: план, факт, прошлый год, выполнение плана и рост к прошлому году
export function metricSeries(metric, rows) {
  return rows.map((row) => {
    const value = (field) => (row && field && isNumber(row[field]) ? row[field] : null)
    const fact = value(metric.fact)
    const plan = value(metric.plan)
    const past = value(metric.past)
    const done = completion(fact, plan)
    // Рост к прошлому году: у процентных показателей — в процентных пунктах
    const yoy = past === null || fact === null ? null : metric.percent ? fact - past : growth(fact, past)
    return { fact, plan, past, done, status: statusOf(done), yoy, yoyTrend: trendOf(yoy) }
  })
}

// Изменение со знаком: «+4,5%», «−2,1 п.п.» (points — подпись процентных пунктов); почти нулевое — «0,0%» без знака
export function signedChange(value, locale, points) {
  if (!isNumber(value)) return '—'
  const rounded = Math.round(value * 10) / 10
  const sign = rounded > 0 ? '+' : rounded < 0 ? '−' : ''
  const text = numberFormat(locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(Math.abs(rounded))
  return `${sign}${text}${points ? ` ${points}` : '%'}`
}

// Изменение между двумя значениями: у процентных показателей — в процентных пунктах, у остальных — в процентах
export function changeOf(from, to, percent) {
  if (!isNumber(from) || !isNumber(to)) return null
  if (percent) return to - from
  return from !== 0 ? ((to - from) / Math.abs(from)) * 100 : null
}
