import { createApp } from 'vue'
import { createPinia } from 'pinia'
import App from './App.vue'
import router from './router'
import i18n from './plugins/i18n'
import vuetify from './plugins/vuetify'
import './plugins/chart'
import './styles/main.scss'
import { validateConfig } from './utils/validateConfig'

// Ошибки в configurations.js видны сразу в консоли браузера (F12 → Console), а не странным поведением сайта
const problems = validateConfig((key, locale) => i18n.global.te(key, locale))
if (problems.length) {
  const list = problems.map((text) => `• ${text}`).join('\n')
  console.error(`configurations.js: найдено ошибок — ${problems.length}\n\n${list}`)
}

createApp(App)
  .use(createPinia())
  .use(router)
  .use(i18n)
  .use(vuetify)
  .mount('#app')
