<template>
  <section class="cmp-cats" :aria-label="$t('compare.categories')">
    <p class="cmp-cats__hint">{{ $t('compare.categoriesHint') }}</p>

    <!-- По оси — категории, столбцы — выбранные периоды; пункт легенды скрывает период -->
    <glass-bars :groups="groups" :series="series" :values="values" :value-format="format" :tick-format="tick" :full-format="format" :height="260" />
  </section>
</template>

<script>
import { mapState } from 'pinia'
import GlassBars from '@/components/GlassBars.vue'
import numberFormatMixin from '@/mixins/numberFormat'
import { useCompareStore } from '@/stores/compare'
import { CATEGORIES } from '@/utils/compare'

// Цвета периодов: яркие, от бирюзового к фиолетовому (периодов не больше трёх)
const PALETTE = ['#22d3ee', '#0ea5e9', '#7c3aed']

// Доли категорий в товарообороте по выбранным периодам
export default {
  name: 'CompareCategories',

  components: { GlassBars },

  mixins: [numberFormatMixin],

  computed: {
    ...mapState(useCompareStore, ['periods', 'rowOf']),

    groups() {
      return CATEGORIES.map((category) => this.$t(category.title))
    },

    series() {
      return this.periods.map((time, index) => ({ id: time, label: time, color: PALETTE[index % PALETTE.length] }))
    },

    values() {
      return this.periods.map((time) => {
        const row = this.rowOf(time)
        return CATEGORIES.map((category) => (row && typeof row[category.field] === 'number' ? row[category.field] : null))
      })
    },
  },

  methods: {
    format(value) {
      return this.percent(value)
    },

    tick(value) {
      return `${Math.round(value * 10) / 10}%`
    },
  },
}
</script>

