<template>
  <budget-bars
    v-model:sort-by="sortBy"
    :label="$t('budget.salary.title')"
    :rows="rows"
    :series="series"
    :stats-start="series.map((item) => ({ id: item.id, label: item.label, color: item.color, value: percent(averages[item.id] * 100) }))"
    :sort-options="series.map((item) => ({ ...item, label: $t(item.sortLabel) }))"
  />
</template>

<script>
import { mapState } from 'pinia'
import BudgetBars from '@/components/BudgetBars.vue'
import numberFormatMixin from '@/mixins/numberFormat'
import { useBudgetStore } from '@/stores/budget'
import { useScopeStore } from '@/stores/scope'
import { SPECIAL, n } from '@/utils/budget'

// Два показателя на одном графике, цвета и порядок — как на прежней странице:
// общая ЗП к прибыли — зелёная, ЗП «% від продажу» к прибыли — оранжевая
const SERIES = [
  { id: 'total', color: 'rgba(34, 197, 94, 0.85)', sortLabel: 'budget.salary.sortTotal' },
  { id: 'pct', color: 'rgba(249, 115, 22, 0.85)', sortLabel: 'budget.salary.sortPct' },
]

// Частка ЗП у прибутку (budget-page-map.md, блок 7 + 10–11, левая часть): магазины с валовой прибылью больше нуля
// и заполненным salary_pct_profit (у Інтернет-магазину и Сервісу его нет). «% від продажу» — готовое значение
// из таблицы (salary_pct_profit), «загальна» считается: оплата праці / валовая прибыль
export default {
  name: 'BudgetSalaryShare',

  components: { BudgetBars },

  mixins: [numberFormatMixin],

  data() {
    return {
      // По какому показателю сортировать магазины: total (по умолчанию, как на прежней странице) или pct
      sortBy: 'total',
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    stores() {
      return useBudgetStore()
        .rowsOf(this.period)
        .filter((row) => !SPECIAL.has(row.store) && n(row.profit) > 0 && typeof row.salary_pct_profit === 'number')
        .map((row) => ({ store: row.store, profit: n(row.profit), salary: n(row.salary), total: n(row.salary) / n(row.profit), pct: row.salary_pct_profit }))
        .sort((a, b) => b[this.sortBy] - a[this.sortBy])
    },

    // Средние по этим магазинам, взвешенные по валовой прибыли (для общей ЗП — сумма ЗП к сумме прибыли)
    averages() {
      const profit = this.stores.reduce((sum, row) => sum + row.profit, 0)
      const weighted = (field) => (profit ? this.stores.reduce((sum, row) => sum + row[field] * row.profit, 0) / profit : 0)
      return { total: weighted('total'), pct: weighted('pct') }
    },

    series() {
      return SERIES.map((item) => ({ ...item, label: this.$t(`budget.salary.${item.id}`) }))
    },

    rows() {
      const uah = this.$t('kpi.uah')
      return this.stores.map((row) => ({
        label: row.store,
        values: [row.total, row.pct],
        extra: [`${this.$t('budget.salary.profit')}: ${this.money(row.profit)} ${uah}`, `${this.$t('budget.salary.salary')}: ${this.money(row.salary)} ${uah}`],
      }))
    },
  },
}
</script>
