<template>
  <section class="stores" :aria-label="$t('results.rmStores.title')">
    <p v-if="!rmList.length" class="stores__empty">{{ $t('results.rmStores.empty') }}</p>

    <template v-else>
      <!-- Переключатель РМ: кнопка в цвете менеджера, как на прежней странице -->
      <div class="stores__tabs" role="tablist" :aria-label="$t('results.rmStores.choose')">
        <button
          v-for="rm in rmList"
          :key="rm.name"
          type="button"
          role="tab"
          class="stores__tab"
          :class="{ 'stores__tab--active': rm.name === current }"
          :style="{ '--rm': rm.color }"
          :aria-selected="rm.name === current"
          @click="select(rm.name)"
        >
          <b>{{ rm.name }}</b>
          <small>{{ $t('results.rmStores.count', { n: rm.count }) }}</small>
        </button>
      </div>

      <ul class="stores__summary" :style="{ '--rm': currentColor }">
        <li>
          <span>{{ $t('results.rmStores.storesTotal') }}</span>
          <b>{{ stores.length }}</b>
        </li>
        <li>
          <span>{{ $t('results.rmStores.metrics.revenue') }}</span>
          <b>{{ millions(sum('revenue')) }}</b>
        </li>
        <li>
          <span>{{ $t('results.rmStores.metrics.profit') }}</span>
          <b>{{ millions(sum('profit')) }}</b>
        </li>
        <li>
          <span>{{ $t('results.rmStores.onPlan') }}</span>
          <b>{{ onPlan }} / {{ stores.length }}</b>
        </li>
      </ul>

      <!-- Шесть рейтингов магазинов выбранного РМ -->
      <div class="stores__grid">
        <article v-for="panel in panels" :key="panel.field" class="stores__panel">
          <header class="stores__head">
            <span class="stores__icon" aria-hidden="true">
              <v-icon :icon="panel.icon" size="20" />
            </span>
            <h3 class="stores__title">{{ $t(`results.rmStores.metrics.${panel.field}`) }}</h3>
          </header>

          <ol class="stores__list">
            <li
              v-for="row in panel.rows"
              :key="row.name"
              class="stores__row"
              :class="{ 'stores__row--hover': hovered === row.name }"
              @pointerenter="hovered = row.name"
              @pointerleave="hovered = null"
            >
              <span class="stores__name" :title="row.name">{{ row.name }}</span>
              <span class="stores__track" aria-hidden="true">
                <i v-if="panel.zero > 0" class="stores__zero" :style="{ left: `${panel.zero}%` }"></i>
                <i class="stores__bar" :style="barStyle(panel, row)"></i>
              </span>
              <span class="stores__value">{{ row.text }}</span>
            </li>
          </ol>
        </article>

        <!-- Трафик столбиками и конверсия линией, на всю ширину -->
        <article class="stores__panel stores__panel--wide">
          <header class="stores__head">
            <span class="stores__icon" aria-hidden="true">
              <v-icon :icon="mdiAccountGroupOutline" size="20" />
            </span>
            <h3 class="stores__title">{{ $t('results.rmStores.metrics.traffic') }}</h3>
            <ul class="stores__legend">
              <li><i class="stores__legend-bar" aria-hidden="true"></i>{{ $t('results.rmStores.trafficShort') }}</li>
              <li><i class="stores__legend-line" aria-hidden="true"></i>{{ $t('results.rmStores.conversion') }}</li>
            </ul>
          </header>

          <div class="stores__chart-scroll">
            <div class="stores__chart" :class="{ 'stores__chart--vertical': vertical }" :style="chartStyle">
              <canvas ref="canvas"></canvas>
            </div>
          </div>
        </article>
      </div>
    </template>
  </section>
</template>

<script>
import { markRaw } from 'vue'
import { mapState } from 'pinia'
import {
  mdiAccountGroupOutline,
  mdiBullseyeArrow,
  mdiCashMultiple,
  mdiCreditCardOutline,
  mdiReceiptTextOutline,
  mdiShapeOutline,
  mdiTrendingUp,
} from '@mdi/js'
import Chart from '@/plugins/chart'
import { useResultsStore } from '@/stores/results'
import { useScopeStore } from '@/stores/scope'
import { useSettingsStore } from '@/stores/settings'
import { gradientRgb, thresholdGradientRgb } from '@/utils/color'
import { managerColor, NO_MANAGER_COLOR } from '@/utils/resultsColors'
import { animateProgress } from '@/utils/tween'
import numberFormatMixin from '@/mixins/numberFormat'

// Цвета — из _storeColor прежней страницы итогов
const NEGATIVE = '#ef4444'
// Линия конверсии на графике «Трафік і конверсія»
const CONVERSION = '#6366f1'

// Товарооборот: 5 ступеней по доле от лучшего магазина РМ
function revenueColor(value, max) {
  const ratio = value / Math.max(max, 1)
  if (ratio > 0.8) return '#15803d'
  if (ratio > 0.5) return '#22c55e'
  if (ratio > 0.3) return '#4ade80'
  if (ratio > 0.15) return '#86efac'
  return '#bbf7d0'
}

// Прибыль: убыток — красный, иначе верхняя (жёлто-зелёная) половина градиента по доле от лучшего магазина
function profitColor(value, max) {
  if (value < 0) return NEGATIVE
  return `rgb(${gradientRgb(0.5 + (value / Math.max(max, 1)) * 0.5)})`
}

const byThresholds = (thresholds) => (value) => `rgb(${thresholdGradientRgb(value, thresholds)})`

// Рейтинги в порядке прежней страницы. kind: percent — доля (1,12 → 112 %), money — сумма в гривнах
const PANELS = [
  { field: 'plan_pct', icon: mdiBullseyeArrow, kind: 'percent', color: byThresholds({ red: 0.8, yellow: 0.9, green: 1.15 }) },
  { field: 'revenue', icon: mdiCashMultiple, kind: 'money', color: revenueColor },
  { field: 'cat_pct', icon: mdiShapeOutline, kind: 'percent', color: byThresholds({ red: 0.2, yellow: 0.49, green: 1.0 }) },
  { field: 'profit', icon: mdiTrendingUp, kind: 'money', color: profitColor },
  { field: 'avg_check', icon: mdiReceiptTextOutline, kind: 'money', color: byThresholds({ red: 2000, yellow: 2999, green: 8000 }) },
  { field: 'credit_pct', icon: mdiCreditCardOutline, kind: 'percent', color: byThresholds({ red: 0.1, yellow: 0.213, green: 0.5 }) },
]
// Столбики трафика
const trafficColor = byThresholds({ red: 0, yellow: 50, green: 120 })

const isNumber = (value) => typeof value === 'number' && Number.isFinite(value)

export default {
  name: 'ResultsRmStores',

  mixins: [numberFormatMixin],

  data() {
    return {
      mdiAccountGroupOutline,
      // Выбранный РМ; null — первый по порядку таблицы
      selected: null,
      // Магазин под курсором: подсвечивается во всех рейтингах
      hovered: null,
      progress: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),
    ...mapState(useSettingsStore, ['isDark']),

    locale() {
      return this.$i18n.locale
    },

    detail() {
      return useResultsStore().rowsOf('stores_detail', this.period)
    },

    // РМ в порядке появления в таблице, с цветом менеджера и числом магазинов
    rmList() {
      const list = []
      for (const row of this.detail) {
        if (!row.rm) continue
        let rm = list.find((item) => item.name === row.rm)
        if (!rm) {
          rm = { name: row.rm, color: managerColor(row.rm), count: 0 }
          list.push(rm)
        }
        rm.count += 1
      }
      return list
    },

    current() {
      return this.rmList.some((rm) => rm.name === this.selected) ? this.selected : this.rmList.length ? this.rmList[0].name : null
    },

    currentColor() {
      const rm = this.rmList.find((item) => item.name === this.current)
      return rm ? rm.color : NO_MANAGER_COLOR
    },

    stores() {
      return this.detail.filter((row) => row.rm === this.current)
    },

    onPlan() {
      return this.stores.filter((row) => isNumber(row.plan_pct) && row.plan_pct >= 1).length
    },

    panels() {
      return PANELS.map((panel) => {
        const list = this.stores.filter((row) => isNumber(row[panel.field])).sort((a, b) => b[panel.field] - a[panel.field])
        const values = list.map((row) => row[panel.field])
        const max = Math.max(0, ...values)
        const min = Math.min(0, ...values)
        const span = max - min || 1
        return {
          ...panel,
          // Положение нуля на шкале: у прибыли бывают убытки, тогда столбики расходятся от нуля
          zero: (-min / span) * 100,
          span,
          rows: list.map((row) => ({
            name: row.store,
            value: row[panel.field],
            color: panel.color(row[panel.field], max),
            text: this.format(panel.kind, row[panel.field]),
          })),
        }
      })
    },

    traffic() {
      return this.stores.filter((row) => isNumber(row.avg_traffic)).sort((a, b) => b.avg_traffic - a.avg_traffic)
    },

    view() {
      return `${this.period}|${this.current}`
    },

    // Телефон: график трафика и конверсии поворачивается
    vertical() {
      return this.$vuetify.display.xs
    },

    // Высота повёрнутого графика — по числу магазинов
    chartStyle() {
      return this.vertical ? { height: `${this.traffic.length * 34 + 60}px` } : null
    },
  },

  watch: {
    // Сменился РМ или период (часто оба сразу, когда данные пришли): анимация и график — один раз
    view() {
      this.replay()
      this.$nextTick(this.draw)
    },

    isDark() {
      this.draw()
    },

    locale() {
      this.draw()
    },

    vertical() {
      this.$nextTick(this.draw)
    },
  },

  mounted() {
    this.replay()
    this.draw()
  },

  beforeUnmount() {
    if (this.stopTween) this.stopTween()
    this.destroy()
  },

  methods: {
    select(name) {
      this.selected = name
    },

    replay() {
      if (this.stopTween) this.stopTween()
      this.stopTween = animateProgress((progress) => (this.progress = progress), { delay: 100, duration: 900 })
    },

    sum(field) {
      return this.stores.reduce((total, row) => total + (isNumber(row[field]) ? row[field] : 0), 0)
    },

    format(kind, value) {
      return kind === 'percent' ? this.percent(value * 100) : this.money(value)
    },

    // Столбик от нуля вправо, убыток — от нуля влево
    barStyle(panel, row) {
      const width = (Math.abs(row.value) / panel.span) * 100 * this.progress
      const side = row.value >= 0 ? { left: `${panel.zero}%` } : { right: `${100 - panel.zero}%` }
      return { ...side, width: `${width}%`, background: row.color }
    },

    destroy() {
      // Экземпляр графика хранится вне data(), чтобы Vue не делал его реактивным
      if (this.chart) this.chart.destroy()
      this.chart = null
    },

    // Трафик и конверсия: столбики трафика (цвет по порогам 0 / 50 / 120) и линия конверсии, как на прежней странице.
    // На телефоне график поворачивается: магазины идут сверху вниз, трафик — горизонтальными столбиками
    draw() {
      this.destroy()
      const canvas = this.$refs.canvas
      if (!canvas || !this.traffic.length) return

      const vertical = this.vertical
      const text = this.isDark ? 'rgba(255, 255, 255, 0.7)' : 'rgba(0, 0, 0, 0.6)'
      const grid = this.isDark ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.06)'
      const surface = this.isDark ? '#20201e' : '#ffffff'
      const rows = this.traffic
      const percent = (value) => this.percent(value * 100)
      const traffic = (value) => this.money(value)
      // Ось магазинов и оси значений: в обычном виде магазины снизу, на телефоне — слева
      const storeAxis = vertical ? 'y' : 'x'
      const trafficAxis = vertical ? 'x' : 'y'
      const conversionAxis = vertical ? 'x1' : 'y1'
      const storeTicks = {
        color: text,
        font: { size: 11, weight: 600 },
        autoSkip: false,
        maxRotation: vertical ? 0 : 40,
        // Длинные названия магазинов обрезаются, полное — в подсказке
        callback(value) {
          const label = this.getLabelForValue(value)
          const limit = vertical ? 18 : 16
          return label.length > limit ? `${label.slice(0, limit - 1)}…` : label
        },
      }

      this.chart = markRaw(
        new Chart(canvas, {
          type: 'bar',
          data: {
            labels: rows.map((row) => row.store),
            datasets: [
              {
                type: 'bar',
                data: rows.map((row) => row.avg_traffic),
                backgroundColor: rows.map((row) => trafficColor(row.avg_traffic)),
                borderRadius: 6,
                maxBarThickness: vertical ? 22 : 56,
                [`${trafficAxis}AxisID`]: trafficAxis,
                order: 2,
                datalabels: {
                  anchor: 'start',
                  align: 'end',
                  offset: 4,
                  color: '#fff',
                  font: { weight: 800, size: 11 },
                  formatter: traffic,
                },
              },
              {
                type: 'line',
                data: rows.map((row) => (isNumber(row.conversion) ? row.conversion : null)),
                borderColor: CONVERSION,
                backgroundColor: CONVERSION,
                pointBackgroundColor: CONVERSION,
                pointBorderColor: surface,
                pointBorderWidth: 2,
                pointRadius: vertical ? 4 : 5,
                pointHoverRadius: 7,
                borderWidth: 2.5,
                tension: 0.3,
                spanGaps: true,
                [`${trafficAxis}AxisID`]: conversionAxis,
                order: 1,
                datalabels: {
                  align: vertical ? 'right' : 'top',
                  offset: 6,
                  color: text,
                  font: { weight: 800, size: 11 },
                  formatter: (value) => (value === null ? '' : percent(value)),
                },
              },
            ],
          },
          options: {
            indexAxis: storeAxis,
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: 'index', intersect: false, axis: storeAxis },
            layout: { padding: vertical ? { top: 4, right: 40, left: 0 } : { top: 26, right: 4, left: 4 } },
            animation: { duration: 900, easing: 'easeOutQuart' },
            plugins: {
              legend: { display: false },
              tooltip: {
                backgroundColor: surface,
                titleColor: this.isDark ? '#fff' : '#0b0b0b',
                bodyColor: text,
                borderColor: grid,
                borderWidth: 1,
                padding: 10,
                cornerRadius: 10,
                callbacks: {
                  label: (context) =>
                    context.datasetIndex === 0
                      ? ` ${this.$t('results.rmStores.trafficShort')}: ${traffic(context.raw)}`
                      : ` ${this.$t('results.rmStores.conversion')}: ${percent(context.raw)}`,
                },
              },
            },
            scales: {
              [storeAxis]: { grid: { display: false }, border: { display: false }, ticks: storeTicks },
              [trafficAxis]: {
                position: vertical ? 'bottom' : 'left',
                grid: { color: grid },
                border: { display: false },
                beginAtZero: true,
                ticks: { color: text },
              },
              [conversionAxis]: {
                position: vertical ? 'top' : 'right',
                grid: { display: false },
                border: { display: false },
                beginAtZero: true,
                ticks: { color: CONVERSION, callback: (value) => `${Math.round(value * 100)}%` },
              },
            },
          },
        }),
      )
    },
  },
}
</script>

