<template>
  <section ref="root" class="bpies" :class="{ 'bpies--row': row }" :aria-label="$t('budget.pies.title')">
    <budget-pie
      v-for="pie in pies"
      :key="pie.id"
      :class="`bpies__${pie.id}`"
      :title="$t(`budget.pies.${pie.id}`)"
      :icon="pie.icon"
      :from="pie.from"
      :to="pie.to"
      :items="pie.items"
      :half-width="!row && pie.id === 'maintain' ? 0 : halfWidth"
      :radius="shape.r"
      :start-angle="shape.startAngle"
      :inline="shape.inline"
      :row-gap="shape.rowGap"
      :limit-height="!row"
      :animate="false"
      clickable
      @open="open(pie)"
    />

    <!-- Окно диаграммы: компактный круг общего для трёх диаграмм размера — окна одинаковые -->
    <budget-pie-dialog v-model="dialog" :pie="active && dialogPie(active)" />
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiAccountGroupOutline, mdiChartPie, mdiWrenchOutline } from '@mdi/js'
import BudgetPie, { COMPACT_SHAPE, pieFormat, shapeProps } from '@/components/BudgetPie.vue'
import BudgetPieDialog from '@/components/BudgetPieDialog.vue'
import numberFormatMixin from '@/mixins/numberFormat'
import { useBudgetStore } from '@/stores/budget'
import { useScopeStore } from '@/stores/scope'
import { CALLOUT_R, calloutLayout } from '@/utils/calloutPie'
import { FOT_ROW, MAINTAIN_FIELDS, n } from '@/utils/budget'

// Цвета — как на прежней странице: палитра PIE_COLORS и цвета шапок карточек
const PIE_COLORS = ['#6366f1', '#22c55e', '#f59e0b', '#ef4444', '#14b8a6', '#8b5cf6', '#f97316', '#06b6d4', '#84cc16', '#ec4899', '#a78bfa', '#fb923c', '#34d399', '#fbbf24']

// Категории расходов: поля, из которых складывается категория
const CATEGORIES = [
  { id: 'maintain', fields: MAINTAIN_FIELDS },
  { id: 'repairs', fields: ['repairs', 'tools'] },
  { id: 'personnel', fields: ['salary', 'salary_other', 'salary_travel'] },
  { id: 'marketing', fields: ['marketing'] },
  { id: 'taxes', fields: ['taxes'] },
]

// Все три диаграммы в один ряд — от этой ширины блока (px). Тогда первый сектор начинается справа («3 часа»):
// мелкие статьи оказываются сбоку, их подписи встают столбиком, а не широкой строкой над кругом. Подписи компактные
// (сумма и процент в одной строке, промежуток ROW_GAP): столбик не выше круга, выноски короткие.
// ROW_R — радиус круга (в единицах текста подписей, у которого размер 26)
const ROW_FROM = 1500
const ROW_R = 250
const ROW_GAP = 16

// Составляющие ФОТ из строки «МЕРЕЖА (ФОТ деталізація)»
const FOT_FIELDS = [
  { id: 'rate', field: 'salary_rate' },
  { id: 'pctSales', field: 'salary_pct_sales' },
  { id: 'bonuses', field: 'salary_bonuses' },
  { id: 'freelance', field: 'salary_freelance' },
  { id: 'vacation', field: 'salary_vacation' },
]

// Три диаграммы расходов сети за месяц (все строки, кроме строки ФОТ): по категориям, ФОТ и расходы на содержание.
// Статьи с нулевой суммой не показываются, остальные — от большей к меньшей
export default {
  name: 'BudgetExpensePies',

  components: { BudgetPie, BudgetPieDialog },

  mixins: [numberFormatMixin],

  data() {
    return {
      // Ширина блока: от неё зависит раскладка (три в ряд или две и одна под ними)
      width: 0,
      dialog: false,
      // id диаграммы, открытой в окне
      activeId: null,
    }
  },

  computed: {
    row() {
      return this.width >= ROW_FROM
    },

    shape() {
      return this.row
        ? { r: ROW_R, startAngle: 0, inline: true, rowGap: ROW_GAP }
        : { r: CALLOUT_R, startAngle: -Math.PI / 2, inline: false, rowGap: undefined }
    },

    ...mapState(useScopeStore, ['period']),

    monthRows() {
      return useBudgetStore().rowsOf(this.period)
    },

    // Строки для сумм: вся сеть с офисом и складами, без строки ФОТ
    rows() {
      return this.monthRows.filter((row) => row.store !== FOT_ROW)
    },

    pies() {
      const sum = (fields) => this.rows.reduce((total, row) => total + fields.reduce((acc, field) => acc + n(row[field]), 0), 0)
      const clean = (list) => list.filter((item) => item.value > 0).sort((a, b) => b.value - a.value)

      const categories = CATEGORIES.map((item, index) => ({
        id: item.id,
        label: this.$t(`budget.cats.${item.id}`),
        value: sum(item.fields),
        color: PIE_COLORS[index],
      }))

      // ФОТ: пять составляющих из строки ФОТ; прочие расходы на персонал и командировки в ней не заполнены —
      // они суммируются по всем строкам
      const fot = this.monthRows.find((row) => row.store === FOT_ROW) || {}
      const payroll = [
        ...FOT_FIELDS.map((item, index) => ({ id: item.id, label: this.$t(`budget.fot.${item.id}`), value: n(fot[item.field]), color: PIE_COLORS[index] })),
        { id: 'salary_other', label: this.$t('budget.fields.salary_other'), value: sum(['salary_other']), color: PIE_COLORS[5] },
        { id: 'salary_travel', label: this.$t('budget.fields.salary_travel'), value: sum(['salary_travel']), color: PIE_COLORS[6] },
      ]

      // Содержание: цвет закреплён за статьёй (по её месту в списке статей), а не по размеру
      const maintain = MAINTAIN_FIELDS.map((field, index) => ({
        id: field,
        label: this.$t(`budget.fields.${field}`),
        value: sum([field]),
        color: PIE_COLORS[index % PIE_COLORS.length],
      }))

      return [
        { id: 'expCat', icon: mdiChartPie, from: '#f59e0b', to: '#c2410c', items: clean(categories) },
        { id: 'fot', icon: mdiAccountGroupOutline, from: '#22c55e', to: '#15803d', items: clean(payroll) },
        { id: 'maintain', icon: mdiWrenchOutline, from: '#3b82f6', to: '#1d4ed8', items: clean(maintain) },
      ]
    },

    // Общая ширина диаграмм в одном ряду (три в ряд или две верхние): круги и текст у них одного размера,
    // как на прежней странице
    halfWidth() {
      const format = pieFormat(this)
      const inRow = this.pies.filter((pie) => (this.row || pie.id !== 'maintain') && pie.items.length)
      return Math.max(0, ...inRow.map((pie) => calloutLayout(pie.items, { ...this.shape, format }).halfWidth))
    },

    active() {
      return this.pies.find((pie) => pie.id === this.activeId) || null
    },

    // Общий размер окон: компактный круг, по всем трём диаграммам
    dialogSize() {
      const format = pieFormat(this)
      const layouts = this.pies.filter((pie) => pie.items.length).map((pie) => calloutLayout(pie.items, { ...COMPACT_SHAPE, format }))
      return { halfWidth: Math.max(0, ...layouts.map((item) => item.halfWidth)), halfHeight: Math.max(0, ...layouts.map((item) => item.halfHeight)) }
    },
  },

  watch: {
    // Другой месяц: открытое окно показывает уже другие данные — закрываем
    period() {
      this.dialog = false
    },
  },

  mounted() {
    if ('ResizeObserver' in window) {
      this.observer = new ResizeObserver(([entry]) => (this.width = Math.floor(entry.contentRect.width)))
      this.observer.observe(this.$refs.root)
    }
    // Первый размер — сразу: в фоновой вкладке ResizeObserver срабатывает, только когда вкладку откроют
    this.width = Math.floor(this.$refs.root.getBoundingClientRect().width)
  },

  beforeUnmount() {
    if (this.observer) this.observer.disconnect()
  },

  methods: {
    open(pie) {
      this.activeId = pie.id
      this.dialog = true
    },

    // Props круга в окне
    dialogPie(pie) {
      return { title: this.$t(`budget.pies.${pie.id}`), icon: pie.icon, from: pie.from, to: pie.to, items: pie.items, ...this.dialogSize, ...shapeProps(COMPACT_SHAPE) }
    },
  },
}
</script>

<style lang="scss" scoped>
// Широкий блок — три в ряд; иначе две в ряд, третья (много статей, подписи шире) — под ними на всю ширину;
// ещё уже — одна колонка
.bpies {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: $spacer * 5;
  width: 100%;
  max-width: var(--page-max, 1500px);

  &__maintain {
    grid-column: 1 / -1;
  }

  &--row {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  &--row &__maintain {
    grid-column: auto;
  }

  @media (max-width: #{$breakpoint-lg - 1px}) {
    grid-template-columns: minmax(0, 1fr);
    gap: $spacer * 4;
  }
}
</style>
