import { RESULTS } from '@/configurations'
import { normalizeRows } from '@/services/company'
import { gasGet } from '@/services/gas'

// Массивы ответа скрипта итогов. У каждой строки есть period — месяц в формате «Серпень-26»
const RESULTS_TABLES = [
  'main_kpi',
  'stores_revenue',
  'credits',
  'cat_managers',
  'rm_metrics',
  'stores_detail',
  'yoy',
  'lavina_main',
  'lavina_cat_plan',
  'lavina_cat_revenue',
]

// Текстовые столбцы; остальные значения — числа или null
const TEXT_COLUMNS = ['period', 'store', 'bank', 'oc_bank', 'manager', 'rm', 'category']

// Все таблицы итогов одним запросом: { main_kpi: [...], stores_revenue: [...], ... }.
// Таблица, которой нет в ответе, становится пустым списком, чтобы один пропавший блок не ломал страницу.
export async function fetchResults() {
  const data = await gasGet(RESULTS.URL)
  const info = data && data.results_info
  if (!info || !Array.isArray(info.main_kpi)) throw new Error('Results: неожиданный ответ')
  const tables = Object.fromEntries(
    RESULTS_TABLES.map((name) => [name, Array.isArray(info[name]) ? normalizeRows(info[name], TEXT_COLUMNS).map(unifyStore) : []]),
  )
  warnUnpaired(tables)
  return tables
}

// Одно название магазина во всех таблицах (RESULTS.STORE_ALIASES)
function unifyStore(row) {
  const alias = row.store && RESULTS.STORE_ALIASES[row.store]
  return alias ? { ...row, store: alias } : row
}

// Магазины из «структуры доходу», которых нет в таблице плана: скорее всего, название записано по-разному
// и пару нужно добавить в RESULTS.STORE_ALIASES
function warnUnpaired(tables) {
  const planned = new Set(tables.stores_detail.map((row) => row.store))
  const unpaired = [
    ...new Set(
      tables.stores_revenue
        .map((row) => row.store)
        .filter((store) => store && !planned.has(store) && !RESULTS.STORES_WITHOUT_PLAN.includes(store)),
    ),
  ]
  const extra = [...new Set(tables.stores_detail.map((row) => row.store))].filter(
    (store) => store && !tables.stores_revenue.some((row) => row.store === store),
  )
  if (unpaired.length || extra.length) {
    console.warn(
      `Підсумки: магазини без пари (додайте пару в RESULTS.STORE_ALIASES у configurations.js)\n` +
        `• є в структурі доходу, немає в плані: ${unpaired.join(', ') || '—'}\n` +
        `• є в плані, немає в структурі доходу: ${extra.join(', ') || '—'}`,
    )
  }
}
