// Анимация появления: через delay вызывает onStep(progress) с плавным ростом progress от 0 до 1 за duration мс
// (замедление к концу). setInterval, а не requestAnimationFrame, чтобы анимация доходила до конца и в фоновой вкладке.
// Возвращает функцию остановки: её нужно вызвать при повторном запуске и в beforeUnmount.
export function animateProgress(onStep, { duration = 1200, delay = 0 } = {}) {
  let interval = null
  onStep(0)
  const timeout = setTimeout(() => {
    const started = Date.now()
    interval = setInterval(() => {
      const t = Math.min(1, (Date.now() - started) / duration)
      onStep(1 - Math.pow(1 - t, 3))
      if (t === 1) clearInterval(interval)
    }, 16)
  }, delay)

  return () => {
    clearTimeout(timeout)
    clearInterval(interval)
  }
}
