<template>
  <section class="rm" :aria-label="$t('results.rm.title')">
    <p v-if="!rows.length" class="rm__empty">{{ $t('results.rm.empty') }}</p>

    <template v-else>
      <article v-for="panel in panels" :key="panel.field" class="rm__panel">
        <header class="rm__head">
          <span class="rm__icon" aria-hidden="true">
            <v-icon :icon="panel.icon" size="22" />
          </span>
          <h3 class="rm__title">{{ $t(`results.rm.metrics.${panel.field}`) }}</h3>
        </header>

        <ol class="rm__list">
          <li
            v-for="(row, index) in panel.rows"
            :key="row.name"
            class="rm__row"
            :class="{ 'rm__row--hover': hovered === row.name, 'rm__row--leader': index === 0 }"
            @pointerenter="hovered = row.name"
            @pointerleave="hovered = null"
          >
            <span class="rm__rank">{{ index + 1 }}</span>
            <span class="rm__name">
              <i class="rm__dot" :style="{ background: row.dot }" aria-hidden="true"></i>
              {{ row.name }}
            </span>
            <span class="rm__track" aria-hidden="true">
              <i class="rm__bar" :style="{ width: `${row.width * progress}%`, background: `rgb(${row.color})` }"></i>
              <!-- Пунктир — среднее по РМ -->
              <i class="rm__mean" :style="{ left: `${panel.averageAt}%` }"></i>
            </span>
            <span class="rm__figures">
              <b class="rm__value">{{ format(panel, row.value) }}</b>
              <small
                v-if="row.delta !== null"
                class="rm__delta"
                :class="row.delta >= 0 ? 'rm__delta--up' : 'rm__delta--down'"
                :title="$t('results.rm.vsPrev', { period: previous })"
              >
                {{ row.delta >= 0 ? '▲' : '▼' }} {{ deltaText(panel, row.delta) }}
              </small>
            </span>
          </li>
        </ol>
      </article>

      <p class="rm__note">
        <i class="rm__note-mean" aria-hidden="true"></i>
        {{ $t('results.rm.meanNote') }}
        <template v-if="previous">· {{ $t('results.rm.deltaNote', { period: previous }) }}</template>
      </p>
    </template>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import {
  mdiAccountTieOutline,
  mdiBullseyeArrow,
  mdiPercentOutline,
  mdiReceiptTextOutline,
  mdiShapeOutline,
  mdiStorefrontCheckOutline,
} from '@mdi/js'
import { useResultsStore } from '@/stores/results'
import { useScopeStore } from '@/stores/scope'
import { thresholdGradientRgb } from '@/utils/color'
import { managerColor } from '@/utils/resultsColors'
import { animateProgress } from '@/utils/tween'
import numberFormatMixin from '@/mixins/numberFormat'

// Показатели РМ в порядке прежней страницы. Пороги цвета — из _rmColor прежней страницы:
// red — красный, yellow — жёлтый, green — зелёный, между ними плавный переход.
// percent — значение в долях (1,12 → 112 %)
const PANELS = [
  { field: 'plan_pct', icon: mdiBullseyeArrow, percent: true, thresholds: { red: 0.8, yellow: 0.9, green: 1.15 } },
  { field: 'stores_on_plan_pct', icon: mdiStorefrontCheckOutline, percent: true, thresholds: { red: 0.2, yellow: 0.5, green: 0.85 } },
  { field: 'categories_pct', icon: mdiShapeOutline, percent: true, thresholds: { red: 0.2, yellow: 0.5, green: 1.0 } },
  { field: 'sellers_ke_pct', icon: mdiAccountTieOutline, percent: true, thresholds: { red: 0.1, yellow: 0.3, green: 0.7 } },
  { field: 'avg_check', icon: mdiReceiptTextOutline, percent: false, thresholds: { red: 2000, yellow: 3500, green: 5500 } },
  { field: 'conversion', icon: mdiPercentOutline, percent: true, thresholds: { red: 0.15, yellow: 0.2, green: 0.28 } },
]


export default {
  name: 'ResultsRmMetrics',

  mixins: [numberFormatMixin],

  data() {
    return {
      // РМ под курсором: подсвечивается во всех панелях
      hovered: null,
      progress: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    locale() {
      return this.$i18n.locale
    },

    rows() {
      return useResultsStore().rowsOf('rm_metrics', this.period).filter((row) => row.rm)
    },

    // Предыдущий период по порядку таблицы: с ним сравнивается каждый РМ
    previous() {
      const periods = useResultsStore().periods
      const index = periods.findIndex((item) => item.time === this.period)
      return index > 0 ? periods[index - 1].time : ''
    },

    previousRows() {
      if (!this.previous) return {}
      return Object.fromEntries(useResultsStore().rowsOf('rm_metrics', this.previous).map((row) => [row.rm, row]))
    },


    panels() {
      return PANELS.map((panel) => {
        const list = this.rows.filter((row) => typeof row[panel.field] === 'number').sort((a, b) => b[panel.field] - a[panel.field])
        // Шкала с запасом: у лидера есть место, пунктир среднего не упирается в край
        const max = list.length ? Math.max(list[0][panel.field], 0) * 1.08 || 1 : 1
        const average = list.length ? list.reduce((sum, row) => sum + row[panel.field], 0) / list.length : null
        return {
          ...panel,
          averageAt: average === null ? 0 : (Math.max(0, average) / max) * 100,
          rows: list.map((row) => {
            const value = row[panel.field]
            const before = this.previousRows[row.rm] ? this.previousRows[row.rm][panel.field] : null
            return {
              name: row.rm,
              value,
              dot: managerColor(row.rm),
              width: (Math.max(0, value) / max) * 100,
              color: thresholdGradientRgb(value, panel.thresholds),
              delta: this.deltaOf(panel, value, before),
            }
          }),
        }
      })
    },
  },

  watch: {
    period: {
      immediate: true,
      handler() {
        if (this.stopTween) this.stopTween()
        this.stopTween = animateProgress((progress) => (this.progress = progress), { delay: 150 })
      },
    },
  },

  beforeUnmount() {
    if (this.stopTween) this.stopTween()
  },

  methods: {
    // Изменение к прошлому месяцу: у долей — в процентных пунктах, у чека — в процентах
    deltaOf(panel, value, before) {
      if (typeof before !== 'number') return null
      if (panel.percent) return (value - before) * 100
      return before ? (value / before - 1) * 100 : null
    },

    format(panel, value) {
      if (value === null) return '—'
      return panel.percent ? this.percent(value * 100) : this.money(value)
    },

    deltaText(panel, delta) {
      const text = this.percent(Math.abs(delta)).replace('%', '')
      return panel.percent ? `${text} ${this.$t('results.overview.points')}` : `${text}%`
    },
  },
}
</script>

