<template>
  <div ref="stage" class="treemap" role="list" :aria-label="label" @pointerleave="onLeave">
    <button
      v-for="cell in cells"
      :key="cell.item.id"
      type="button"
      role="listitem"
      class="treemap__cell"
      :class="{ 'treemap__cell--active': active && active.item.id === cell.item.id }"
      :style="cell.style"
      :aria-label="`${cell.item.label}: ${valueText(cell.item.value)}, ${percent(cell.item.share * 100)}`"
      @pointermove="onMove($event, cell)"
      @click="onTap($event, cell)"
    >
      <span v-if="cell.label" class="treemap__label" :class="`treemap__label--${cell.label}`">
        <span v-if="cell.label !== 'value'" class="treemap__name">{{ cell.item.label }}</span>
        <!-- valueFirst: крупно сумма, мелко доля; иначе наоборот -->
        <b class="treemap__main">{{ valueFirst ? compact(cell.item.value) : percent(cell.item.share * 100) }}</b>
        <small v-if="cell.label === 'full'" class="treemap__extra">
          {{ valueFirst ? percent(cell.item.share * 100) : compact(cell.item.value) }}
        </small>
      </span>
    </button>

    <!-- Подсказка: при наведении, на сенсорном экране — по нажатию. Своё содержимое — через слот tip -->
    <div v-if="active" class="treemap__tip" :style="tipStyle" role="status">
      <slot name="tip" :item="active.item">
        <strong>
          <i :style="{ background: active.item.color }" aria-hidden="true"></i>
          {{ active.item.label }}
        </strong>
        <span>
          {{ valueLabel }}
          <b>{{ valueText(active.item.value) }}</b>
        </span>
        <span>
          {{ $t('results.stores.share') }}
          <b>{{ percent(active.item.share * 100) }}</b>
        </span>
      </slot>
    </div>
  </div>
</template>

<script>
import { layoutTiles } from '@/utils/treemap'
import numberFormatMixin from '@/mixins/numberFormat'

// Промежуток между плитками, px
const GAP = 3
// Наименьшая доля площади плитки: совсем маленькие доли (0,01 %) иначе были бы тоньше промежутка и не видны.
// Размер такой плитки чуть больше настоящей пропорции, а подпись, подсказка и легенда показывают реальную долю
const MIN_AREA = 0.005
// Минимальный размер плитки для подписей: полная (название, доля, сумма), название с долей, только доля
const LABELS = [
  { id: 'full', w: 86, h: 64 },
  { id: 'name', w: 64, h: 40 },
  { id: 'value', w: 40, h: 20 },
]

// Treemap с подписями и подсказкой. items — [{ id, label, value, color, share? }], color — любой CSS-цвет;
// share — доля в долях, если её нужно считать не от показанных плиток (например, от всех магазинов).
// Раскладка считается под реальный размер блока (высота задаётся снаружи через CSS); размер сообщается событием resize.
export default {
  name: 'TreemapChart',

  mixins: [numberFormatMixin],

  props: {
    items: {
      type: Array,
      required: true,
    },
    // Описание для скринридера
    label: {
      type: String,
      default: '',
    },
    // Подпись суммы в подсказке
    valueLabel: {
      type: String,
      default: '',
    },
    // Наименьшая доля площади плитки (см. layoutTiles)
    minArea: {
      type: Number,
      default: MIN_AREA,
    },
    // Размеры плиток для подписей: [{ id: 'full' | 'name' | 'value', w, h }]
    labelSizes: {
      type: Array,
      default: () => LABELS,
    },
    // Крупно на плитке сумма, а доля мелко (по умолчанию — наоборот)
    valueFirst: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['resize'],

  data() {
    return {
      width: 0,
      height: 0,
      active: null,
      pointer: { x: 0, y: 0 },
    }
  },

  computed: {
    locale() {
      return this.$i18n.locale
    },

    cells() {
      const list = this.items.filter((item) => item.value > 0)
      const total = list.reduce((sum, item) => sum + item.value, 0)
      const withShare = list.map((item) => ({ ...item, share: typeof item.share === 'number' ? item.share : total ? item.value / total : 0 }))
      return layoutTiles(withShare, this.width, this.height, { gap: GAP, minArea: this.minArea, labels: this.labelSizes }).map(({ item, x, y, w, h, label }) => ({
        item,
        label,
        style: { left: `${x}px`, top: `${y}px`, width: `${w}px`, height: `${h}px`, background: item.color },
      }))
    },

    // Подсказка рядом с курсором, не выходит за края блока
    tipStyle() {
      const left = this.pointer.x > this.width - 240 ? this.pointer.x - 232 : this.pointer.x + 14
      const top = this.pointer.y > this.height - 140 ? this.pointer.y - 132 : this.pointer.y + 14
      return { left: `${Math.max(0, left)}px`, top: `${Math.max(0, top)}px` }
    },
  },

  watch: {
    items() {
      this.active = null
    },
  },

  mounted() {
    if ('ResizeObserver' in window) {
      this.observer = new ResizeObserver(([entry]) => this.setSize(entry.contentRect))
      this.observer.observe(this.$refs.stage)
    }
    // Первый размер — сразу: в фоновой вкладке ResizeObserver срабатывает, только когда вкладку откроют
    this.setSize(this.$refs.stage.getBoundingClientRect())
  },

  beforeUnmount() {
    if (this.observer) this.observer.disconnect()
  },

  methods: {
    setSize(rect) {
      this.width = Math.floor(rect.width)
      this.height = Math.floor(rect.height)
      this.$emit('resize', { width: this.width, height: this.height })
    },

    valueText(value) {
      return `${this.money(value)} ${this.$t('kpi.uah')}`
    },

    setPointer(event) {
      const rect = this.$refs.stage.getBoundingClientRect()
      this.pointer = { x: event.clientX - rect.left, y: event.clientY - rect.top }
    },

    onMove(event, cell) {
      if (event.pointerType !== 'mouse') return
      this.setPointer(event)
      this.active = cell
    },

    onTap(event, cell) {
      if (event.pointerType === 'mouse') return
      this.setPointer(event)
      this.active = this.active && this.active.item.id === cell.item.id ? null : cell
    },

    onLeave(event) {
      if (event.pointerType === 'mouse') this.active = null
    },
  },
}
</script>

