<template>
  <v-app>
    <!-- После обновления страницы сверка входа с таблицей занимает время: вместо белого экрана показываем заставку -->
    <transition name="boot">
      <boot-screen v-if="booting" />
    </transition>

    <v-main>
      <router-view />
    </v-main>
  </v-app>
</template>

<script>
import { mapState } from 'pinia'
import BootScreen from '@/components/BootScreen.vue'
import { APP } from '@/configurations'
import { afterLoginRoute, canOpen } from '@/router'
import { useAccessStore } from '@/stores/access'
import { useSettingsStore } from '@/stores/settings'

export default {
  name: 'App',

  components: { BootScreen },

  data() {
    return {
      // Первый переход роутера ещё не завершён (идёт сверка входа)
      booting: true,
    }
  },

  computed: {
    ...mapState(useSettingsStore, ['theme', 'locale']),
    ...mapState(useAccessStore, ['isAuthenticated', 'currentRole']),
  },

  watch: {
    // Вход отозван (выход, истёк срок, пользователя удалили, выход в другой вкладке) — уводим с закрытых страниц.
    // Вход (в этой или в другой вкладке) — уводим со страницы входа туда, куда пользователь шёл (?redirect=).
    // Переход после входа делается только здесь, чтобы два перехода не спорили между собой.
    isAuthenticated(authenticated) {
      if (!authenticated && !this.$route.meta.public) {
        this.$router.replace({ name: 'login' })
      } else if (authenticated && this.$route.name === 'login') {
        this.$router.replace(afterLoginRoute(this.$route.query))
      }
    },

    // Роль сменилась без перехода (сверка с таблицей, вход под другой ролью в соседней вкладке):
    // если текущая страница новой роли недоступна — уводим на её «домашнюю» страницу
    currentRole(role) {
      if (role && !canOpen(this.$route)) this.$router.replace(useAccessStore().homeRoute)
    },

    theme: {
      immediate: true,
      handler(theme) {
        this.$vuetify.theme.change(theme)
      },
    },

    locale: {
      immediate: true,
      handler(locale) {
        this.$i18n.locale = locale
        document.documentElement.lang = locale
      },
    },
  },

  created() {
    // isReady завершается и после успешного перехода, и после редиректа на вход
    this.$router.isReady().finally(() => (this.booting = false))
    document.title = APP.TITLE
    useAccessStore().watchSession()
  },
}
</script>

<style lang="scss" scoped>
// Экран проверки входа плавно исчезает, открывая страницу и общий прелоадер данных
.boot-leave-active {
  transition: opacity 0.6s ease;
}

.boot-leave-to {
  opacity: 0;
}
</style>
