import { NETWORK } from '@/configurations'

// Повтор запроса, пока данные не загрузились. Запрос запоминает token() на старте и передаёт его в schedule():
// после cancel() старый токен недействителен, поэтому запрос, который ещё шёл во время отмены (выход, закрытие блока),
// своей ошибкой уже не запустит новый повтор.
// delay — пауза перед повтором (0 — сразу). Если интернета нет вовсе, повтор ждёт, пока связь появится:
// иначе запрос без сети падал бы мгновенно и повторялся без конца
export function createRetry(delay = NETWORK.RETRY_MS) {
  let timer = null
  let generation = 0
  let waitOnline = null

  function stopWaiting() {
    if (!waitOnline) return
    window.removeEventListener('online', waitOnline)
    waitOnline = null
  }

  function clear() {
    clearTimeout(timer)
    stopWaiting()
  }

  return {
    token: () => generation,

    schedule(token, callback) {
      if (token !== generation) return
      clear()
      if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        waitOnline = () => {
          stopWaiting()
          if (token === generation) callback()
        }
        window.addEventListener('online', waitOnline)
        return
      }
      timer = setTimeout(callback, delay)
    },

    // Убирает запланированный повтор (например, перед новым запросом)
    clear,

    // Останавливает повторы совсем, включая те, что запланирует ещё не завершённый запрос
    cancel() {
      generation += 1
      clear()
    },
  }
}
