// Формулы страницы «Бюджет» — из прежней версии страницы (budget-page-map.md, BudgetPage.vue).

// Строка с детализацией ФОТ по всей сети: в ней заполнены только поля ФОТ, в суммы по сети она не входит
export const FOT_ROW = 'МЕРЕЖА (ФОТ деталізація)'

// Служебные строки: не магазины (офис, склады, сервер, тендер…) и строка ФОТ
export const SPECIAL = new Set([
  FOT_ROW,
  'Офіс Київ',
  'Склад Київ',
  'Тендер',
  'Сервер',
  'Склад Смольная',
  'Склад Київ ТМЦ',
  'Склад',
  'Офіс',
  'Кібер-Бульвар',
])

// Не сравниваются с обычными магазинами на графиках маржинальности и рентабельности
export const MARGIN_EXCLUDED = new Set(['Сервіс Маяковського', 'Інтернет Магазин'])

// Все операционные расходы: 19 статей
export const EXPENSE_FIELDS = [
  'rent',
  'security',
  'transport',
  'fuel',
  'insurance',
  'other_services',
  'utilities',
  'logistics',
  'communication',
  'bank_fees',
  'writeoffs',
  'repr_expenses',
  'repairs',
  'tools',
  'salary',
  'salary_other',
  'salary_travel',
  'marketing',
  'taxes',
]

// Цвет каждой статьи расходов закреплён (как на прежней странице, STORE_CAT_COLORS), а не по месту: при смене языка цвет не «плывёт»
export const EXPENSE_COLORS = {
  salary: '#1150a1',
  rent: '#39a2ed',
  taxes: '#d97706',
  marketing: '#dc2626',
  utilities: '#13cd39',
  logistics: '#7c3aed',
  bank_fees: '#ea580c',
  communication: '#a6a036',
  security: '#65a30d',
  tools: '#db2777',
  writeoffs: '#7c6fd6',
  repairs: '#ea7c1f',
  fuel: '#0d9b8a',
  insurance: '#ca8a04',
  transport: '#e11d48',
  repr_expenses: '#059669',
  salary_other: '#0284c7',
  salary_travel: '#c026d3',
  other_services: '#475569',
}
// Расходы на содержание: 12 статей из EXPENSE_FIELDS, без зарплаты, маркетинга, налогов и ремонта
export const MAINTAIN_FIELDS = EXPENSE_FIELDS.slice(0, 12)

// Пустая ячейка — ноль
export const n = (value) => (typeof value === 'number' && Number.isFinite(value) ? value : 0)

// Операционные расходы строки
export const rowExpenses = (row) => EXPENSE_FIELDS.reduce((sum, field) => sum + n(row[field]), 0)

// Прибуток від діяльності: валовая прибыль минус операционные расходы
export const rowOpProfit = (row) => n(row.profit) - rowExpenses(row)

// Маржинальность: валовая прибыль к доходу
export const rowMargin = (row) => (n(row.revenue) > 0 ? n(row.profit) / n(row.revenue) : 0)

// Рентабельность: прибуток від діяльності к доходу
export const rowProfitability = (row) => (n(row.revenue) > 0 ? rowOpProfit(row) / n(row.revenue) : 0)

// Рентабельность после офиса: готовое значение из таблицы (rentab_after), пустая ячейка — ноль
export const rowProfitabilityAfter = (row) => n(row.rentab_after)

// Итоги по сети целиком (с офисом и складами, без строки ФОТ): доход, валовая прибыль, расходы, чистая прибыль
export function networkTotals(rows) {
  const all = rows.filter((row) => row.store !== FOT_ROW)
  const revenue = all.reduce((sum, row) => sum + n(row.revenue), 0)
  const profit = all.reduce((sum, row) => sum + n(row.profit), 0)
  const expenses = all.reduce((sum, row) => sum + rowExpenses(row), 0)
  return { revenue, profit, expenses, net: profit - expenses }
}
