<template>
  <article class="tm">
    <!-- Сводка -->
    <div class="tm__bar">
      <ul class="tm__stats">
        <li>
          <span>{{ $t('results.stores.count') }}</span>
          <b>{{ stores.length }}</b>
        </li>
        <li>
          <span>{{ $t('results.stores.total') }}</span>
          <b>{{ compact(total) }}</b>
        </li>
        <li>
          <span>{{ $t('results.stores.top3') }}</span>
          <b>{{ percent(topShare * 100) }}</b>
        </li>
      </ul>

    </div>

    <treemap-chart
      class="tm__stage"
      :items="tileItems"
      :label="$t('results.stores.title')"
      :min-area="minArea"
      :label-sizes="labelSizes"
      value-first
      @resize="width = $event.width"
    >
      <!-- Подсказка по магазину: место, доход, доля и выполнение плана -->
      <template #tip="{ item }">
        <span class="tm__tip-rank">#{{ item.rank }}</span>
        <strong class="tm__tip-name">{{ item.label }}</strong>
        <span class="tm__tip-row">
          {{ $t('results.stores.revenue') }}
          <b>{{ money(item.value) }} {{ $t('kpi.uah') }}</b>
        </span>
        <span class="tm__tip-row">
          {{ $t('results.stores.share') }}
          <b>{{ percent(item.share * 100) }}</b>
        </span>
        <span class="tm__tip-row">
          {{ $t('results.stores.plan') }}
          <b>{{ item.plan === null ? '—' : percent(item.plan) }}</b>
        </span>
      </template>
    </treemap-chart>

    <!-- Узкий блок: магазины вне топа одной строкой -->
    <p v-if="rest" class="tm__rest">
      <span>{{ $t('results.stores.others', { n: rest.count }) }}</span>
      <b>{{ compact(rest.revenue) }}</b>
      <small>{{ percent(rest.share * 100) }}</small>
    </p>

    <!-- Легенда цвета: по месту магазина, как на прежней странице -->
    <div class="tm__legend">
      <span>{{ $t('results.stores.more') }}</span>
      <i class="tm__scale" aria-hidden="true"></i>
      <span>{{ $t('results.stores.less') }}</span>
    </div>
  </article>
</template>

<script>
import { mapState } from 'pinia'
import { useResultsStore } from '@/stores/results'
import { useScopeStore } from '@/stores/scope'
import { gradientRgb } from '@/utils/color'
import TreemapChart from '@/components/TreemapChart.vue'
import numberFormatMixin from '@/mixins/numberFormat'

// Наименьшая доля площади плитки: самые маленькие магазины иначе были бы тоньше промежутка и пропали бы
// (размер такой плитки чуть больше настоящей пропорции, подсказка показывает настоящие цифры)
const MIN_AREA = 0.003
// На узком блоке все магазины не помещаются: плитками показываются крупнейшие, остальные — строкой под ними.
// width — ширина блока до (px), tiles — сколько магазинов показывать плитками
const LIMITS = [
  { width: 600, tiles: 15 },
  { width: 1000, tiles: 28 },
]
// Минимальный размер плитки для подписей: полная (название, сумма, доля), название с суммой, только сумма
const LABELS = [
  { id: 'full', w: 118, h: 76 },
  { id: 'name', w: 72, h: 42 },
  { id: 'value', w: 64, h: 22 },
]

export default {
  name: 'ResultsStoresTreemap',

  components: { TreemapChart },

  mixins: [numberFormatMixin],

  data() {
    return {
      minArea: MIN_AREA,
      labelSizes: LABELS,
      // Ширина области плиток: от неё зависит, сколько магазинов показать плитками
      width: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    // Магазины периода с долей, местом и выполнением плана (из stores_detail, если магазин там есть)
    stores() {
      const store = useResultsStore()
      const plans = Object.fromEntries(store.rowsOf('stores_detail', this.period).map((row) => [row.store, row.plan_pct]))
      const rows = store
        .rowsOf('stores_revenue', this.period)
        .filter((row) => typeof row.revenue === 'number' && row.revenue > 0)
        .sort((a, b) => b.revenue - a.revenue)
      const total = rows.reduce((sum, row) => sum + row.revenue, 0)
      return rows.map((row, index) => {
        const plan = typeof plans[row.store] === 'number' ? plans[row.store] * 100 : null
        return { store: row.store, revenue: row.revenue, value: row.revenue, share: total ? row.revenue / total : 0, rank: index + 1, plan }
      })
    },

    total() {
      return this.stores.reduce((sum, item) => sum + item.revenue, 0)
    },

    topShare() {
      return this.stores.slice(0, 3).reduce((sum, item) => sum + item.share, 0)
    },

    // Сколько магазинов показать плитками при текущей ширине; null — все
    limit() {
      const rule = LIMITS.find((item) => this.width > 0 && this.width < item.width)
      return rule && this.stores.length > rule.tiles + 1 ? rule.tiles : null
    },

    // Плитки: все магазины, а на узком блоке — только крупнейшие
    tiles() {
      return this.limit ? this.stores.slice(0, this.limit) : this.stores
    },

    // Магазины, которые на узком блоке не показаны плитками
    rest() {
      if (!this.limit) return null
      const list = this.stores.slice(this.limit)
      return { count: list.length, revenue: list.reduce((sum, item) => sum + item.revenue, 0), share: list.reduce((sum, item) => sum + item.share, 0) }
    },

    // Плитки для treemap. Цвет по месту магазина среди всех магазинов (_tmColor прежней страницы):
    // самый большой доход — зелёный, средние — жёлтые, самые маленькие — красные
    tileItems() {
      const count = this.stores.length
      return this.tiles.map((item) => ({
        id: item.store,
        label: item.store,
        value: item.revenue,
        share: item.share,
        rank: item.rank,
        plan: item.plan,
        color: `rgb(${gradientRgb(1 - (count > 1 ? (item.rank - 1) / (count - 1) : 0))})`,
      }))
    },
  },

}
</script>

