<template>
  <section class="overview" :aria-label="$t('results.overview.title')">
    <!-- Выполнение плана и доход: главная карточка блока -->
    <article class="plan" :class="`plan--${state}`">
      <header class="plan__head">
        <span class="plan__icon" aria-hidden="true">
          <v-icon :icon="mdiBullseyeArrow" size="22" />
        </span>
        <div class="plan__heading">
          <h3 class="plan__title">{{ $t('results.overview.plan') }}</h3>
          <span v-if="period" class="plan__period">
            <i class="plan__dot" aria-hidden="true"></i>
            {{ period }}
          </span>
        </div>
        <span v-if="!loading && percent !== null" class="plan__status">{{ $t(`results.overview.status.${state}`) }}</span>
      </header>

      <div class="plan__body">
        <div class="plan__gauge" role="img" :aria-label="`${$t('results.overview.plan')}: ${percentText}`">
          <svg viewBox="0 0 240 132" class="plan__svg">
            <defs>
              <linearGradient :id="gradientId" x1="0" x2="1" y1="0" y2="0">
                <stop offset="0" class="plan__stop plan__stop--from" />
                <stop offset="1" class="plan__stop plan__stop--to" />
              </linearGradient>
            </defs>

            <path :d="arc(96)" class="plan__track" pathLength="100" />
            <path
              v-if="!loading"
              :d="arc(96)"
              class="plan__fill"
              :stroke="`url(#${gradientId})`"
              pathLength="100"
              :stroke-dasharray="`${Math.max(0.01, fillFraction * 100)} 100`"
            />

            <circle v-if="!loading && fillFraction > 0" v-bind="knob" r="7" class="plan__knob" />
          </svg>

          <div class="plan__center">
            <span v-if="loading" class="plan__skeleton plan__skeleton--value"></span>
            <strong v-else class="plan__value">{{ percentText }}</strong>
            <span class="plan__caption">{{ $t('kpi.done') }}</span>
          </div>

          <div class="plan__scale" aria-hidden="true">
            <span>0%</span>
            <span>100%</span>
          </div>
        </div>

        <div class="plan__side">
          <div class="plan__revenue">
            <span class="plan__label">{{ $t('results.overview.revenue') }}</span>
            <span v-if="loading" class="plan__skeleton plan__skeleton--revenue"></span>
            <strong v-else class="plan__money">
              {{ number(shownRevenue, 0) }}
              <small>{{ $t('kpi.uah') }}</small>
            </strong>
          </div>

          <div v-if="!loading && gap !== null" class="plan__gap" :class="gap >= 0 ? 'plan__gap--up' : 'plan__gap--down'">
            <v-icon :icon="gap >= 0 ? mdiTrendingUp : mdiTrendingDown" size="16" />
            {{ $t(gap >= 0 ? 'results.overview.overPlan' : 'results.overview.underPlan', { value: `${number(Math.abs(gap), 1)}%` }) }}
          </div>
        </div>
      </div>
    </article>

    <!-- Трафик, чек и конверсия: значение месяца против среднего за год и прошлого года -->
    <div class="overview__metrics">
      <article
        v-for="(item, index) in metrics"
        :key="item.id"
        class="metric"
        :style="{ '--accent': item.accent, '--i': index + 1 }"
      >
        <header class="metric__head">
          <span class="metric__icon" aria-hidden="true">
            <v-icon :icon="item.icon" size="20" />
          </span>
          <h3 class="metric__title">{{ $t(item.title) }}</h3>
        </header>

        <span v-if="loading" class="metric__skeleton metric__skeleton--hero"></span>
        <strong v-else class="metric__hero">{{ format(item, item.current === null ? null : item.current * progress) }}</strong>

        <ul class="metric__compare">
          <li v-for="line in item.lines" :key="line.key" class="metric__line">
            <span class="metric__name">{{ $t(`results.overview.${line.key}`) }}</span>

            <span class="metric__bars" aria-hidden="true">
              <i class="metric__bar metric__bar--current" :style="{ width: `${barWidth(item, item.current)}%` }"></i>
              <i class="metric__bar metric__bar--base" :style="{ width: `${barWidth(item, line.value)}%` }"></i>
            </span>

            <span class="metric__base">{{ loading ? '—' : format(item, line.value) }}</span>

            <span v-if="!loading" class="metric__delta" :class="`metric__delta--${line.trend}`">
              <span aria-hidden="true">{{ arrows[line.trend] }}</span>
              {{ deltaText(item, line) }}
            </span>
          </li>
        </ul>
      </article>
    </div>
