</template>

<script>
import { mapState } from 'pinia'
import { mdiAccountGroupOutline, mdiBullseyeArrow, mdiPercentOutline, mdiReceiptTextOutline, mdiTrendingDown, mdiTrendingUp } from '@mdi/js'
import { useResultsStore } from '@/stores/results'
import { useScopeStore } from '@/stores/scope'
import { numberFormat } from '@/utils/format'
import { statusOf } from '@/utils/kpi'
import { animateProgress } from '@/utils/tween'

// Геометрия полукруглой шкалы: центр и радиус основной дуги в координатах viewBox
const CX = 120
const CY = 124
// Разница меньше 0,2 % считается «без изменений», чтобы стрелка не дёргалась на шуме
const NEUTRAL = 0.002

// Показатели с сравнением. field — значение месяца, year — среднее за год, past — прошлый год.
// percent — значение в долях (0,226 → 22,6 %), разница с ним считается в процентных пунктах.
// accent — свой цвет карточки (RGB через запятую): здесь нет плана, поэтому цвет не несёт состояния.
const METRICS = [
  { id: 'traffic', icon: mdiAccountGroupOutline, title: 'results.overview.traffic', field: 'avg_traffic_day', year: 'avg_traffic_year', past: 'avg_traffic_ly', digits: 0, accent: '14, 165, 233' },
  { id: 'check', icon: mdiReceiptTextOutline, title: 'results.overview.check', field: 'avg_check', year: 'avg_check_year', past: 'avg_check_ly', digits: 0, accent: '245, 158, 11' },
  { id: 'conversion', icon: mdiPercentOutline, title: 'results.overview.conversion', field: 'conversion', year: 'conversion_year', past: 'conversion_ly', digits: 1, percent: true, accent: '16, 185, 129' },
]

const numeric = (value) => (typeof value === 'number' && Number.isFinite(value) ? value : null)

function trendOf(current, base) {
  if (current === null || base === null || base === 0) return 'flat'
  const diff = (current - base) / Math.abs(base)
  if (diff > NEUTRAL) return 'up'
  return diff < -NEUTRAL ? 'down' : 'flat'
}

export default {
  name: 'ResultsOverview',

  data() {
    return {
      mdiBullseyeArrow,
      mdiTrendingDown,
      mdiTrendingUp,
      arrows: { up: '▲', down: '▼', flat: '●' },
      // Ход анимации появления от 0 до 1: «набегают» числа и заполняется шкала
      progress: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),
    ...mapState(useResultsStore, ['tables']),

    locale() {
      return this.$i18n.locale
    },

    // Строка main_kpi выбранного периода
    row() {
      return this.tables ? this.tables.main_kpi.find((item) => item.period === this.period) || null : null
    },

    loading() {
      return !this.row
    },

    // Выполнение плана в процентах: 1,076 → 107,6
    percent() {
      const value = this.row && numeric(this.row.plan_pct)
      return value === null || value === undefined ? null : value * 100
    },

    state() {
      return this.loading ? 'none' : statusOf(this.percent)
    },

    percentText() {
      return this.percent === null ? '—' : `${this.number(this.percent * this.progress, 1)}%`
    },

    // Сколько процентов до плана (минус) или сверх плана (плюс)
    gap() {
      return this.percent === null ? null : this.percent - 100
    },

    fillFraction() {
      return this.percent === null ? 0 : (Math.min(100, Math.max(0, this.percent)) / 100) * this.progress
    },

    // Точка на конце заполненной дуги
    knob() {
      const angle = Math.PI * this.fillFraction
      return { cx: CX - 96 * Math.cos(angle), cy: CY - 96 * Math.sin(angle) }
    },

    revenue() {
      return this.row ? numeric(this.row.revenue) : null
    },

    shownRevenue() {
      return this.revenue === null ? null : this.revenue * this.progress
    },

    metrics() {
      const row = this.row || {}
      return METRICS.map((metric) => {
        const current = numeric(row[metric.field])
        const lines = [
          { key: 'yearAvg', value: numeric(row[metric.year]) },
          { key: 'pastYear', value: numeric(row[metric.past]) },
        ].map((line) => ({ ...line, trend: trendOf(current, line.value) }))
        const max = Math.max(current || 0, ...lines.map((line) => line.value || 0))
        return { ...metric, current, lines, max }
      })
    },

    gradientId() {
      return `results-plan-${this.$.uid}`
    },

    // Меняется, когда пришли другие значения: тогда анимация проигрывается заново
    signature() {
      return this.row ? `${this.row.period}|${this.row.plan_pct}|${this.row.revenue}` : ''
    },
  },

  watch: {
    signature: {
      immediate: true,
      handler(value) {
        if (this.stopTween) this.stopTween()
        if (value) this.stopTween = animateProgress((progress) => (this.progress = progress), { delay: 150 })
      },
    },
  },

  beforeUnmount() {
    if (this.stopTween) this.stopTween()
  },

  methods: {
    number(value, digits) {
      if (typeof value !== 'number') return '—'
      return numberFormat(this.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value)
    },

    // Значение показателя с единицей: у конверсии — проценты
    format(metric, value) {
      if (value === null || value === undefined) return '—'
      return metric.percent ? `${this.number(value * 100, metric.digits)}%` : this.number(value, metric.digits)
    },

    // Разница с базой: у конверсии в процентных пунктах, у остальных в процентах
    deltaText(metric, line) {
      if (metric.current === null || line.value === null || line.value === 0) return '—'
      const sign = (value) => (value > 0 ? '+' : value < 0 ? '−' : '')
      if (metric.percent) {
        const points = (metric.current - line.value) * 100
        return `${sign(points)}${this.number(Math.abs(points), 1)} ${this.$t('results.overview.points')}`
      }
      const diff = ((metric.current - line.value) / Math.abs(line.value)) * 100
      return `${sign(diff)}${this.number(Math.abs(diff), 1)}%`
    },

    // Ширина полоски сравнения относительно наибольшего из трёх значений карточки
    barWidth(metric, value) {
      if (this.loading || !metric.max || value === null) return 0
      return (Math.max(0, value) / metric.max) * 100 * this.progress
    },

    // Полукруг радиуса radius слева направо
    arc(radius) {
      return `M ${CX - radius} ${CY} A ${radius} ${radius} 0 0 1 ${CX + radius} ${CY}`
    },
  },
}
</script>

