import { defineStore } from 'pinia'
import { NETWORK, STORAGE_KEYS, WEATHER } from '@/configurations'
import { fetchWeather } from '@/services/weather'
import { createRetry } from '@/utils/retry'
import { readStorage, writeStorage } from '@/utils/storage'

const cityIds = WEATHER.CITIES.map((city) => city.id)

// Ответы приходят в произвольном порядке: побеждает только последний запрос
let requestId = 0
const retry = createRetry(NETWORK.SIDE_RETRY_MS)

export const useWeatherStore = defineStore('weather', {
  state: () => {
    const saved = readStorage(STORAGE_KEYS.WEATHER_CITY)
    return {
      city: cityIds.includes(saved) ? saved : WEATHER.DEFAULT_CITY,
      data: null,
      loading: false,
      // Погоды ещё нет, а последняя попытка загрузки не удалась
      failed: false,
      // Когда и на каком языке получена погода: по ним видно, нужно ли запрашивать снова
      loadedAt: 0,
      lang: '',
    }
  },

  actions: {
    cancelRetry() {
      retry.cancel()
    },

    setCity(id, lang) {
      if (!cityIds.includes(id) || id === this.city) return
      this.city = id
      writeStorage(STORAGE_KEYS.WEATHER_CITY, id)
      // Погода прежнего города не должна выглядеть как погода нового
      this.data = null
      this.failed = false
      return this.load(lang)
    },

    // Загружает погоду, только если её нет, она на другом языке или устарела (старше WEATHER.REFRESH_MS).
    // Блок погоды в шапке появляется и исчезает при смене ширины экрана — лишних запросов при этом нет.
    ensure(lang) {
      if (this.data && this.lang === lang && Date.now() - this.loadedAt < WEATHER.REFRESH_MS) return
      return this.load(lang)
    },

    // Пока погоды нет, запрос повторяется каждые NETWORK.SIDE_RETRY_MS, а интерфейс показывает индикатор загрузки
    async load(lang) {
      retry.clear()
      const token = retry.token()
      const id = ++requestId
      const { query } = WEATHER.CITIES.find((city) => city.id === this.city)
      this.loading = true
      try {
        const data = await fetchWeather(query, lang)
        if (id !== requestId) return
        this.data = data
        this.failed = false
        this.loadedAt = Date.now()
        this.lang = lang
      } catch {
        if (id !== requestId) return
        if (!this.data) {
          this.failed = true
          retry.schedule(token, () => this.load(lang))
        }
      } finally {
        if (id === requestId) this.loading = false
      }
    },
  },
})
