const NEUTRAL_RGB = '148, 163, 184'
const cache = {}
let context = null

// Любой CSS-цвет (#rgb, #rrggbb, 'crimson', 'rgb(200, 0, 0)', 'hsl(...)') → строка «r, g, b» для rgba(var(--x), 0.5).
// Разбирает сам браузер: холст приводит цвет к #rrggbb или rgba(...). Если цвет не разобрать — нейтральный серый.
export function colorToRgb(color) {
  const key = String(color).trim()
  if (!(key in cache)) cache[key] = parseColor(key)
  return cache[key]
}

function parseColor(color) {
  if (!context) context = document.createElement('canvas').getContext('2d')
  if (!context || !color) return NEUTRAL_RGB
  // Неверный цвет холст пропускает и оставляет прежний: сравниваем с двумя разными исходными значениями
  const read = (initial) => {
    context.fillStyle = initial
    context.fillStyle = color
    return context.fillStyle
  }
  const value = read('#000000')
  if (value !== read('#ffffff')) return NEUTRAL_RGB

  const hex = /^#([0-9a-f]{6})$/i.exec(value)
  if (hex) {
    const number = parseInt(hex[1], 16)
    return `${(number >> 16) & 255}, ${(number >> 8) & 255}, ${number & 255}`
  }
  const rgb = /^rgba?\(\s*(\d+),\s*(\d+),\s*(\d+)/i.exec(value)
  return rgb ? `${rgb[1]}, ${rgb[2]}, ${rgb[3]}` : NEUTRAL_RGB
}

// Цвета состояния выполнения плана: это переменные темы, поэтому цвет сам меняется в светлой и тёмной теме
const STATE_RGB = {
  good: 'var(--v-theme-success)',
  warn: 'var(--v-theme-warning)',
  bad: 'var(--v-theme-error)',
  // Нет плана или данных: нейтральный серо-голубой, а не чёрный
  none: NEUTRAL_RGB,
}

// Цвет записи в блоках сравнения (значение для --mc: RGB через запятую или переменная темы).
// На главной у каждого менеджера свой цвет из конфигурации. На странице РМ сравниваются магазины: они красятся
// не цветом менеджера, а по показателю — состоянием выполнения плана (зелёный, оранжевый, красный), как карточки.
export function entryRgb(kind, manager, state) {
  return kind === 'stores' ? STATE_RGB[state] || STATE_RGB.none : colorToRgb(manager.color)
}

// Градиент «плохо → нормально → хорошо» страницы итогов (как в прежней версии): красный → жёлтый → зелёный.
// t от 0 до 1; возвращает «r, g, b».
const GRADIENT = [
  [239, 68, 68],
  [234, 179, 8],
  [34, 197, 94],
]

export function gradientRgb(t) {
  if (!Number.isFinite(t)) return NEUTRAL_RGB
  const clamped = Math.min(1, Math.max(0, t))
  const [from, to, local] = clamped <= 0.5 ? [GRADIENT[0], GRADIENT[1], clamped * 2] : [GRADIENT[1], GRADIENT[2], (clamped - 0.5) * 2]
  return from.map((channel, index) => Math.round(channel + (to[index] - channel) * local)).join(', ')
}

// Асимметричный градиент: жёлтая середина не посередине шкалы, а на пороге center (например, +4 % роста).
// Значения от min до center — красно-жёлтая половина, от center до max — жёлто-зелёная.
export function centeredGradientRgb(value, min, max, center) {
  if (value <= center) return gradientRgb(center > min ? ((value - min) / (center - min)) * 0.5 : 0)
  return gradientRgb(max > center ? 0.5 + ((value - center) / (max - center)) * 0.5 : 1)
}

// Градиент по трём порогам метрики (_rmColor прежней страницы): red — красный, yellow — жёлтый, green — зелёный.
// Ниже red — красный, выше green — зелёный, между порогами — плавный переход.
export function thresholdGradientRgb(value, { red, yellow, green }) {
  if (!Number.isFinite(value)) return NEUTRAL_RGB
  // Совпадающие пороги: до порога — сразу его цвет, без деления на ноль
  const lower = yellow > red ? ((value - red) / (yellow - red)) * 0.5 : 0.5
  const upper = green > yellow ? 0.5 + ((value - yellow) / (green - yellow)) * 0.5 : 1
  return gradientRgb(value <= yellow ? lower : upper)
}
