<template>
  <budget-bars
    :label="$t('budget.margin.title')"
    :rows="rows"
    :series="series"
    :stats-start="[{ id: 'average', label: $t('budget.margin.average'), value: percent(average * 100) }]"
    :stats-end="zones"
  />
</template>

<script>
import { mapState } from 'pinia'
import BudgetBars from '@/components/BudgetBars.vue'
import numberFormatMixin from '@/mixins/numberFormat'
import { useBudgetStore } from '@/stores/budget'
import { useScopeStore } from '@/stores/scope'
import { MARGIN_EXCLUDED, SPECIAL, n, rowMargin } from '@/utils/budget'

// Зоны маржинальности и цвета — как на прежней странице: от 25 % зелёный, от 15 % оранжевый, ниже — красный
const ZONES = [
  { id: 'good', from: 0.25, color: 'rgba(34, 197, 94, 0.85)', label: '≥25%' },
  { id: 'mid', from: 0.15, color: 'rgba(245, 158, 11, 0.85)', label: '15–25%' },
  { id: 'low', from: -Infinity, color: 'rgba(239, 68, 68, 0.85)', label: '<15%' },
]
const zoneOf = (margin) => ZONES.find((zone) => margin >= zone.from)

// Маржинальность магазинов за месяц (budget-page-map.md, блок 7–9): валовая прибыль к доходу. Только магазины
// (без служебных строк), без Інтернет-магазину и Сервісу Маяковського — они несопоставимы с обычными магазинами
export default {
  name: 'BudgetMargin',

  components: { BudgetBars },

  mixins: [numberFormatMixin],

  computed: {
    ...mapState(useScopeStore, ['period']),

    stores() {
      return useBudgetStore()
        .rowsOf(this.period)
        .filter((row) => !SPECIAL.has(row.store) && !MARGIN_EXCLUDED.has(row.store) && n(row.revenue) > 0)
        .map((row) => ({ store: row.store, revenue: n(row.revenue), profit: n(row.profit), margin: rowMargin(row) }))
        .sort((a, b) => b.margin - a.margin)
    },

    // Средняя по этим магазинам: сумма валовой прибыли к сумме дохода
    average() {
      const revenue = this.stores.reduce((sum, row) => sum + row.revenue, 0)
      return revenue ? this.stores.reduce((sum, row) => sum + row.profit, 0) / revenue : 0
    },

    // Сколько магазинов в каждой зоне; цвет зоны — это же легенда столбиков
    zones() {
      return ZONES.map((zone) => ({ id: zone.id, label: zone.label, color: zone.color, value: this.stores.filter((row) => zoneOf(row.margin) === zone).length }))
    },

    series() {
      return [{ id: 'margin', label: this.$t('budget.margin.margin'), color: (margin) => zoneOf(margin).color }]
    },

    rows() {
      const uah = this.$t('kpi.uah')
      return this.stores.map((row) => ({
        label: row.store,
        values: [row.margin],
        extra: [`${this.$t('budget.kpi.revenue')}: ${this.money(row.revenue)} ${uah}`, `${this.$t('budget.kpi.profit')}: ${this.money(row.profit)} ${uah}`],
      }))
    },
  },
}
</script>
