// Круговая диаграмма с выносками (callout pie) — алгоритм прежней страницы итогов (ResultsPage.vue, «Офіс Київ» в BudgetPage).
// Подписи стоят вокруг круга: слева и справа — столбиком, сверху и снизу — строкой; алгоритм сам раздвигает их,
// чтобы не накладывались. Все размеры — в единицах viewBox (текст рассчитан на font-size ≈ 26).

export const CALLOUT_R = 360
const SIDE_GAP = 25
const LABEL_GAP = 30
const CALLOUT_LINE_H = 32
// Средняя ширина символа при font-size 26 (шрифт Manrope)
const CHAR_W = 15.6
const WRAP_CHARS = 13
const ROW_GAP = 40
const GAP_X = 50
const CROSS_BUFFER = 24

const elbowAt = (r) => r + SIDE_GAP
const labelAt = (r) => r + SIDE_GAP + LABEL_GAP

// Длинное название делится на две строки по пробелу ближе к середине
function wrapLabel(label) {
  if (label.length <= WRAP_CHARS) return [label]
  const mid = Math.floor(label.length / 2)
  let index = label.lastIndexOf(' ', mid)
  if (index <= 0) index = label.indexOf(' ', mid)
  if (index <= 0) return [label]
  return [label.slice(0, index), label.slice(index + 1)]
}

// Высота подписи: строки названия + сумма + процент (в компактном виде сумма и процент — одна строка)
const rowHeight = (item) => (item.lines.length + (item.inline ? 1 : 2)) * CALLOUT_LINE_H

// Сектор кольца: от угла start до end, радиусы outer и inner (inner = 0 — обычный сектор круга)
export function ringPath(start, end, outer, inner = 0) {
  const point = (radius, angle) => `${(radius * Math.cos(angle)).toFixed(2)},${(radius * Math.sin(angle)).toFixed(2)}`
  const large = end - start > Math.PI ? 1 : 0
  if (!inner) return `M0,0 L${point(outer, start)} A${outer},${outer},0,${large},1,${point(outer, end)} Z`
  return `M${point(outer, start)} A${outer},${outer},0,${large},1,${point(outer, end)} L${point(inner, end)} A${inner},${inner},0,${large},0,${point(inner, start)} Z`
}

function buildSegments(items, total, startAngle) {
  let angle = startAngle
  return items.map((item) => {
    const sweep = total > 0 ? (item.value / total) * 2 * Math.PI : 0
    const start = angle
    angle += sweep
    return { ...item, start, end: angle, midA: start + sweep / 2, share: total > 0 ? item.value / total : 0 }
  })
}

function classify(segments, r, format, inline) {
  return segments.map((segment) => {
    const cos = Math.cos(segment.midA)
    const sin = Math.sin(segment.midA)
    const zone = Math.abs(cos) >= Math.abs(sin) ? (cos > 0 ? 'right' : 'left') : sin > 0 ? 'bottom' : 'top'
    const lines = wrapLabel(segment.label)
    const valueText = format.value(segment.value)
    const shareText = format.share(segment.share)
    const numbers = inline ? [`${valueText} · ${shareText}`] : [valueText, shareText]
    const textWidth = Math.max(...[...lines, ...numbers].map((line) => line.length * CHAR_W))
    return { ...segment, zone, lines, valueText, shareText, inline, textWidth, edgeX: r * cos, edgeY: r * sin }
  })
}

// Слева и справа: подписи раздвигаются по вертикали
function resolveVertical(group, rowGap) {
  group.forEach((item) => (item.rawY = item.edgeY))
  group.sort((a, b) => a.rawY - b.rawY)
  for (let i = 1; i < group.length; i++) {
    const minGap = (rowHeight(group[i - 1]) + rowHeight(group[i])) / 2 + rowGap
    if (group[i].rawY - group[i - 1].rawY < minGap) group[i].rawY = group[i - 1].rawY + minGap
  }
  for (let i = group.length - 2; i >= 0; i--) {
    const minGap = (rowHeight(group[i]) + rowHeight(group[i + 1])) / 2 + rowGap
    if (group[i + 1].rawY - group[i].rawY < minGap) group[i].rawY = group[i + 1].rawY - minGap
  }
  if (group.length) {
    const center = (group[0].rawY + group[group.length - 1].rawY) / 2
    group.forEach((item) => (item.rawY -= center))
  }
}

// Сверху и снизу: подписи раздвигаются по горизонтали
function resolveHorizontal(group) {
  group.forEach((item) => (item.rawX = item.edgeX))
  group.sort((a, b) => a.rawX - b.rawX)
  for (let i = 1; i < group.length; i++) {
    const minGap = (group[i - 1].textWidth + group[i].textWidth) / 2 + GAP_X
    if (group[i].rawX - group[i - 1].rawX < minGap) group[i].rawX = group[i - 1].rawX + minGap
  }
  for (let i = group.length - 2; i >= 0; i--) {
    const minGap = (group[i].textWidth + group[i + 1].textWidth) / 2 + GAP_X
    if (group[i + 1].rawX - group[i].rawX < minGap) group[i].rawX = group[i + 1].rawX - minGap
  }
  if (group.length) {
    const center = (group[0].rawX + group[group.length - 1].rawX) / 2
    group.forEach((item) => (item.rawX -= center))
  }
}

// Итоговое положение подписи: линия-выноска (points) и строки текста с ролью (name, value, share).
// В компактном виде у строки суммы есть extra — процент, который рисуется в той же строке
function finalize(item, r, extraPush) {
  const texts = [
    ...item.lines.map((text) => ({ text, role: 'name' })),
    ...(item.inline
      ? [{ text: item.valueText, role: 'value', extra: item.shareText }]
      : [
          { text: item.valueText, role: 'value' },
          { text: item.shareText, role: 'share' },
        ]),
  ]
  let textX
  let anchor
  let baselines
  let points
  if (item.zone === 'left' || item.zone === 'right') {
    const sign = item.zone === 'left' ? -1 : 1
    textX = sign * labelAt(r)
    anchor = item.zone === 'left' ? 'end' : 'start'
    const top = item.rawY - (texts.length * CALLOUT_LINE_H) / 2 + CALLOUT_LINE_H * 0.8
    baselines = texts.map((_, index) => top + index * CALLOUT_LINE_H)
    const elbowX = sign * elbowAt(r)
    points = `${item.edgeX.toFixed(1)},${item.edgeY.toFixed(1)} ${elbowX.toFixed(1)},${item.rawY.toFixed(1)} ${(textX - sign * 8).toFixed(1)},${item.rawY.toFixed(1)}`
  } else {
    const sign = item.zone === 'top' ? -1 : 1
    const labelY = sign * (labelAt(r) + extraPush)
    textX = item.rawX
    anchor = 'middle'
    baselines = texts.map((_, index) =>
      item.zone === 'top' ? labelY - (texts.length - 1 - index) * CALLOUT_LINE_H : labelY + (index + 0.6) * CALLOUT_LINE_H,
    )
    const elbowY = sign * (elbowAt(r) + extraPush)
    points = `${item.edgeX.toFixed(1)},${item.edgeY.toFixed(1)} ${item.rawX.toFixed(1)},${elbowY.toFixed(1)} ${item.rawX.toFixed(1)},${(labelY - sign * 6).toFixed(1)}`
  }
  return {
    ...item,
    textX,
    anchor,
    points,
    texts: texts.map((line, index) => ({ ...line, y: baselines[index].toFixed(1) })),
  }
}

// items — [{ label, value, color, ... }] по убыванию. Все попадают в круг; подписи — только у долей от minShare.
// format.value(value) и format.share(share) — тексты суммы и доли. startAngle — где начинается первый сектор
// (радианы от «3 часов» по часовой; по умолчанию сверху). inline — компактные подписи: сумма и процент в одной строке,
// rowGap — промежуток между подписями в столбике: меньше — столбик короче и выноски короче.
// Возвращает { segments, labels, halfWidth, halfHeight, total }: центр круга в (0, 0), viewBox — 2·halfWidth × 2·halfHeight.
export function calloutLayout(items, { r = CALLOUT_R, minShare = 0, startAngle = -Math.PI / 2, inline = false, rowGap = ROW_GAP, format }) {
  const total = items.reduce((sum, item) => sum + item.value, 0)
  if (!items.length || !total) return { segments: [], labels: [], halfWidth: r, halfHeight: r, total }

  const segments = buildSegments(items, total, startAngle)
  const classified = classify(
    segments.filter((segment) => segment.share >= minShare),
    r,
    format,
    inline,
  )
  const byZone = (zone) => classified.filter((item) => item.zone === zone)
  resolveVertical(byZone('left'), rowGap)
  resolveVertical(byZone('right'), rowGap)
  resolveHorizontal(byZone('top'))
  resolveHorizontal(byZone('bottom'))

  const left = byZone('left')
  const right = byZone('right')
  const top = byZone('top')
  const bottom = byZone('bottom')
  const label = labelAt(r)
  const maxOf = (list, fn) => (list.length ? Math.max(...list.map(fn)) : 0)

  // Подписи сбоку не должны пересекаться с подписями сверху и снизу: верхние и нижние отодвигаются дальше
  const sides = [...left, ...right]
  const sideTop = sides.length ? Math.max(0, ...sides.map((item) => -(item.rawY - rowHeight(item) / 2))) : 0
  const sideBottom = sides.length ? Math.max(0, ...sides.map((item) => item.rawY + rowHeight(item) / 2)) : 0
  const topPush = top.length ? Math.max(0, sideTop + CROSS_BUFFER - label) : 0
  const bottomPush = bottom.length ? Math.max(0, sideBottom + CROSS_BUFFER - label) : 0

  const halfWidth = Math.max(
    r,
    label + maxOf(left, (item) => item.textWidth),
    label + maxOf(right, (item) => item.textWidth),
    maxOf(top, (item) => Math.abs(item.rawX) + item.textWidth / 2) + 16,
    maxOf(bottom, (item) => Math.abs(item.rawX) + item.textWidth / 2) + 16,
  )
  const halfHeight = Math.max(
    r,
    maxOf(left, (item) => Math.abs(item.rawY) + rowHeight(item) / 2) + 10,
    maxOf(right, (item) => Math.abs(item.rawY) + rowHeight(item) / 2) + 10,
    label + topPush + maxOf(top, rowHeight),
    label + bottomPush + maxOf(bottom, rowHeight),
  )

  const labels = classified.map((item) => finalize(item, r, item.zone === 'top' ? topPush : item.zone === 'bottom' ? bottomPush : 0))
  return { segments, labels, halfWidth, halfHeight, total }
}
