// Форматтеры Intl дорого создавать, а числа на странице перерисовываются в анимации десятки раз в секунду.
// Поэтому форматтер создаётся один раз на каждую пару «язык + настройки» и дальше берётся из кэша.
const cache = new Map()

function cached(Formatter, locale, options) {
  const key = `${Formatter.name}|${locale}|${JSON.stringify(options)}`
  if (!cache.has(key)) cache.set(key, new Formatter(locale, options))
  return cache.get(key)
}

// Использование: numberFormat(locale, { maximumFractionDigits: 0 }).format(value)
export function numberFormat(locale, options = {}) {
  return cached(Intl.NumberFormat, locale, options)
}

export function dateFormat(locale, options = {}) {
  return cached(Intl.DateTimeFormat, locale, options)
}
