<template>
  <section class="cmp-controls" :aria-label="$t('compare.params')">
    <!-- Что сравниваем: вся сеть или региональный менеджер (кнопка в цвете менеджера) -->
    <div class="cmp-controls__row">
      <span class="cmp-controls__label">{{ $t('compare.scope') }}</span>
      <div class="cmp-controls__chips" role="radiogroup" :aria-label="$t('compare.scope')">
        <button
          type="button"
          role="radio"
          class="cmp-chip"
          :class="{ 'cmp-chip--active': !managerId }"
          :aria-checked="!managerId"
          :style="{ '--tone': '#475569' }"
          @click="setManager(null)"
        >
          <v-icon :icon="mdiStorefrontOutline" size="16" />
          {{ $t('compare.network') }}
        </button>
        <button
          v-for="item in managers"
          :key="item.id"
          type="button"
          role="radio"
          class="cmp-chip"
          :class="{ 'cmp-chip--active': managerId === item.id, 'cmp-chip--off': !item.source || item.source.status !== 'ready' }"
          :aria-checked="managerId === item.id"
          :style="{ '--tone': item.color }"
          @click="setManager(item.id)"
        >
          <i class="cmp-chip__dot" aria-hidden="true"></i>
          {{ item.name }}
        </button>
      </div>
    </div>

    <!-- Магазины выбранного менеджера -->
    <div v-if="manager && stores.length" class="cmp-controls__row">
      <span class="cmp-controls__label">{{ $t('compare.stores') }}</span>
      <div class="cmp-controls__chips" role="radiogroup" :aria-label="$t('compare.stores')">
        <button
          type="button"
          role="radio"
          class="cmp-chip cmp-chip--small"
          :class="{ 'cmp-chip--active': !store }"
          :aria-checked="!store"
          :style="{ '--tone': manager.color }"
          @click="setStore(null)"
        >
          {{ $t('compare.allStores') }}
        </button>
        <button
          v-for="name in stores"
          :key="name"
          type="button"
          role="radio"
          class="cmp-chip cmp-chip--small"
          :class="{ 'cmp-chip--active': store === name }"
          :aria-checked="store === name"
          :style="{ '--tone': manager.color }"
          @click="setStore(name)"
        >
          {{ name }}
        </button>
      </div>
    </div>

    <!-- Периоды: выпадающий чек-лист (не больше MAX_PERIODS) -->
    <div class="cmp-controls__row cmp-controls__row--periods">
      <span class="cmp-controls__label">{{ $t('compare.periods') }}</span>
      <v-menu v-model="menu" location="bottom start" :offset="8" :close-on-content-click="false" transition="scale-transition">
        <template #activator="{ props }">
          <button v-bind="props" type="button" class="cmp-select" :class="{ 'cmp-select--open': menu }" :aria-label="$t('compare.periods')">
            <span class="cmp-select__icon" aria-hidden="true">
              <v-icon :icon="mdiCalendarMultiselect" size="18" />
            </span>
            <span v-if="!periods.length" class="cmp-select__placeholder">{{ $t('compare.noPeriods') }}</span>
            <transition-group tag="span" name="cmp-pill" class="cmp-select__pills">
              <span v-for="time in periods" :key="time" class="cmp-select__pill" :class="{ 'cmp-select__pill--partial': !isMonth(time) }">{{ time }}</span>
            </transition-group>
            <span class="cmp-select__count">{{ periods.length }}/{{ max }}</span>
            <v-icon :icon="mdiChevronDown" size="20" class="cmp-select__arrow" />
          </button>
        </template>

        <v-card class="cmp-list" rounded="xl" elevation="8" min-width="290">
          <div class="cmp-list__head">
            <span>{{ $t('compare.periodsHint', { n: max }) }}</span>
            <button type="button" class="cmp-list__preset" :disabled="!lastMonths.length" @click="setPeriods(lastMonths)">
              {{ $t('compare.last3') }}
            </button>
          </div>

          <section v-for="group in groups" :key="group.id" class="cmp-list__group">
            <p class="cmp-list__caption">{{ $t(`compare.${group.id}`) }}</p>
            <ul class="cmp-list__items">
              <li v-for="time in group.times" :key="time">
                <button
                  type="button"
                  class="cmp-list__item"
                  :class="{ 'cmp-list__item--on': periods.includes(time) }"
                  role="checkbox"
                  :aria-checked="periods.includes(time)"
                  :disabled="!periods.includes(time) && periods.length >= max"
                  @click="togglePeriod(time)"
                >
                  <span class="cmp-list__box" aria-hidden="true">
                    <svg viewBox="0 0 16 16"><path d="M3.5 8.5l3 3 6-7" /></svg>
                  </span>
                  {{ time }}
                </button>
              </li>
            </ul>
          </section>
        </v-card>
      </v-menu>
    </div>

    <p v-if="mixed" class="cmp-controls__note">
      <v-icon :icon="mdiAlertOutline" size="18" />
      {{ $t('compare.mixed') }}
    </p>
  </section>
</template>

<script>
import { mapActions, mapState } from 'pinia'
import { mdiAlertOutline, mdiCalendarMultiselect, mdiChevronDown, mdiStorefrontOutline } from '@mdi/js'
import { useCompareStore } from '@/stores/compare'
import { MAX_PERIODS, isMonth } from '@/utils/compare'

// Параметры сравнения: область (сеть, РМ, магазин РМ) и периоды
export default {
  name: 'CompareControls',

  data() {
    return {
      mdiAlertOutline,
      mdiCalendarMultiselect,
      mdiChevronDown,
      mdiStorefrontOutline,
      max: MAX_PERIODS,
      menu: false,
    }
  },

  computed: {
    ...mapState(useCompareStore, ['managers', 'manager', 'managerId', 'store', 'stores', 'times', 'periods', 'mixed', 'lastMonths']),

    // Периоды в списке: сначала полные месяцы, затем нарастающие итоги текущего месяца (свежие сверху)
    groups() {
      const months = this.times.filter(isMonth).reverse()
      const partial = this.times.filter((time) => !isMonth(time)).reverse()
      return [
        { id: 'months', times: months },
        { id: 'partial', times: partial },
      ].filter((group) => group.times.length)
    },
  },

  methods: {
    ...mapActions(useCompareStore, ['setManager', 'setStore', 'togglePeriod', 'setPeriods']),

    isMonth,
  },
}
</script>

