<template>
  <section ref="root" class="bstores" :aria-label="$t('budget.stores.title')" :style="{ '--columns': columns }">
    <!-- Карточки магазинов: шапка с показателями, круг с выносками — куда ушла валовая прибыль.
         Круги нарисованы сразу, без анимации появления: при прокрутке карточки не дорисовываются -->
    <budget-pie
      v-for="card in cards"
      :key="card.store"
      class="bstores__card"
      v-bind="pieOf(card)"
      :limit-height="false"
      :animate="false"
      clickable
      @open="open(card)"
    >
      <template #head>
        <store-head :card="card" :rank="card.rank" />
      </template>
    </budget-pie>

    <!-- Окно магазина: та же карточка крупно — тот же круг того же общего размера, поэтому окна всех магазинов
         одинаковые -->
    <budget-pie-dialog v-model="dialog" :pie="active && pieOf(active)">
      <template #head>
        <store-head v-if="active" :card="active" />
      </template>
    </budget-pie-dialog>
  </section>
</template>

<script>
import { h } from 'vue'
import { mapState } from 'pinia'
import BudgetPie, { COMPACT_SHAPE, pieFormat, shapeProps } from '@/components/BudgetPie.vue'
import BudgetPieDialog from '@/components/BudgetPieDialog.vue'
import numberFormatMixin from '@/mixins/numberFormat'
import { useBudgetStore } from '@/stores/budget'
import { useScopeStore } from '@/stores/scope'
import { calloutLayout } from '@/utils/calloutPie'
import { EXPENSE_COLORS, EXPENSE_FIELDS, SPECIAL, n, rowExpenses, rowMargin, rowOpProfit } from '@/utils/budget'

// Сегмент «Прибуток від діяльності» — что осталось от валовой прибыли после расходов
const OP_PROFIT_COLOR = '#0c831e'

// Шапка карточки по маржинальности (как на прежней странице): от 25 % зелёная, от 15 % оранжевая, ниже — красная
function toneOf(margin) {
  if (margin >= 0.25) return { from: '#22c55e', to: '#059669' }
  if (margin >= 0.15) return { from: '#f59e0b', to: '#d97706' }
  return { from: '#ef4444', to: '#b91c1c' }
}

// Колонок карточек по ширине блока (px): от 1400 — три, от 820 — две, уже — одна
const COLUMNS = [
  { from: 1400, columns: 3 },
  { from: 820, columns: 2 },
]

// Шапка карточки: место, название и четыре показателя
const StoreHead = {
  name: 'StoreHead',

  mixins: [numberFormatMixin],

  props: {
    card: { type: Object, required: true },
    rank: { type: Number, default: 0 },
  },

  render() {
    const card = this.card
    const metric = (label, value, loss = false) =>
      h('div', { class: 'bstore-head__metric' }, [
        h('span', { class: 'bstore-head__label' }, this.$t(label)),
        h('b', { class: ['bstore-head__value', { 'bstore-head__value--loss': loss }] }, value),
      ])
    return h('div', { class: 'bstore-head' }, [
      h('div', { class: 'bstore-head__top' }, [
        this.rank ? h('span', { class: 'bstore-head__rank' }, `#${this.rank}`) : null,
        h('h3', { class: 'bstore-head__name', title: card.store }, card.store),
      ]),
      h('div', { class: 'bstore-head__metrics' }, [
        metric('budget.stores.profit', this.compact(card.profit)),
        metric('budget.stores.expenses', this.compact(card.expenses)),
        metric('budget.stores.opProfit', this.compact(card.op), card.op < 0),
        metric('budget.stores.margin', this.percent(card.margin * 100)),
      ]),
    ])
  },
}

// Структура витрат по магазинах (budget-page-map.md, блок 12): все магазины (с Інтернет-магазином и Сервісом),
// от большего прибутку від діяльності к меньшему. Круг — все статьи расходов магазина и, если он в плюсе,
// прибуток від діяльності: куда ушла валовая прибыль. Убыток сектором не показать — он виден в шапке.
// Нажатие на карточку открывает её крупно
export default {
  name: 'BudgetStoreCards',

  components: { BudgetPie, BudgetPieDialog, StoreHead },

  mixins: [numberFormatMixin],

  data() {
    return {
      dialog: false,
      active: null,
      // Ширина блока: от неё зависит число колонок
      width: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    cards() {
      return useBudgetStore()
        .rowsOf(this.period)
        .filter((row) => !SPECIAL.has(row.store))
        .map((row) => {
          const op = rowOpProfit(row)
          const items = EXPENSE_FIELDS.map((field) => ({
            id: field,
            label: this.$t(`budget.fields.${field}`),
            value: n(row[field]),
            color: EXPENSE_COLORS[field],
          }))
          if (op > 0) items.push({ id: 'op', label: this.$t('budget.stores.opProfit'), value: op, color: OP_PROFIT_COLOR })
          const margin = rowMargin(row)
          return {
            store: row.store,
            profit: n(row.profit),
            expenses: rowExpenses(row),
            op,
            margin,
            tone: toneOf(margin),
            items: items.filter((item) => item.value > 0).sort((a, b) => b.value - a.value),
          }
        })
        .sort((a, b) => b.op - a.op)
        .map((card, index) => ({ ...card, rank: index + 1 }))
    },

    // Раскладка круга каждой карточки: считается один раз и нужна и для общего размера, и самой карточке
    layouts() {
      const format = pieFormat(this)
      return Object.fromEntries(this.cards.map((card) => [card.store, calloutLayout(card.items, { ...COMPACT_SHAPE, format })]))
    },

    // Общие ширина и высота: круг и текст во всех карточках и окнах одного размера (как на прежней странице)
    shared() {
      const layouts = this.cards.filter((card) => card.items.length).map((card) => this.layouts[card.store])
      return { halfWidth: Math.max(0, ...layouts.map((item) => item.halfWidth)), halfHeight: Math.max(0, ...layouts.map((item) => item.halfHeight)) }
    },

    columns() {
      const rule = COLUMNS.find((item) => this.width >= item.from)
      return rule ? rule.columns : 1
    },
  },

  watch: {
    // Другой месяц: открытое окно показывает уже другие данные — закрываем
    period() {
      this.dialog = false
    },
  },

  mounted() {
    if ('ResizeObserver' in window) {
      this.observer = new ResizeObserver(([entry]) => (this.width = Math.floor(entry.contentRect.width)))
      this.observer.observe(this.$refs.root)
    }
    // Первый размер — сразу: в фоновой вкладке ResizeObserver срабатывает, только когда вкладку откроют
    this.width = Math.floor(this.$refs.root.getBoundingClientRect().width)
  },

  beforeUnmount() {
    if (this.observer) this.observer.disconnect()
  },

  methods: {
    // Props круга карточки (и её окна): компактный круг общего для всех карточек размера
    pieOf(card) {
      return {
        title: card.store,
        from: card.tone.from,
        to: card.tone.to,
        items: card.items,
        prepared: this.layouts[card.store],
        totalLabel: this.$t(card.op > 0 ? 'budget.stores.profit' : 'budget.stores.expenses'),
        halfWidth: this.shared.halfWidth,
        halfHeight: this.shared.halfHeight,
        ...shapeProps(COMPACT_SHAPE),
      }
    },

    open(card) {
      this.active = card
      this.dialog = true
    },
  },
}
</script>

<style lang="scss" scoped>
