<template>
  <v-navigation-drawer
    :model-value="desktop || modelValue"
    :permanent="desktop"
    :temporary="!desktop"
    :width="isRail ? 84 : 272"
    :scrim="!desktop"
    class="sidebar"
    :class="{ 'sidebar--rail': isRail, 'sidebar--light': !isDark }"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <div class="sidebar__glow" aria-hidden="true"></div>

    <div class="sidebar__inner">
      <router-link :to="{ name: 'home' }" class="sidebar__brand" :aria-label="appName">
        <img :src="logo" :alt="appName" class="sidebar__logo" width="44" height="44" />
        <span class="sidebar__name">{{ appName }}</span>
      </router-link>

      <nav class="sidebar__nav" :aria-label="$t('common.mainNav')">
        <p class="sidebar__caption">{{ $t('common.menu') }}</p>

        <!-- Региональный менеджер видит одну кнопку: обновить данные своей страницы -->
        <button
          v-if="ownManager"
          type="button"
          class="sidebar__link sidebar__link--button"
          :disabled="refreshing"
          :style="{ '--i': 0 }"
          @click="onRefresh"
        >
          <v-progress-circular v-if="refreshing" indeterminate size="22" width="2.5" class="sidebar__icon" />
          <v-icon v-else :icon="mdiRefresh" size="22" class="sidebar__icon" />
          <span class="sidebar__label">{{ $t('common.refresh') }}</span>
          <v-tooltip v-if="isRail" activator="parent" location="end" :text="$t('common.refresh')" />
        </button>

        <template v-else>
          <router-link
            v-for="(item, index) in mainItems"
            :key="item.route"
            :to="{ name: item.route }"
class="sidebar__link sidebar__link--card"
            exact-active-class="sidebar__link--active"
            :style="{ '--i': index }"
            @click="onNavigate"
          >
            <span class="sidebar__tile" aria-hidden="true">
              <v-icon :icon="item.icon" size="20" />
            </span>
            <span class="sidebar__label">{{ $t(item.title) }}</span>
            <v-tooltip v-if="isRail" activator="parent" location="end" :text="$t(item.title)" />
          </router-link>

          <!-- Менеджеры: одна кнопка, список раскрывается под ней. Сколько РМ, столько и пунктов -->
          <template v-if="managers.length">
            <div v-if="!isRail" class="sidebar__group">
              <button
                type="button"
                class="sidebar__link sidebar__link--button sidebar__link--group"
                :class="{ 'sidebar__link--open': managersOpen, 'sidebar__link--child': onManagerPage }"
                :aria-expanded="managersOpen"
                aria-controls="sidebar-managers"
                :style="{ '--i': mainItems.length }"
                @click="managersOpen = !managersOpen"
              >
                <span class="sidebar__tile" aria-hidden="true">
                  <v-icon :icon="mdiAccountGroupOutline" size="20" />
                </span>
                <span class="sidebar__label">{{ $t('nav.managers') }}</span>
                <span class="sidebar__count" aria-hidden="true">{{ managers.length }}</span>
                <v-icon :icon="mdiChevronDown" size="20" class="sidebar__chevron" />
              </button>

              <div id="sidebar-managers" class="sidebar__sub" :class="{ 'sidebar__sub--open': managersOpen }" :aria-hidden="!managersOpen">
                <div class="sidebar__sub-inner">
                  <router-link
                    v-for="manager in managers"
                    :key="manager.id"
                    :to="{ name: 'manager', params: { id: manager.id } }"
                    class="sidebar__link sidebar__link--manager"
                    exact-active-class="sidebar__link--active"
                    :style="{ '--mc': manager.color }"
                    :tabindex="managersOpen ? 0 : -1"
                    @click="onNavigate"
                  >
                    <span class="sidebar__badge" aria-hidden="true">{{ initial(manager.name) }}</span>
                    <span class="sidebar__label">{{ manager.name }}</span>
                  </router-link>
                </div>
              </div>
            </div>

            <!-- В узком сайдбаре раскрывать некуда: список открывается меню сбоку -->
            <v-menu v-else location="end" :offset="12" transition="scale-transition">
              <template #activator="{ props }">
                <button
                  v-bind="props"
                  type="button"
                  class="sidebar__link sidebar__link--button sidebar__link--group"
                  :class="{ 'sidebar__link--child': onManagerPage }"
                  :aria-label="$t('nav.managers')"
                >
                  <v-icon :icon="mdiAccountGroupOutline" size="22" class="sidebar__icon" />
                  <v-tooltip activator="parent" location="end" :text="$t('nav.managers')" />
                </button>
              </template>

              <v-card class="sidebar__menu" rounded="xl" elevation="8" min-width="220">
                <p class="sidebar__menu-title">{{ $t('nav.managers') }}</p>
                <router-link
                  v-for="manager in managers"
                  :key="manager.id"
                  :to="{ name: 'manager', params: { id: manager.id } }"
                  class="sidebar__menu-link"
                  exact-active-class="sidebar__menu-link--active"
                  :style="{ '--mc': manager.color }"
                >
                  <span class="sidebar__badge" aria-hidden="true">{{ initial(manager.name) }}</span>
                  {{ manager.name }}
                </router-link>
              </v-card>
            </v-menu>
          </template>

          <!-- Разделы после менеджеров: «Порівняння», «Бюджет», «Підсумки» -->
          <router-link
            v-for="(item, index) in laterItems"
            :key="item.route"
            :to="{ name: item.route }"
class="sidebar__link sidebar__link--card"
            exact-active-class="sidebar__link--active"
            :style="{ '--i': mainItems.length + 1 + index }"
            @click="onNavigate"
          >
            <span class="sidebar__tile" aria-hidden="true">
              <v-icon :icon="item.icon" size="20" />
            </span>
            <span class="sidebar__label">{{ $t(item.title) }}</span>
            <v-tooltip v-if="isRail" activator="parent" location="end" :text="$t(item.title)" />
          </router-link>
        </template>
      </nav>

      <!-- Язык интерфейса — над карточкой пользователя -->
      <div class="sidebar__lang">
        <language-switcher :rail="isRail" />
      </div>

      <div class="sidebar__user">
        <span class="sidebar__avatar" aria-hidden="true">
          <span class="sidebar__avatar-face">
            <v-icon :icon="mdiAccount" size="22" />
          </span>
        </span>
        <span class="sidebar__login">{{ currentUser ? currentUser.login : $t('common.guest') }}</span>
        <v-btn
          :aria-label="$t('common.logout')"
          class="sidebar__logout"
          variant="text"
          size="small"
          @click="confirmOpen = true"
        >
          <v-icon :icon="mdiLogout" />
          <v-tooltip activator="parent" location="top" :text="$t('common.logout')" />
        </v-btn>
      </div>
