import { defineStore } from 'pinia'
import { fetchBudget } from '@/services/budget'
import { createRetry } from '@/utils/retry'

const retry = createRetry()

// Данные страницы «Бюджет». Загружаются при первом открытии страницы и дальше живут до перезагрузки сайта
export const useBudgetStore = defineStore('budget', {
  state: () => ({
    // Строки всех месяцев или null, пока не загрузились
    rows: null,
    loading: false,
    // Данных ещё нет, а последняя попытка загрузки не удалась
    failed: false,
  }),

  getters: {
    loaded: (state) => state.rows !== null,

    // Строки по месяцам: { 'Липень 26': [...] } — группируются один раз, а блоков страницы, которым нужен месяц, много
    byTime: (state) => {
      const groups = {}
      for (const row of state.rows || []) {
        if (!groups[row.time]) groups[row.time] = []
        groups[row.time].push(row)
      }
      return groups
    },

    // Месяцы в порядке таблицы, в той же форме, что строки компании: { time }
    periods() {
      return Object.keys(this.byTime).map((time) => ({ time }))
    },
  },

  actions: {
    // Пока данных нет, после ошибки запрос сразу повторяется (NETWORK.RETRY_MS)
    // Ответ запроса, начатого до отмены (выход, уход со страницы), отбрасывается
    async load() {
      if (this.loading || this.loaded) return
      retry.clear()
      const token = retry.token()
      this.loading = true
      try {
        const rows = await fetchBudget()
        if (token !== retry.token()) return
        this.rows = rows
        this.failed = false
      } catch {
        if (token !== retry.token()) return
        this.failed = true
        retry.schedule(token, () => this.load())
      } finally {
        if (token === retry.token()) this.loading = false
      }
    },

    // Строки месяца time
    rowsOf(time) {
      return this.byTime[time] || []
    },

    // Останавливает загрузку и повторы; следующий заход на страницу запросит данные заново
    cancelRetry() {
      retry.cancel()
      this.loading = false
    },

    // Выход из аккаунта: данные прежнего входа не должны достаться следующему
    reset() {
      this.cancelRetry()
      this.rows = null
      this.failed = false
    },
  },
})
