<template>
  <!-- clickable: карточку можно открыть крупно (мышью или Enter / пробелом) — событие open -->
  <article
    class="bpie"
    :class="{ 'bpie--clickable': clickable }"
    :style="{ '--from': from, '--to': to }"
    :role="clickable ? 'button' : null"
    :tabindex="clickable ? 0 : null"
    :aria-label="clickable ? `${title}: ${$t('budget.open')}` : null"
    @click="clickable && $emit('open')"
    @keydown.enter.prevent="clickable && $emit('open')"
    @keydown.space.prevent="clickable && $emit('open')"
  >
    <!-- Шапка залита градиентом своего цвета (цвета прежней страницы). Своё содержимое шапки — через слот head -->
    <header class="bpie__head">
      <slot name="head">
        <span class="bpie__icon" aria-hidden="true">
          <v-icon :icon="icon" size="22" />
        </span>
        <div class="bpie__heading">
          <h3 class="bpie__title">{{ title }}</h3>
          <span class="bpie__total">{{ $t('budget.pies.total') }}: {{ millions(total) }}</span>
        </div>
      </slot>
    </header>

    <div ref="body" class="bpie__body">
      <p v-if="!items.length" class="bpie__empty">{{ $t('budget.pies.empty') }}</p>

      <!-- Широкая карточка: круг с выносками, как на прежней странице -->
      <svg
        v-else-if="!narrow"
        class="bpie__callout"
        :class="{ 'bpie__callout--free': !limitHeight }"
        :viewBox="`0 0 ${width * 2} ${height * 2}`"
        role="img"
        :aria-label="title"
      >
        <g :transform="`translate(${width}, ${height})`">
          <path
            v-for="segment in segments"
            :key="segment.id"
            :d="segment.path"
            :fill="segment.color"
            class="bpie__slice"
            :class="{ 'bpie__slice--dim': hovered && hovered !== segment.id }"
            :style="{ transform: hovered === segment.id ? segment.pop : null }"
            @pointerenter="hovered = segment.id"
            @pointerleave="hovered = null"
          >
            <title>{{ tooltip(segment) }}</title>
          </path>

          <g
            v-for="label in layout.labels"
            :key="`label-${label.id}`"
            class="bpie__label"
            :class="{ 'bpie__label--dim': hovered && hovered !== label.id, 'bpie__label--active': hovered === label.id }"
            @pointerenter="hovered = label.id"
            @pointerleave="hovered = null"
          >
            <polyline :points="label.points" class="bpie__leader" />
            <circle :cx="label.edgeX" :cy="label.edgeY" r="5" :fill="label.color" class="bpie__dot" />
            <text
              v-for="(line, index) in label.texts"
              :key="index"
              :x="label.textX"
              :y="line.y"
              :text-anchor="label.anchor"
              :class="`bpie__text-${line.role}`"
              :fill="line.role === 'name' ? label.color : null"
            >
              {{ line.text }}
              <tspan v-if="line.extra" class="bpie__text-share">· {{ line.extra }}</tspan>
            </text>
          </g>
        </g>
      </svg>

      <!-- Узкая карточка (телефон): кольцо и список, подписи вокруг круга были бы нечитаемо мелкими -->
      <div v-else class="bpie__compact">
        <div class="bpie__donut">
          <svg viewBox="-110 -110 220 220" role="img" :aria-label="title">
            <path
              v-for="segment in donut"
              :key="segment.id"
              :d="segment.path"
              :fill="segment.color"
              class="bpie__ring"
              :class="{ 'bpie__ring--active': hovered === segment.id, 'bpie__ring--dim': hovered && hovered !== segment.id }"
              @pointerenter="hovered = segment.id"
              @pointerleave="hovered = null"
            >
              <title>{{ tooltip(segment) }}</title>
            </path>
          </svg>
          <div class="bpie__center">
            <template v-if="active">
              <b>{{ percent(active.share * 100) }}</b>
              <span>{{ active.label }}</span>
            </template>
            <template v-else>
              <b>{{ millions(total) }}</b>
              <span>{{ totalLabel || $t('budget.pies.total') }}</span>
            </template>
          </div>
        </div>

        <ol class="bpie__list">
          <li
            v-for="item in shares"
            :key="item.id"
            class="bpie__row"
            :class="{ 'bpie__row--active': hovered === item.id }"
            @pointerenter="hovered = item.id"
            @pointerleave="hovered = null"
          >
            <span class="bpie__name" :title="item.label">
              <i :style="{ background: item.color }" aria-hidden="true"></i>
              {{ item.label }}
            </span>
            <span class="bpie__num">{{ money(item.value) }}</span>
            <b class="bpie__num bpie__num--share">{{ percent(item.share * 100) }}</b>
          </li>
        </ol>
      </div>
    </div>
  </article>
</template>

<script>
import numberFormatMixin from '@/mixins/numberFormat'
import { CALLOUT_R, calloutLayout, ringPath } from '@/utils/calloutPie'
import { animateProgress } from '@/utils/tween'

// Насколько выдвигается сектор под курсором
const POP = 16
// Уже этой ширины области диаграммы (телефон) подписи вокруг круга нечитаемо мелкие — вместо круга с выносками
// кольцо и список. В ряду из трёх карточек область около 480 px — там ещё круг с выносками
const COMPACT_BELOW = 420
// Кольцо узкой карточки: внешний и внутренний радиус
const OUTER = 100
const INNER = 64

// Круговая диаграмма расходов с выносками (как «Офіс Київ» прежней страницы).
// items — [{ id, label, value, color }] по убыванию. halfWidth — общая половина ширины для нескольких диаграмм рядом:
// так круги и текст у них одного размера
export default {
  name: 'BudgetPie',

  mixins: [numberFormatMixin],

  props: {
    title: {
      type: String,
      required: true,
    },
    // Значок шапки по умолчанию (не нужен, если шапка своя — слот head)
    icon: {
      type: String,
      default: '',
    },
    // Цвета градиента шапки
    from: {
      type: String,
      required: true,
    },
    to: {
      type: String,
      required: true,
    },
    items: {
      type: Array,
      required: true,
    },
    halfWidth: {
      type: Number,
      default: 0,
    },
    // Общая половина высоты: у нескольких диаграмм одного размера (карточки, окно магазина) высота тоже одна
    halfHeight: {
      type: Number,
      default: 0,
    },
    // Подпись суммы всех секторов в центре кольца (по умолчанию «Витрати»)
    totalLabel: {
      type: String,
      default: '',
    },
    // Радиус круга в единицах viewBox (текст подписей — 26): чем меньше круг, тем крупнее текст при той же ширине
    radius: {
      type: Number,
      default: CALLOUT_R,
    },
    // Где начинается первый сектор (радианы от «3 часов» по часовой); по умолчанию — сверху
    startAngle: {
      type: Number,
      default: -Math.PI / 2,
    },
    // Компактные подписи: сумма и процент в одной строке, промежутки между подписями меньше (см. calloutLayout)
    inline: {
      type: Boolean,
      default: false,
    },
    rowGap: {
      type: Number,
      default: undefined,
    },
    // Готовая раскладка (calloutLayout) с теми же параметрами, если родитель уже посчитал её для общего размера
    prepared: {
      type: Object,
      default: null,
    },
    // Карточку можно нажать, чтобы открыть крупно (событие open)
    clickable: {
      type: Boolean,
      default: false,
    },
    // Ограничить высоту диаграммы (на всю ширину страницы круг иначе огромный)
    limitHeight: {
      type: Boolean,
      default: true,
    },
    // Анимация появления, когда диаграмма доходит до экрана. false — диаграмма сразу нарисована целиком
    // (диаграммы страницы «Бюджет» не должны дорисовываться при прокрутке; анимация осталась в окне диаграммы)
    animate: {
      type: Boolean,
      default: true,
    },
  },

  emits: ['open'],

  data() {
    return {
      // Статья под курсором: подсвечивается в круге, в подписях и в списке
      hovered: null,
      progress: this.animate ? 0 : 1,
      // Диаграмма уже показывалась на экране: анимация появления проигрывается, только когда её видно
      // (карточек магазинов десятки — иначе все анимировались бы разом, в том числе за пределами экрана)
      seen: false,
      // Ширина области диаграммы: от неё зависит вид (круг с выносками или кольцо со списком)
      bodyWidth: 0,
    }
  },

  computed: {
    total() {
      return this.items.reduce((sum, item) => sum + item.value, 0)
    },

    layout() {
      if (this.prepared) return this.prepared
      return calloutLayout(this.items, { r: this.radius, startAngle: this.startAngle, inline: this.inline, rowGap: this.rowGap, format: pieFormat(this) })
    },

    // Половина ширины viewBox: общая для диаграмм рядом, но не меньше своей
    width() {
      return Math.max(this.halfWidth, this.layout.halfWidth)
    },

    // Половина высоты viewBox: общая, но не меньше своей
    height() {
      return Math.max(this.halfHeight, this.layout.halfHeight)
    },

    narrow() {
      return this.bodyWidth > 0 && this.bodyWidth < COMPACT_BELOW
    },

    // Секторы растут по кругу при появлении; сектор под курсором выдвигается наружу
    segments() {
      const list = this.layout.segments
      const start = list.length ? list[0].start : 0
      const turn = (angle) => start + (angle - start) * this.progress
      return list.map((segment) => ({
        ...segment,
        // Не больше полного круга без капли: дуга ровно в 360° рисуется как точка (одна статья на весь круг)
        path: ringPath(turn(segment.start), Math.min(Math.max(turn(segment.end), turn(segment.start) + 0.002), segment.start + Math.PI * 2 - 0.0001), this.radius),
        pop: `translate(${(Math.cos(segment.midA) * POP).toFixed(1)}px, ${(Math.sin(segment.midA) * POP).toFixed(1)}px)`,
      }))
    },

    shares() {
      return this.items.map((item) => ({ ...item, share: this.total ? item.value / this.total : 0 }))
    },

    donut() {
      const start = -Math.PI / 2
      let angle = start
      return this.shares.map((item) => {
        const from = angle
        angle += item.share * Math.PI * 2 * this.progress
        const to = Math.min(Math.max(angle, from + 0.004), start + Math.PI * 2 - 0.0001)
        return { ...item, path: ringPath(from, to, OUTER, INNER) }
      })
    },

    active() {
      return this.shares.find((item) => item.id === this.hovered) || null
    },

    // Меняется, когда пришли другие значения: тогда анимация проигрывается заново
    signature() {
      return this.items.map((item) => `${item.id}:${item.value}`).join('|')
    },
  },

  watch: {
    // Другие значения (месяц): анимация проигрывается заново, если диаграмму уже видно
    signature() {
      if (this.animate && this.seen) this.play()
    },
  },

  mounted() {
    if (!this.animate) {
      this.seen = true
    } else if ('IntersectionObserver' in window) {
      this.visibility = new IntersectionObserver(
        ([entry]) => {
          if (!entry.isIntersecting) return
          this.visibility.disconnect()
          this.seen = true
          this.play()
        },
        { rootMargin: '120px' },
      )
      this.visibility.observe(this.$el)
    } else {
      this.seen = true
      this.play()
    }

    if ('ResizeObserver' in window) {
      this.observer = new ResizeObserver(([entry]) => (this.bodyWidth = Math.floor(entry.contentRect.width)))
      this.observer.observe(this.$refs.body)
    }
    // Первый размер — сразу: в фоновой вкладке ResizeObserver срабатывает, только когда вкладку откроют
    this.bodyWidth = Math.floor(this.$refs.body.getBoundingClientRect().width)
  },

  beforeUnmount() {
    if (this.stopTween) this.stopTween()
    if (this.observer) this.observer.disconnect()
    if (this.visibility) this.visibility.disconnect()
  },

  methods: {
    play() {
      if (this.stopTween) this.stopTween()
      this.stopTween = animateProgress((progress) => (this.progress = progress), { delay: 150 })
    },

    tooltip(item) {
      return `${item.label}: ${this.money(item.value)} ${this.$t('kpi.uah')} (${this.percent(item.share * 100)})`
    },
  },
}

// Компактный круг (карточки в ряд, окна): меньше круг, первый сектор справа («3 часа») — мелкие статьи сбоку столбиком,
// подписи в строку «сумма · процент». Параметры calloutLayout; для props BudgetPie — shapeProps()
export const COMPACT_SHAPE = { r: 250, startAngle: 0, inline: true, rowGap: 16 }

// Параметры круга (как у calloutLayout) в виде props BudgetPie
export function shapeProps(shape) {
  return { radius: shape.r, startAngle: shape.startAngle, inline: shape.inline, rowGap: shape.rowGap }
}

// Тексты подписей выносок: сумма целиком и доля. Нужны и снаружи, чтобы посчитать общую ширину нескольких диаграмм
export function pieFormat(vm) {
  return { value: (value) => vm.money(value), share: (share) => vm.percent(share * 100) }
}
</script>

