<template>
  <div class="boot" :class="{ 'boot--dark': isDark }" role="status" aria-live="polite">
    <div class="boot__field" aria-hidden="true">
      <span class="boot__pill boot__pill--a"></span>
      <span class="boot__pill boot__pill--b"></span>
      <span class="boot__pill boot__pill--c"></span>
    </div>

    <div class="boot__hero">
      <div class="boot__mark">
        <svg viewBox="0 0 100 100" class="boot__ring" aria-hidden="true">
          <circle class="boot__track" cx="50" cy="50" r="46" />
          <circle class="boot__arc" cx="50" cy="50" r="46" />
        </svg>
        <img :src="logo" :alt="appName" class="boot__logo" width="72" height="72" />
      </div>

      <h2 class="boot__title">{{ $t('boot.title') }}</h2>

      <!-- Пока проверка идёт, точки бегут; при медленной сети появляется пояснение -->
      <div class="boot__dots" aria-hidden="true"><i></i><i></i><i></i></div>

      <transition name="boot-slow">
        <p v-if="slow" class="boot__slow">{{ $t('boot.slow') }}</p>
      </transition>
    </div>
  </div>
</template>

<script>
import { mapState } from 'pinia'
import logo from '@/assets/logo.png'
import { APP } from '@/configurations'
import { useSettingsStore } from '@/stores/settings'

// Через сколько секунд показать, что связь медленная
const SLOW_AFTER_MS = 6000

// Экран проверки входа: показывается, пока после обновления страницы сверяется сохранённый вход с таблицей доступов.
// Внешне продолжает заставку из index.html и переходит в общий экран загрузки данных.
export default {
  name: 'BootScreen',

  data() {
    return {
      logo,
      appName: APP.NAME,
      slow: false,
    }
  },

  computed: {
    ...mapState(useSettingsStore, ['isDark']),
  },

  mounted() {
    this.slowTimer = setTimeout(() => (this.slow = true), SLOW_AFTER_MS)
  },

  beforeUnmount() {
    clearTimeout(this.slowTimer)
  },
}
</script>

