import { BUDGET } from '@/configurations'
import { normalizeRows } from '@/services/company'
import { gasGet } from '@/services/gas'

// Текстовые столбцы; остальные значения — числа или null (пустая ячейка приходит строкой "")
const TEXT_COLUMNS = ['time', 'store']

// Строки бюджета всех месяцев в порядке таблицы: [{ time, store, revenue, profit, rent, … }]
export async function fetchBudget() {
  const data = await gasGet(BUDGET.URL)
  if (!data || !Array.isArray(data.budget_info)) throw new Error('Budget: неожиданный ответ')
  return normalizeRows(data.budget_info, TEXT_COLUMNS)
}
