import { defineStore } from 'pinia'
import { fetchCompany } from '@/services/company'
import { createRetry } from '@/utils/retry'

const retry = createRetry()

export const useCompanyStore = defineStore('company', {
  state: () => ({
    rows: [],
    loading: false,
    // Данных ещё нет, а последняя попытка загрузки не удалась
    failed: false,
  }),

  getters: {
    loaded: (state) => state.rows.length > 0,

    // Самый свежий период: последняя строка таблицы
    latest: (state) => (state.rows.length ? state.rows[state.rows.length - 1] : null),
  },

  actions: {
    // Пока данных нет, после ошибки запрос сразу повторяется (NETWORK.RETRY_MS), а интерфейс показывает индикатор загрузки
    // Ответ запроса, начатого до отмены (выход из аккаунта), отбрасывается
    async load() {
      if (this.loading) return
      retry.clear()
      const token = retry.token()
      this.loading = true
      try {
        const rows = await fetchCompany()
        if (token !== retry.token()) return
        this.rows = rows
        this.failed = false
      } catch {
        if (token !== retry.token()) return
        if (!this.loaded) {
          this.failed = true
          retry.schedule(token, () => this.load())
        }
      } finally {
        if (token === retry.token()) this.loading = false
      }
    },

    // Останавливает загрузку и повторы: следующий load() начнёт заново, не дожидаясь прежнего запроса
    cancelRetry() {
      retry.cancel()
      this.loading = false
    },

    // Выход из аккаунта: данные прежнего входа не должны достаться следующему
    reset() {
      this.cancelRetry()
      this.rows = []
      this.failed = false
    },
  },
})
