<template>
  <article class="bbars">
    <!-- Сводка: слева и справа — показатели (цветная точка — цвет столбиков, это же легенда), справа — сортировка -->
    <div v-if="statsStart.length || statsEnd.length || sortOptions.length" class="bbars__bar">
      <ul class="bbars__stats">
        <li v-for="stat in statsStart" :key="stat.id" class="bbars__stat" :style="{ '--dot': stat.color }">
          <i v-if="stat.color" aria-hidden="true"></i>
          <span>{{ stat.label }}</span>
          <b :class="{ 'bbars__loss': stat.loss }">{{ stat.value }}</b>
        </li>
      </ul>

      <ul v-if="statsEnd.length" class="bbars__stats">
        <li v-for="stat in statsEnd" :key="stat.id" class="bbars__stat" :style="{ '--dot': stat.color }">
          <i v-if="stat.color" aria-hidden="true"></i>
          <span>{{ stat.label }}</span>
          <b :class="{ 'bbars__loss': stat.loss }">{{ stat.value }}</b>
        </li>
      </ul>

      <div v-if="sortOptions.length" class="bbars__sort" role="group" :aria-label="$t('budget.sort')">
        <span class="bbars__sort-label">{{ $t('budget.sort') }}</span>
        <button
          v-for="option in sortOptions"
          :key="option.id"
          type="button"
          class="bbars__sort-btn"
          :class="{ 'bbars__sort-btn--active': sortBy === option.id }"
          :style="{ '--dot': option.color }"
          :aria-pressed="sortBy === option.id"
          @click="$emit('update:sortBy', option.id)"
        >
          {{ option.label }}
        </button>
      </div>
    </div>

    <div class="bbars__chart" :style="chartStyle">
      <canvas ref="canvas" role="img" :aria-label="label"></canvas>
    </div>
  </article>
</template>

<script>
import { markRaw } from 'vue'
import { mapState } from 'pinia'
import Chart from '@/plugins/chart'
import numberFormatMixin from '@/mixins/numberFormat'
import { useSettingsStore } from '@/stores/settings'

// Уже этой ширины окна график поворачивается: магазины сверху вниз, столбики горизонтальные (как на прежней странице)
const NARROW_MAX = 1000
// Сколько места (px) нужно подписи значения: столбик убытка длиннее — подпись внутри него
const LABEL_ROOM = 64

// Столбики по магазинам для страницы «Бюджет» (маржинальность, рентабельность, доля ЗП, прибыль).
// rows — [{ label, values: [число | null по порядку series], extra: [строки подсказки] }] в нужном порядке.
// series — [{ id, label, color: цвет или (значение) => цвет }]. format — 'percent' (значения в долях) или 'money'.
// Над графиком — сводка (statsStart слева, statsEnd справа: [{ id, label, value, color?, loss? }])
// и сортировка (sortOptions: [{ id, label, color }], v-model:sortBy)
export default {
  name: 'BudgetBars',

  mixins: [numberFormatMixin],

  props: {
    label: {
      type: String,
      required: true,
    },
    rows: {
      type: Array,
      required: true,
    },
    series: {
      type: Array,
      required: true,
    },
    format: {
      type: String,
      default: 'percent',
      validator: (value) => ['percent', 'money'].includes(value),
    },
    statsStart: {
      type: Array,
      default: () => [],
    },
    statsEnd: {
      type: Array,
      default: () => [],
    },
    sortOptions: {
      type: Array,
      default: () => [],
    },
    sortBy: {
      type: String,
      default: '',
    },
  },

  emits: ['update:sortBy'],

  computed: {
    ...mapState(useSettingsStore, ['isDark']),

    narrow() {
      return this.$vuetify.display.width <= NARROW_MAX
    },

    // Повёрнутый график: высота по числу магазинов (у двух показателей строка выше)
    chartStyle() {
      if (!this.narrow) return null
      const row = this.series.length > 1 ? 36 : 26
      return { height: `${Math.max(500, this.rows.length * row)}px` }
    },

    // Меняется, когда нужно перерисовать график: другие данные, ориентация, тема или язык
    view() {
      const data = this.rows.map((row) => `${row.label}:${row.values.join(',')}`).join('|')
      return `${data}|${this.narrow}|${this.isDark}|${this.$i18n.locale}`
    },
  },

  watch: {
    view() {
      this.$nextTick(this.draw)
    },
  },

  mounted() {
    this.draw()
  },

  beforeUnmount() {
    this.destroy()
  },

  methods: {
    destroy() {
      // Экземпляр графика хранится вне data(), чтобы Vue не делал его реактивным
      if (this.chart) this.chart.destroy()
      this.chart = null
    },

    value(value) {
      return this.format === 'percent' ? this.percent(value * 100) : this.money(value)
    },

    tick(value) {
      if (this.format === 'percent') return this.percent(value * 100)
      return value === 0 ? '0' : this.compact(value)
    },

    draw() {
      this.destroy()
      const canvas = this.$refs.canvas
      if (!canvas || !this.rows.length) return

      const narrow = this.narrow
      const pair = this.series.length > 1
      const text = this.isDark ? 'rgba(255, 255, 255, 0.7)' : 'rgba(0, 0, 0, 0.6)'
      const strong = this.isDark ? 'rgba(255, 255, 255, 0.92)' : 'rgba(0, 0, 0, 0.85)'
      const grid = this.isDark ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.06)'
      const zero = this.isDark ? 'rgba(255, 255, 255, 0.3)' : 'rgba(0, 0, 0, 0.25)'
      const surface = this.isDark ? '#20201e' : '#ffffff'
      const rows = this.rows
      const value = (number) => this.value(number)
      const storeAxis = narrow ? 'y' : 'x'
      const valueAxis = narrow ? 'x' : 'y'
      const lowest = Math.min(0, ...rows.flatMap((row) => row.values.map((number) => number ?? 0)))
      const negative = (context) => context.dataset.data[context.dataIndex] < 0
      // Длинный столбик убытка: подпись внутри него (белым), короткий — за его концом. На повёрнутом графике (телефон)
      // подпись убытка стоит справа от нуля, в той же строке: там пусто
      const inside = (context) => {
        if (narrow || !negative(context)) return false
        // Длина — по шкале, а не по нарисованному столбику: подписи считаются в начале анимации, когда он ещё нулевой
        const scale = context.chart.scales[valueAxis]
        return Math.abs(scale.getPixelForValue(context.dataset.data[context.dataIndex]) - scale.getPixelForValue(0)) > LABEL_ROOM
      }

      this.chart = markRaw(
        new Chart(canvas, {
          type: 'bar',
          data: {
            labels: rows.map((row) => row.label),
            datasets: this.series.map((series, index) => {
              const data = rows.map((row) => row.values[index] ?? null)
              return {
                label: series.label,
                data,
                backgroundColor: data.map((number) => (typeof series.color === 'function' ? series.color(number) : series.color)),
                borderRadius: pair ? 3 : 4,
                maxBarThickness: pair ? (narrow ? 12 : 18) : narrow ? 18 : 30,
                categoryPercentage: 0.8,
                barPercentage: 0.9,
                datalabels: {
                  display: (context) => context.dataset.data[context.dataIndex] !== null,
                  // start/end считаются по значению: у отрицательного столбика дальний от нуля край — start
                  anchor: (context) => (negative(context) && !narrow && !inside(context) ? 'start' : 'end'),
                  align: (context) => {
                    if (narrow) return 'right'
                    return negative(context) ? 'bottom' : 'top'
                  },
                  offset: 3,
                  rotation: narrow ? 0 : -90,
                  color: (context) => (inside(context) ? '#fff' : strong),
                  // Повёрнутый жирный текст мелкого размера слипается: шрифт полегче, между знаками — волосяная шпация,
                  // разряды разделены обычным пробелом
                  font: { weight: narrow ? 800 : 700, size: narrow ? 10 : pair ? 11 : 12 },
                  formatter: (number) => (narrow ? value(number) : [...value(number).replace(/\s/g, ' ')].join('\u200a')),
                },
              }
            }),
          },
          options: {
            indexAxis: storeAxis,
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: 'index', intersect: false, axis: storeAxis },
            layout: {
              padding: narrow
                ? { top: 4, right: this.format === 'money' ? 70 : 52, left: 4 }
                : { top: this.format === 'money' ? 84 : 58, bottom: 4, right: 4 },
            },
            animation: { duration: 900, easing: 'easeOutQuart' },
            plugins: {
              legend: { display: false },
              tooltip: {
                backgroundColor: surface,
                titleColor: this.isDark ? '#fff' : '#0b0b0b',
                bodyColor: text,
                borderColor: grid,
                borderWidth: 1,
                padding: 10,
                cornerRadius: 10,
                displayColors: pair,
                usePointStyle: true,
                filter: (item) => item.raw !== null,
                callbacks: {
                  label: (context) => ` ${context.dataset.label}: ${value(context.raw)}`,
                  afterBody: (items) => rows[items[0].dataIndex].extra || [],
                },
              },
            },
            scales: {
              [storeAxis]: {
                grid: { display: false },
                border: { display: false },
                ticks: {
                  color: text,
                  font: { size: 10, weight: 600 },
                  autoSkip: false,
                  maxRotation: 90,
                  minRotation: narrow ? 0 : 90,
                  // Длинные названия сокращаются, полное — в подсказке
                  callback(index) {
                    const name = this.getLabelForValue(index)
                    const limit = narrow ? 16 : 24
                    return name.length > limit ? `${name.slice(0, limit - 1)}…` : name
                  },
                },
              },
              [valueAxis]: {
                position: narrow ? 'top' : 'left',
                // Нулевая линия заметнее: у убыточных магазинов столбики уходят ниже нуля
                grid: { color: (context) => (context.tick.value === 0 ? zero : grid) },
                border: { display: false },
                beginAtZero: true,
                // Короткий убыток подписан за концом столбика: небольшой запас, чтобы подпись не наезжала на названия
                suggestedMin: lowest < 0 && !narrow ? lowest * 1.08 : undefined,
                ticks: { color: text, callback: (number) => this.tick(number) },
              },
            },
          },
        }),
      )
    },
  },
}
</script>

<style lang="scss" scoped>
