    border-radius: $radius-pill;
    background: rgb(var(--v-theme-surface));
    color: rgba(var(--v-theme-on-surface), 0.75);
    font: inherit;
    font-size: 0.78rem;
    font-weight: 700;
    cursor: pointer;
