    &:hover {
      border-color: var(--dot);
    }

    &:focus-visible {
      outline: 2px solid rgb(var(--v-theme-brand-yellow));
      outline-offset: 2px;
    }

    &--active {
      border-color: transparent;
      background: var(--dot);
      color: #fff;
    }
  }

  // Высота обычного графика; повёрнутый получает высоту по числу магазинов
  &__chart {
    position: relative;
    height: 520px;
  }
}
</style>
