<template>
  <!-- У каждого показателя свой цвет и узор в углу; канал продаж выделен сильнее (кромка, название в цвете) -->
  <article
    class="cmp-chart"
    :class="[`cmp-chart--${metric.pattern}`, { 'cmp-chart--channel': metric.channel }]"
    :style="{ '--i': index, '--accent': metric.accent }"
  >
    <header class="cmp-chart__head">
      <span class="cmp-chart__icon" aria-hidden="true">
        <v-icon :icon="metric.icon" size="18" />
      </span>
      <h3 class="cmp-chart__title">{{ $t(metric.title) }}</h3>
      <span v-if="unit" class="cmp-chart__unit">{{ unit }}</span>
    </header>

    <!-- Стеклянные столбцы «план / факт / прошлый год» по периодам; пункт легенды скрывает ряд -->
    <glass-bars
      :groups="periods"
      :series="legend"
      :values="values"
      :value-format="label"
      :tick-format="tick"
      :full-format="full"
    />

    <!-- По каждому периоду (под его столбцами): выполнение плана и рост к прошлому году (если прошлый год есть) -->
    <ul class="cmp-chart__stats" :style="{ '--n': periods.length }">
      <li v-for="(item, position) in series" :key="periods[position]" class="cmp-chart__stat">
        <span class="cmp-chart__pair">
          <small>{{ $t('compare.done') }}</small>
          <b class="cmp-chart__done" :class="`cmp-chart__done--${item.status}`">{{ item.done === null ? '—' : percent(item.done) }}</b>
        </span>
        <span v-if="hasPast" class="cmp-chart__pair">
          <small>{{ $t('compare.yoy') }}</small>
          <b class="cmp-chart__yoy" :class="`cmp-chart__yoy--${item.yoyTrend}`">{{ yoyText(item.yoy) }}</b>
        </span>
      </li>
    </ul>
  </article>
</template>

<script>
import GlassBars from '@/components/GlassBars.vue'
import numberFormatMixin from '@/mixins/numberFormat'
import { SERIES_COLORS, metricSeries, signedChange } from '@/utils/compare'
import { numberFormat } from '@/utils/format'

// Показатели в гривнах — к единице добавляется «грн»
const MONEY = ['products', 'noIphone', 'services', 'check', 'shop', 'mono']

// Карточка показателя: стеклянные столбцы «план / факт / прошлый год» по выбранным периодам с подписями значений,
// под ними — выполнение плана и рост к прошлому году по каждому периоду
export default {
  name: 'CompareMetricChart',

  components: { GlassBars },

  mixins: [numberFormatMixin],

  props: {
    metric: {
      type: Object,
      required: true,
    },
    periods: {
      type: Array,
      required: true,
    },
    // Строки таблицы по периодам (в том же порядке)
    rows: {
      type: Array,
      required: true,
    },
    // Порядковый номер карточки — задержка появления
    index: {
      type: Number,
      default: 0,
    },
  },

  computed: {
    series() {
      return metricSeries(this.metric, this.rows)
    },

    hasPast() {
      return this.series.some((item) => item.past !== null)
    },

    // Масштаб подписей: большие суммы — в миллионах или тысячах с одним знаком, чтобы подписи помещались над столбцами
    scale() {
      if (this.metric.percent) return { divisor: 1, digits: this.metric.digits }
      const max = Math.max(0, ...this.series.flatMap((item) => [item.fact, item.plan, item.past].map((value) => Math.abs(value || 0))))
      if (max >= 1e6) return { divisor: 1e6, digits: 1, label: this.$t('compare.million') }
      if (max >= 1e4) return { divisor: 1e3, digits: 1, label: this.$t('compare.thousand') }
      return { divisor: 1, digits: this.metric.digits }
    },

    unit() {
      if (this.metric.percent) return '%'
      const money = MONEY.includes(this.metric.id) ? this.$t('kpi.uah') : ''
      return [this.scale.label, money].filter(Boolean).join(' ')
    },

    // Ряды: план, факт, прошлый год (у кредита прошлого года нет)
    legend() {
      const list = [
        { id: 'plan', label: this.$t('compare.plan'), color: SERIES_COLORS.plan },
        { id: 'fact', label: this.$t('compare.fact'), color: SERIES_COLORS.fact },
      ]
      if (this.hasPast) list.push({ id: 'past', label: this.$t('compare.past'), color: SERIES_COLORS.past })
      return list
    },

    values() {
      return this.legend.map((item) => this.series.map((point) => point[item.id]))
    },
  },

  methods: {
    number(value, digits) {
      return numberFormat(this.$i18n.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value)
    },

    // Подпись над столбцом — в масштабе карточки
    label(value) {
      const text = this.number(value / this.scale.divisor, this.scale.digits)
      return this.metric.percent ? `${text}%` : text
    },

    // Подпись шкалы: без лишних нулей после запятой (150, а не 150,0)
    tick(value) {
      const text = numberFormat(this.$i18n.locale, { maximumFractionDigits: this.scale.digits }).format(value / this.scale.divisor)
      return this.metric.percent ? `${text}%` : text
    },

    // Полное значение для подсказки
    full(value) {
      return `${this.number(value, this.metric.digits)}${this.metric.suffix || ''}`
    },

    yoyText(value) {
      return signedChange(value, this.$i18n.locale, this.metric.percent && this.$t('compare.points'))
    },
  },
}
</script>

