import { defineStore } from 'pinia'
import { fetchResults } from '@/services/results'
import { createRetry } from '@/utils/retry'

const retry = createRetry()

// Данные страницы «Підсумки». Загружаются при первом открытии страницы и дальше живут до перезагрузки сайта
export const useResultsStore = defineStore('results', {
  state: () => ({
    // { main_kpi: [...], ... } или null, пока не загрузились
    tables: null,
    loading: false,
    // Данных ещё нет, а последняя попытка загрузки не удалась
    failed: false,
  }),

  getters: {
    loaded: (state) => state.tables !== null,

    // Периоды в порядке таблицы main_kpi, в той же форме, что строки компании: { time }
    periods: (state) => {
      if (!state.tables) return []
      return [...new Set(state.tables.main_kpi.map((row) => row.period))].map((time) => ({ time }))
    },
  },

  actions: {
    // Пока данных нет, после ошибки запрос сразу повторяется (NETWORK.RETRY_MS)
    // Ответ запроса, начатого до отмены (выход, уход со страницы), отбрасывается
    async load() {
      if (this.loading || this.loaded) return
      retry.clear()
      const token = retry.token()
      this.loading = true
      try {
        const tables = await fetchResults()
        if (token !== retry.token()) return
        this.tables = tables
        this.failed = false
      } catch {
        if (token !== retry.token()) return
        this.failed = true
        retry.schedule(token, () => this.load())
      } finally {
        if (token === retry.token()) this.loading = false
      }
    },

    // Строки таблицы name за период
    rowsOf(name, period) {
      return this.tables ? this.tables[name].filter((row) => row.period === period) : []
    },

    // Останавливает загрузку и повторы; следующий заход на страницу запросит данные заново
    cancelRetry() {
      retry.cancel()
      this.loading = false
    },

    // Выход из аккаунта: данные прежнего входа не должны достаться следующему
    reset() {
      this.cancelRetry()
      this.tables = null
      this.failed = false
    },
  },
})
