import { defineStore } from 'pinia'
import { NBU, NETWORK } from '@/configurations'
import { fetchRates } from '@/services/nbu'
import { createRetry } from '@/utils/retry'

const retry = createRetry(NETWORK.SIDE_RETRY_MS)
const DAY_MS = 24 * 60 * 60 * 1000

// Моменты обновления из NBU.REFRESH_TIMES за сутки, в которые попадает now
function refreshTimes(now) {
  return NBU.REFRESH_TIMES.map((time) => {
    const [hours, minutes] = time.split(':').map(Number)
    const at = new Date(now)
    at.setHours(hours, minutes, 0, 0)
    return at.getTime()
  }).sort((a, b) => a - b)
}

// Последний момент обновления, который уже наступил
function lastRefresh(now) {
  const passed = refreshTimes(now).filter((at) => at <= now)
  return passed.length ? passed[passed.length - 1] : Math.max(...refreshTimes(now)) - DAY_MS
}

// Сколько мс до следующего момента обновления
export function msToNextRefresh(now = Date.now()) {
  const times = refreshTimes(now)
  const next = times.find((at) => at > now) || times[0] + DAY_MS
  return next - now
}

export const useRatesStore = defineStore('rates', {
  state: () => ({
    rates: {},
    date: '',
    loading: false,
    // Курса ещё нет, а последняя попытка загрузки не удалась
    failed: false,
    // Когда курс получен (мс)
    loadedAt: 0,
  }),

  getters: {
    loaded: (state) => Object.keys(state.rates).length > 0,
  },

  actions: {
    // Пока курса нет, запрос повторяется каждые NETWORK.SIDE_RETRY_MS, а интерфейс показывает индикатор загрузки
    async load() {
      if (this.loading) return
      retry.clear()
      const token = retry.token()
      this.loading = true
      try {
        const { date, rates } = await fetchRates()
        if (token !== retry.token()) return
        this.date = date
        this.rates = rates
        this.failed = false
        this.loadedAt = Date.now()
      } catch {
        if (token !== retry.token()) return
        if (!this.loaded) {
          this.failed = true
          retry.schedule(token, () => this.load())
        }
      } finally {
        if (token === retry.token()) this.loading = false
      }
    },

    // Загружает курс, только если его нет или после получения наступило время обновления.
    // Блок курса в шапке появляется и исчезает при смене ширины экрана — лишних запросов при этом нет.
    ensure() {
      if (this.loaded && this.loadedAt >= lastRefresh(Date.now())) return
      return this.load()
    },

    // Блок курса скрылся: загрузка и повторы останавливаются, при следующем появлении курс запросится заново
    cancelRetry() {
      retry.cancel()
      this.loading = false
    },
  },
})
