<template>
  <div class="divider" :class="{ 'divider--visible': visible }" role="separator">
    <svg class="divider__waves" viewBox="0 0 1200 24" preserveAspectRatio="none" aria-hidden="true">
      <!-- Волны длиннее видимой области вдвое и бесконечно сдвигаются на целое число периодов: движение без рывков -->
      <g class="divider__flow divider__flow--back">
        <path :d="backWave" class="divider__wave divider__wave--back" />
      </g>
      <g class="divider__flow divider__flow--front">
        <path :d="frontWave" class="divider__wave divider__wave--front" />
      </g>
    </svg>

    <span v-if="title" class="divider__title">{{ title }}</span>
  </div>
</template>

<script>
// Волна из плавных дуг: period — длина волны, amplitude — высота, от 0 до width (единицы viewBox 1200 × 24)
function wave(period, amplitude, width) {
  const middle = 12
  let path = `M0 ${middle} Q${period / 4} ${middle - amplitude} ${period / 2} ${middle}`
  for (let x = period / 2; x < width; x += period / 2) path += ` T${x + period / 2} ${middle}`
  return path
}

// Разделитель блоков страницы: тонкая анимированная волна фирменного цвета, края растворяются в фоне
export default {
  name: 'SectionDivider',

  props: {
    // Необязательная подпись по центру
    title: {
      type: String,
      default: '',
    },
  },

  data() {
    return {
      // Волна раскрывается от центра, когда разделитель попадает в поле зрения
      visible: false,
      // Сдвиг анимации на целое число периодов: основная волна — 200, фоновая — 150
      frontWave: wave(200, 5, 2400),
      backWave: wave(150, 3.5, 2400),
    }
  },

  mounted() {
    if ('IntersectionObserver' in window) {
      this.observer = new IntersectionObserver(
        ([entry]) => {
          if (!entry.isIntersecting) return
          this.visible = true
          this.observer.disconnect()
        },
        { threshold: 0.6 },
      )
      this.observer.observe(this.$el)
    }
    // Если наблюдатель не сработал (например, вкладка в фоне), всё равно показываем
    this.fallback = setTimeout(() => (this.visible = true), 1500)
  },

  beforeUnmount() {
    clearTimeout(this.fallback)
    if (this.observer) this.observer.disconnect()
  },
}
</script>

<style lang="scss" scoped>
.divider {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: var(--page-max, 1500px);
  height: 24px;

  &__waves {
