    left: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
    // Края растворяются в фоне; до появления волна «свёрнута» к центру
    mask-image: linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent);
    clip-path: inset(0 50% 0 50%);
    transition: clip-path 1.2s $ease-out-expo;
  }

  &--visible &__waves {
    clip-path: inset(0 0 0 0);
  }

  &__flow {
    animation: divider-flow linear infinite;

    &--front {
      // Сдвиг на 3 периода (3 × 200) за цикл
      --shift: -600px;

      animation-duration: 9s;
    }

    // Навстречу основной: 4 периода (4 × 150) за цикл
    &--back {
      transform: translateX(-600px);
      animation-name: divider-flow-back;
      animation-duration: 14s;
    }
  }

  &__wave {
    fill: none;
    stroke-linecap: round;
    vector-effect: non-scaling-stroke;

    &--front {
      stroke: rgb(var(--v-theme-brand-yellow));
      stroke-width: 2;
    }

    &--back {
      stroke: rgba(var(--v-theme-on-surface), 0.16);
      stroke-width: 1.5;
    }
  }

  &__title {
    position: relative;
    padding: 2px 14px;
    border: 1px solid rgba(var(--v-theme-brand-yellow), 0.5);
    border-radius: $radius-pill;
    background: rgb(var(--v-theme-background));
    color: rgba(var(--v-theme-on-surface), 0.65);
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
  }
}

@keyframes divider-flow {
  from {
    transform: translateX(0);
  }

  to {
    transform: translateX(var(--shift));
  }
}

@keyframes divider-flow-back {
  from {
    transform: translateX(-600px);
  }

  to {
    transform: translateX(0);
  }
}

// Уменьшенное движение: волна сразу видна и стоит на месте
@media (prefers-reduced-motion: reduce) {
  .divider__waves {
    clip-path: none;
    transition: none;
  }

  .divider__flow {
    animation: none;
  }
}
</style>
