import { numberFormat } from '@/utils/format'

// Общее форматирование чисел для блоков страницы «Підсумки»: на языке интерфейса, одинаково во всех блоках.
// Подключение: mixins: [numberFormatMixin]
export default {
  methods: {
    // Целое число с разрядами: 11 676 816
    money(value) {
      return numberFormat(this.$i18n.locale, { maximumFractionDigits: 0 }).format(value)
    },

    // Процент из значения в процентах: 22,6%. Совсем маленькая доля — «<0,1%», а не «0,0%», чтобы не выглядела нулём
    percent(value, digits = 1) {
      const format = numberFormat(this.$i18n.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits })
      if (value > 0 && value < 0.05 && digits === 1) return `<${format.format(0.1)}%`
      return `${format.format(value)}%`
    },

    // В миллионах: 11,6 млн
    millions(value) {
      return `${numberFormat(this.$i18n.locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(value / 1e6)} ${this.$t('kpi.million')}`
    },

    // Коротко: от миллиона — в миллионах (34,0 млн), меньше — в тысячах (994 тис)
    compact(value) {
      if (Math.abs(value) >= 1e6) return this.millions(value)
      return `${numberFormat(this.$i18n.locale, { maximumFractionDigits: 0 }).format(value / 1e3)} ${this.$t('results.stores.thousand')}`
    },
  },
}
