import {
  ALL_PERMISSIONS,
  APP,
  AUTH,
  COMPANY,
  KPI,
  LOCALES,
  MANAGERS,
  managerPermission,
  NBU,
  NETWORK,
  PERMISSIONS,
  RESULTS,
  BUDGET,
  ROLE_PERMISSIONS,
  ROLES,
  THEMES,
  UI,
  WEATHER,
  WORKDAY,
} from '@/configurations'

const GAS_URL = /^https:\/\/script\.google\.com\/macros\/s\/[\w-]+\/exec$/
const MANAGER_ID = /^[a-z0-9_-]+$/
const TIME = /^([01]\d|2[0-3]):[0-5]\d$/
const LEADERSHIP_ROLES = [ROLES.SUPER, ROLES.CEO, ROLES.ANALYST]

const isPositive = (value) => typeof value === 'number' && Number.isFinite(value) && value > 0
const isHour = (value) => Number.isInteger(value) && value >= 0 && value <= 24
const isText = (value) => typeof value === 'string' && value.trim() !== ''

function duplicates(list) {
  return [...new Set(list.filter((item, index) => list.indexOf(item) !== index))]
}

// Проверяет configurations.js и возвращает список понятных описаний ошибок (пустой — всё в порядке).
// translated(key, locale) — есть ли перевод; через него проверяются города и валюты в файлах src/locales.
export function validateConfig(translated) {
  const problems = []
  const add = (text) => problems.push(text)

  // 1. Приложение и вход
  if (!isText(APP.VERSION)) add('APP.VERSION не заполнена')
  if (!GAS_URL.test(AUTH.URL)) add(`AUTH.URL не похожа на ссылку GAS-скрипта (https://script.google.com/macros/s/…/exec): «${AUTH.URL}»`)
  if (!isPositive(AUTH.SESSION_HOURS)) add('AUTH.SESSION_HOURS должно быть положительным числом часов')

  // 2. Источники данных
  if (!GAS_URL.test(COMPANY.URL)) add(`COMPANY.URL не похожа на ссылку GAS-скрипта: «${COMPANY.URL}»`)
  if (!GAS_URL.test(RESULTS.URL)) add(`RESULTS.URL не похожа на ссылку GAS-скрипта: «${RESULTS.URL}»`)
  if (!GAS_URL.test(BUDGET.URL)) add(`BUDGET.URL не похожа на ссылку GAS-скрипта: «${BUDGET.URL}»`)
  const aliases = RESULTS.STORE_ALIASES || {}
  Object.entries(aliases)
    .filter(([from, to]) => !isText(from) || !isText(to))
    .forEach(([from]) => add(`RESULTS.STORE_ALIASES: у пары «${from}» пустое название`))
  Object.entries(aliases)
    .filter(([, to]) => aliases[to] !== undefined)
    .forEach(([from, to]) => add(`RESULTS.STORE_ALIASES: «${to}» (пара для «${from}») само указано слева — цепочки не поддерживаются`))
  if (!Array.isArray(RESULTS.STORES_WITHOUT_PLAN)) add('RESULTS.STORES_WITHOUT_PLAN должно быть списком названий [ … ]')
  for (const key of ['REVENUE', 'TRAFFIC']) {
    const value = RESULTS.YOY_GOOD && RESULTS.YOY_GOOD[key]
    if (typeof value !== 'number' || value < 0) add(`RESULTS.YOY_GOOD.${key} должно быть числом процентов не меньше 0`)
  }

  const currencyCodes = NBU.CURRENCIES.map((currency) => currency.code)
  duplicates(currencyCodes).forEach((code) => add(`NBU.CURRENCIES: валюта ${code} указана дважды`))
  NBU.CURRENCIES.forEach(({ code, symbol }) => {
    if (!/^[A-Z]{3}$/.test(code)) add(`NBU.CURRENCIES: код валюты «${code}» должен быть из трёх заглавных латинских букв (USD, EUR…)`)
    if (!isText(symbol)) add(`NBU.CURRENCIES: у валюты ${code} нет значка symbol`)
  })
  NBU.REFRESH_TIMES.forEach((time) => {
    if (!TIME.test(time)) add(`NBU.REFRESH_TIMES: время «${time}» должно быть в формате ЧЧ:ММ, например '08:00'`)
  })

  const cityIds = WEATHER.CITIES.map((city) => city.id)
  duplicates(cityIds).forEach((id) => add(`WEATHER.CITIES: город «${id}» указан дважды`))
  WEATHER.CITIES.forEach(({ id, query }) => {
    if (!isText(query)) add(`WEATHER.CITIES: у города «${id}» не заполнен query`)
  })
  if (!cityIds.includes(WEATHER.DEFAULT_CITY)) add(`WEATHER.DEFAULT_CITY: города «${WEATHER.DEFAULT_CITY}» нет в WEATHER.CITIES`)
  if (!isPositive(WEATHER.REFRESH_MS)) add('WEATHER.REFRESH_MS должно быть положительным числом миллисекунд')

  // 3. Сеть
  if (!isPositive(NETWORK.TIMEOUT)) add('NETWORK.TIMEOUT должно быть положительным числом миллисекунд')
  if (typeof NETWORK.RETRY_MS !== 'number' || !(NETWORK.RETRY_MS >= 0)) add('NETWORK.RETRY_MS должно быть числом миллисекунд, 0 или больше')
  if (!isPositive(NETWORK.SIDE_RETRY_MS)) add('NETWORK.SIDE_RETRY_MS должно быть положительным числом миллисекунд')

  // 4. Менеджеры
  const managerIds = MANAGERS.map((manager) => manager.id)
  duplicates(managerIds).forEach((id) => add(`MANAGERS: id «${id}» есть у нескольких менеджеров, он должен быть уникальным`))
  MANAGERS.forEach((manager, index) => {
    const who = `MANAGERS[${index}]${manager.name ? ` (${manager.name})` : ''}`
    if (!MANAGER_ID.test(manager.id || '')) add(`${who}: id «${manager.id}» — только латиница в нижнем регистре, цифры, «-» и «_»`)
    if (LEADERSHIP_ROLES.includes(manager.id)) add(`${who}: id «${manager.id}» совпадает с ролью руководства, выберите другой`)
    if (!isText(manager.name)) add(`${who}: не заполнено имя name`)
    if (!isText(manager.color) || !CSS.supports('color', manager.color)) add(`${who}: цвет «${manager.color}» браузер не понимает`)
    if (!GAS_URL.test(manager.url || '')) add(`${who}: url не похож на ссылку GAS-скрипта: «${manager.url}»`)
    if (manager.dataKey !== undefined && !isText(manager.dataKey)) add(`${who}: dataKey должен быть непустой строкой или не указан вовсе`)
  })
  duplicates(MANAGERS.map((manager) => String(manager.color).toLowerCase())).forEach((color) =>
    add(`MANAGERS: цвет ${color} у нескольких менеджеров — на графиках их не различить`),
  )

  // 5. Роли и доступ
  const known = new Set([ALL_PERMISSIONS, ...Object.values(PERMISSIONS), ...managerIds.map(managerPermission)])
  Object.entries(ROLE_PERMISSIONS).forEach(([role, permissions]) => {
    if (!Array.isArray(permissions)) {
      add(`ROLE_PERMISSIONS.${role}: права должны быть списком [ … ]`)
      return
    }
    permissions.filter((permission) => !known.has(permission)).forEach((permission) =>
      add(`ROLE_PERMISSIONS.${role}: права «${permission}» не существует (нет в PERMISSIONS или такого менеджера нет в MANAGERS)`),
    )
  })

  // 6. Показатели и интерфейс
  if (typeof KPI.WARN_FROM !== 'number' || KPI.WARN_FROM < 0 || KPI.WARN_FROM > 100) add('KPI.WARN_FROM должно быть числом от 0 до 100')
  if (!isPositive(UI.INFO_MIN_WIDTH)) add('UI.INFO_MIN_WIDTH должно быть положительным числом пикселей')
  const hours = ['SHOW_FROM', 'START', 'LUNCH_START', 'LUNCH_END', 'END', 'HIDE_AFTER']
  hours.filter((key) => !isHour(WORKDAY[key])).forEach((key) => add(`WORKDAY.${key} должно быть целым часом от 0 до 24`))
  if (hours.every((key) => isHour(WORKDAY[key]))) {
    const { SHOW_FROM, START, LUNCH_START, LUNCH_END, END, HIDE_AFTER } = WORKDAY
    if (!(SHOW_FROM <= START && START < LUNCH_START && LUNCH_START < LUNCH_END && LUNCH_END < END && END <= HIDE_AFTER)) {
      add('WORKDAY: часы должны идти по порядку SHOW_FROM ≤ START < LUNCH_START < LUNCH_END < END ≤ HIDE_AFTER')
    }
  }
  WORKDAY.DAYS.filter((day) => !Number.isInteger(day) || day < 0 || day > 6).forEach((day) =>
    add(`WORKDAY.DAYS: «${day}» — день недели должен быть числом от 0 (воскресенье) до 6 (суббота)`),
  )

  // 7. Языки и темы
  const localeCodes = LOCALES.AVAILABLE.map((locale) => locale.code)
  if (!localeCodes.includes(LOCALES.DEFAULT)) add(`LOCALES.DEFAULT: языка «${LOCALES.DEFAULT}» нет в LOCALES.AVAILABLE`)
  if (!localeCodes.includes(LOCALES.FALLBACK)) add(`LOCALES.FALLBACK: языка «${LOCALES.FALLBACK}» нет в LOCALES.AVAILABLE`)
  if (!THEMES.AVAILABLE[THEMES.DEFAULT]) add(`THEMES.DEFAULT: темы «${THEMES.DEFAULT}» нет, есть: ${Object.keys(THEMES.AVAILABLE).join(', ')}`)

  // Переводы городов и валют: без них в шапке вместо названия показался бы ключ вроде cities.lutsk
  localeCodes.forEach((locale) => {
    const file = `src/locales/${locale}.json`
    cityIds.filter((id) => !translated(`cities.${id}`, locale)).forEach((id) => add(`${file}: нет названия города "cities.${id}"`))
    currencyCodes.filter((code) => !translated(`currency.${code}`, locale)).forEach((code) => add(`${file}: нет названия валюты "currency.${code}"`))
  })

  return problems
}
