<template>
  <transition name="to-top">
    <button v-if="visible" type="button" class="to-top" :aria-label="$t('common.scrollTop')" :title="$t('common.scrollTop')" @click="scrollTop">
      <v-icon :icon="mdiChevronUp" size="26" />
    </button>
  </transition>
</template>

<script>
import { mdiChevronUp } from '@mdi/js'

// Через сколько пикселей прокрутки появляется кнопка
const SHOW_AFTER = 400

// Кнопка «Нагору»: появляется, когда страницу прокрутили вниз, и плавно возвращает к началу
export default {
  name: 'ScrollTopButton',

  data() {
    return {
      mdiChevronUp,
      visible: false,
    }
  },

  mounted() {
    window.addEventListener('scroll', this.onScroll, { passive: true })
    this.onScroll()
  },

  beforeUnmount() {
    window.removeEventListener('scroll', this.onScroll)
  },

  methods: {
    onScroll() {
      this.visible = window.scrollY > SHOW_AFTER
    },

    scrollTop() {
      window.scrollTo({ top: 0, behavior: 'smooth' })
    },
  },
}
</script>

