<template>
  <budget-bars
    v-model:sort-by="sortBy"
    :label="$t('budget.rentab.title')"
    :rows="rows"
    :series="series"
    :stats-start="series.map((item) => ({ id: item.id, label: item.label, color: item.color, value: percent(averages[item.id] * 100) }))"
    :sort-options="series"
  />
</template>

<script>
import { mapState } from 'pinia'
import BudgetBars from '@/components/BudgetBars.vue'
import numberFormatMixin from '@/mixins/numberFormat'
import { useBudgetStore } from '@/stores/budget'
import { useScopeStore } from '@/stores/scope'
import { MARGIN_EXCLUDED, SPECIAL, n, rowOpProfit, rowProfitability, rowProfitabilityAfter } from '@/utils/budget'

// Два показателя на одном графике, цвета — как на прежней странице
const SERIES = [
  { id: 'rentab', color: 'rgba(99, 102, 241, 0.85)' },
  { id: 'after', color: 'rgba(20, 184, 166, 0.75)' },
]

// Рентабельность магазинов за месяц (budget-page-map.md, блок 7–9): прибуток від діяльності к доходу и готовая
// «рентабельність після офісу» из таблицы (rentab_after). Только магазины (без служебных строк),
// без Інтернет-магазину и Сервісу Маяковського — как у маржинальности
export default {
  name: 'BudgetRentab',

  components: { BudgetBars },

  mixins: [numberFormatMixin],

  data() {
    return {
      // По какому показателю сортировать магазины: rentab или after
      sortBy: 'rentab',
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    stores() {
      return useBudgetStore()
        .rowsOf(this.period)
        .filter((row) => !SPECIAL.has(row.store) && !MARGIN_EXCLUDED.has(row.store))
        .map((row) => ({ store: row.store, revenue: n(row.revenue), op: rowOpProfit(row), rentab: rowProfitability(row), after: rowProfitabilityAfter(row) }))
        .sort((a, b) => b[this.sortBy] - a[this.sortBy])
    },

    // Средние по этим магазинам, взвешенные по доходу
    averages() {
      const revenue = this.stores.reduce((sum, row) => sum + row.revenue, 0)
      const weighted = (field) => (revenue ? this.stores.reduce((sum, row) => sum + row[field] * row.revenue, 0) / revenue : 0)
      return { rentab: weighted('rentab'), after: weighted('after') }
    },

    series() {
      return SERIES.map((item) => ({ ...item, label: this.$t(`budget.rentab.${item.id}`) }))
    },

    rows() {
      const uah = this.$t('kpi.uah')
      return this.stores.map((row) => ({
        label: row.store,
        values: [row.rentab, row.after],
        extra: [`${this.$t('budget.kpi.revenue')}: ${this.money(row.revenue)} ${uah}`, `${this.$t('budget.rentab.opProfit')}: ${this.money(row.op)} ${uah}`],
      }))
    },
  },
}
</script>
