<!-- Страница «Порівняння»: показатели главной и страниц РМ в выбранных периодах — по всей сети, по РМ
     или по магазину РМ. Данные — уже загруженные таблицы компании и менеджеров. Комментарии вне <template>:
     иначе ломается <transition> страниц -->
<template>
  <div class="compare">
    <div ref="top" class="compare__block">
      <section-title :icon="mdiTune" :title="$t('compare.params')" />
      <compare-controls />
    </div>

    <p v-if="!ready" class="compare__wait">
      <v-progress-circular indeterminate size="20" width="2" />
      {{ $t('compare.notReady') }}
    </p>

    <!-- Все периоды сняты: заглушка с подсказкой и быстрым выбором -->
    <transition v-else-if="!periods.length" name="compare-empty" appear>
      <section class="compare-empty" role="status">
        <div class="compare-empty__art" aria-hidden="true">
          <span class="compare-empty__ring"></span>
          <span class="compare-empty__ring compare-empty__ring--late"></span>
          <span class="compare-empty__icon">
            <v-icon :icon="mdiCalendarSearch" size="34" />
          </span>
        </div>
        <h2 class="compare-empty__title">{{ $t('compare.emptyTitle') }}</h2>
        <p class="compare-empty__text">{{ $t('compare.emptyText', { n: max }) }}</p>
        <button v-if="lastMonths.length" type="button" class="compare-empty__action" @click="setPeriods(lastMonths)">
          <v-icon :icon="mdiCalendarMultiselect" size="18" />
          {{ $t('compare.last3') }}
        </button>
      </section>
    </transition>

    <template v-else>
      <section-divider />

      <div class="compare__block">
        <section-title :icon="mdiViewGridOutline" :title="$t('compare.metrics')" :period="scopeName" />
        <compare-metrics />
      </div>

      <!-- Каналы продаж — только у всей сети, отдельным блоком -->
      <template v-if="network">
        <section-divider />

        <div class="compare__block">
          <section-title :icon="mdiCartOutline" :title="$t('compare.channels')" :period="scopeName" />
          <compare-metrics channels />
        </div>
      </template>

      <section-divider />

      <div class="compare__block">
        <section-title :icon="mdiShapeOutline" :title="$t('compare.categories')" :period="scopeName" />
        <compare-categories />
      </div>

      <section-divider />

      <div class="compare__block">
        <section-title :icon="mdiFormatListBulleted" :title="$t('compare.breakdown')" :period="scopeName" />
        <compare-breakdown @drill="toTop" />
      </div>
    </template>
  </div>
</template>

<script>
import { mapActions, mapState } from 'pinia'
import { mdiCalendarMultiselect, mdiCalendarSearch, mdiCartOutline, mdiFormatListBulleted, mdiShapeOutline, mdiTune, mdiViewGridOutline } from '@mdi/js'
import CompareBreakdown from '@/components/CompareBreakdown.vue'
import CompareCategories from '@/components/CompareCategories.vue'
import CompareControls from '@/components/CompareControls.vue'
import CompareMetrics from '@/components/CompareMetrics.vue'
import SectionDivider from '@/components/SectionDivider.vue'
import SectionTitle from '@/components/SectionTitle.vue'
import { useCompareStore } from '@/stores/compare'
import { MAX_PERIODS } from '@/utils/compare'

export default {
  name: 'CompareView',

  components: { CompareBreakdown, CompareCategories, CompareControls, CompareMetrics, SectionDivider, SectionTitle },

  data() {
    return {
      max: MAX_PERIODS,
      mdiCalendarMultiselect,
      mdiCalendarSearch,
      mdiCartOutline,
      mdiFormatListBulleted,
      mdiShapeOutline,
      mdiTune,
      mdiViewGridOutline,
    }
  },

  computed: {
    ...mapState(useCompareStore, ['ready', 'manager', 'store', 'network', 'periods', 'lastMonths']),

    // Что сейчас сравнивается — подпись рядом с названием блока
    scopeName() {
      if (!this.manager) return this.$t('compare.network')
      return this.store ? `${this.manager.name} · ${this.store}` : this.manager.name
    },
  },

  methods: {
    ...mapActions(useCompareStore, ['setPeriods']),

    // Переход к РМ или магазину из деталізації: страница поднимается к показателям
    toTop() {
      this.$refs.top.scrollIntoView({ behavior: 'smooth', block: 'start' })
    },
  },
}
</script>

