<template>
  <section class="boffice" :aria-label="$t('budget.office.title')">
    <budget-pie
      v-for="pie in pies"
      :key="pie.id"
      :title="$t(`budget.office.${pie.id}`)"
      :icon="pie.icon"
      :from="pie.from"
      :to="pie.to"
      :items="pie.items"
      :half-width="shared.halfWidth"
      :half-height="shared.halfHeight"
      :radius="SHAPE.r"
      :start-angle="SHAPE.startAngle"
      :inline="SHAPE.inline"
      :row-gap="SHAPE.rowGap"
      :animate="false"
      clickable
      @open="open(pie)"
    />

    <!-- Окно диаграммы: тот же круг того же общего размера, только крупнее -->
    <budget-pie-dialog
      v-model="dialog"
      :pie="active && { title: $t(`budget.office.${active.id}`), icon: active.icon, from: active.from, to: active.to, items: active.items, ...shared, ...shapeProps(SHAPE) }"
    />
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiDomain, mdiWarehouse } from '@mdi/js'
import BudgetPie, { COMPACT_SHAPE, pieFormat, shapeProps } from '@/components/BudgetPie.vue'
import BudgetPieDialog from '@/components/BudgetPieDialog.vue'
import numberFormatMixin from '@/mixins/numberFormat'
import { useBudgetStore } from '@/stores/budget'
import { useScopeStore } from '@/stores/scope'
import { calloutLayout } from '@/utils/calloutPie'
import { EXPENSE_COLORS, EXPENSE_FIELDS, n } from '@/utils/budget'

// Строки таблицы и шапки карточек — как на прежней странице: офис фиолетовый, склад бирюзовый
const PLACES = [
  { id: 'office', store: 'Офіс Київ', icon: mdiDomain, from: '#6366f1', to: '#4338ca' },
  { id: 'warehouse', store: 'Склад Київ', icon: mdiWarehouse, from: '#14b8a6', to: '#0f766e' },
]
// Статей в круге не больше этого: самые мелкие собираются в «Інше» (серое), чтобы круг не дробился
const MAX_ITEMS = 10
const OTHER_COLOR = '#94a3b8'

// Круг — как у карточек магазинов: подписи компактные, мелкие статьи столбиком сбоку
const SHAPE = COMPACT_SHAPE

// Офіс та Склад Київ (budget-page-map.md, блоки 13–14): структура расходов двух служебных строк. Прибыли у них нет —
// только статьи расходов. Размер кругов общий: круг и текст у обеих карточек одного размера
export default {
  name: 'BudgetOffice',

  components: { BudgetPie, BudgetPieDialog },

  mixins: [numberFormatMixin],

  data() {
    return {
      SHAPE,
      dialog: false,
      // id карточки, открытой в окне
      activeId: null,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    active() {
      return this.pies.find((pie) => pie.id === this.activeId) || null
    },

    pies() {
      const rows = useBudgetStore().rowsOf(this.period)
      return PLACES.map((place) => {
        const row = rows.find((item) => item.store === place.store) || {}
        const items = EXPENSE_FIELDS.map((field) => ({
          id: field,
          label: this.$t(`budget.fields.${field}`),
          value: n(row[field]),
          color: EXPENSE_COLORS[field],
        }))
          .filter((item) => item.value > 0)
          .sort((a, b) => b.value - a.value)
        if (items.length <= MAX_ITEMS) return { ...place, items }
        const rest = items.slice(MAX_ITEMS - 1)
        const other = { id: 'other', label: this.$t('budget.pies.other'), value: rest.reduce((sum, item) => sum + item.value, 0), color: OTHER_COLOR }
        return { ...place, items: [...items.slice(0, MAX_ITEMS - 1), other] }
      })
    },

    shared() {
      const format = pieFormat(this)
      const layouts = this.pies.filter((pie) => pie.items.length).map((pie) => calloutLayout(pie.items, { ...SHAPE, format }))
      return { halfWidth: Math.max(0, ...layouts.map((item) => item.halfWidth)), halfHeight: Math.max(0, ...layouts.map((item) => item.halfHeight)) }
    },
  },

  watch: {
    // Другой месяц: открытое окно показывает уже другие данные — закрываем
    period() {
      this.dialog = false
    },
  },

  methods: {
    shapeProps,

    open(pie) {
      this.activeId = pie.id
      this.dialog = true
    },
  },
}
</script>

<style lang="scss" scoped>
// Две карточки рядом; уже — одна колонка
.boffice {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: $spacer * 5;
  width: 100%;
  max-width: var(--page-max, 1500px);

  @media (max-width: #{$breakpoint-lg - 1px}) {
    grid-template-columns: minmax(0, 1fr);
    gap: $spacer * 4;
  }
}
</style>
