<template>
  <section class="its" :aria-label="$t('items.title')">
    <panel-head :icon="mdiBasketOutline" :title="$t('items.title')" :period="period" />

    <!-- Сводка по РМ: итоговая строка менеджера и магазины -->
    <ul class="its__summary">
      <li v-if="managerFact !== null">
        <span>{{ $t('items.stores.average') }}</span>
        <b>{{ number(managerFact, 2) }}</b>
        <small v-if="managerPlan !== null">{{ $t('kpi.plan') }} {{ number(managerPlan, 2) }}</small>
      </li>
      <li>
        <span>{{ $t('items.stores.onPlan') }}</span>
        <b>{{ onPlan }} / {{ withPlan }}</b>
      </li>
      <li>
        <span>{{ $t('items.stores.grew') }}</span>
        <b>{{ grew }} / {{ withPast }}</b>
      </li>
    </ul>

    <!-- Полоса — отклонение от плана: от линии плана вправо — перевыполнение, влево — недовыполнение -->
    <ol class="its__rows">
      <li
        v-for="(item, index) in items"
        :key="item.manager.id"
        class="its__row"
        :style="{ '--mc': item.rgb, '--i': index }"
      >
        <span class="its__name" :title="item.manager.name">{{ item.manager.name }}</span>

        <span class="its__track" role="img" :aria-label="rowLabel(item)">
          <i class="its__target"></i>
          <i v-if="item.percent !== null" class="its__bar" :style="barStyle(item.percent)"></i>
        </span>

        <span class="its__numbers">
          <b>{{ number(item.fact, 2) }}</b>
          <small v-if="item.plan !== null">{{ $t('items.stores.of') }} {{ number(item.plan, 2) }}</small>
        </span>

        <b class="its__pill">{{ item.percent === null ? '—' : `${number(item.percent, 1)}%` }}</b>

        <small v-if="item.delta !== null" class="its__delta" :class="item.delta >= 0 ? 'its__delta--up' : 'its__delta--down'">
          {{ item.delta >= 0 ? '▲' : '▼' }} {{ number(Math.abs(item.delta), 0) }}% {{ $t('kpi.vsPast') }}
        </small>
        <small v-else class="its__delta"></small>
      </li>
    </ol>

    <p class="its__note">
      <i class="its__note-target" aria-hidden="true"></i>
      {{ $t('items.stores.note') }}
    </p>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiBasketOutline } from '@mdi/js'
import PanelHead from '@/components/PanelHead.vue'
import { useScopeStore } from '@/stores/scope'
import { entryRgb } from '@/utils/color'
import { numberFormat } from '@/utils/format'
import { completion, growth, statusOf } from '@/utils/kpi'

const isNumber = (value) => typeof value === 'number' && Number.isFinite(value)

// Количество позиций в чеке по магазинам РМ. На главной (менеджеры) остаются корзины — ItemsByManagers
export default {
  name: 'ItemsByStores',

  components: { PanelHead },

  data() {
    return {
      mdiBasketOutline,
      // Полосы заполняются после появления блока
      ready: false,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['current', 'kind', 'totals']),

    locale() {
      return this.$i18n.locale
    },

    period() {
      return this.current ? this.current.time : ''
    },

    // Итог менеджера за период (первая строка его периода)
    managerFact() {
      return this.current && isNumber(this.current.count_f) ? this.current.count_f : null
    },

    managerPlan() {
      return this.current && isNumber(this.current.count_p) ? this.current.count_p : null
    },

    // Магазины от лучшего выполнения плана к худшему; без плана — в конце
    items() {
      const list = this.totals.map(({ manager, row }) => {
        const pick = (field) => (row && isNumber(row[field]) ? row[field] : null)
        const fact = pick('count_f')
        const plan = pick('count_p')
        const past = pick('count_past')
        const percent = completion(fact, plan)
        const state = statusOf(percent)
        return { manager, fact, plan, past, percent, state, rgb: entryRgb(this.kind, manager, state), delta: growth(fact, past) }
      })
      return list.sort((a, b) => (b.percent === null ? -1 : b.percent) - (a.percent === null ? -1 : a.percent))
    },

    withPlan() {
      return this.items.filter((item) => item.percent !== null).length
    },

    onPlan() {
      return this.items.filter((item) => item.percent !== null && item.percent >= 100).length
    },

    withPast() {
      return this.items.filter((item) => item.delta !== null).length
    },

    grew() {
      return this.items.filter((item) => item.delta !== null && item.delta > 0).length
    },

    // Наибольшее отклонение от плана среди магазинов (в процентных пунктах), не меньше 5: полоса этого магазина —
    // во всю половину шкалы, остальные — пропорционально
    maxDeviation() {
      return Math.max(5, ...this.items.map((item) => item.percent).filter(isNumber).map((percent) => Math.abs(percent - 100))) * 1.05
    },
  },

  mounted() {
    this.readyTimer = setTimeout(() => (this.ready = true), 250)
  },

  beforeUnmount() {
    clearTimeout(this.readyTimer)
  },

  methods: {
    number(value, digits) {
      if (!isNumber(value)) return '—'
      return numberFormat(this.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value)
    },

    // Полоса от линии плана (середина шкалы): вправо при перевыполнении, влево при недовыполнении.
    // Пока блок не появился, полосы нулевые и потом плавно вырастают
    barStyle(percent) {
      const width = this.ready ? (Math.abs(percent - 100) / this.maxDeviation) * 50 : 0
      return percent >= 100 ? { left: '50%', width: `${width}%` } : { left: `${50 - width}%`, width: `${width}%` }
    },

    rowLabel(item) {
      const parts = [`${this.$t('kpi.fact')} ${this.number(item.fact, 2)}`]
      if (item.plan !== null) parts.push(`${this.$t('kpi.plan')} ${this.number(item.plan, 2)}`)
      if (item.past !== null) parts.push(`${this.$t('traffic.pastShort')} ${this.number(item.past, 2)}`)
      return `${item.manager.name}: ${parts.join(', ')}`
    },
  },
}
</script>

