import { MANAGERS } from '@/configurations'

// Цвета страницы «Підсумки» — из прежней версии страницы (results-page-map.md, ResultsPage.vue).
// Новые цвета здесь не придумываются: только перенос из прежней страницы.

// Цвет РМ по имени из таблиц итогов — тот же, что на главной и в его кабинете (MANAGERS); если РМ нет в списке —
// нейтральный серый (getManagerColor(rm) || '#94a3b8' на прежней странице)
const MANAGER_COLORS = Object.fromEntries(MANAGERS.map((manager) => [manager.name, manager.color]))
export const NO_MANAGER_COLOR = '#94a3b8'

export function managerColor(name) {
  return MANAGER_COLORS[name] || NO_MANAGER_COLOR
}

// Палитра категорий (catColors): цвет по месту категории в рейтинге
export const CAT_COLORS = [
  '#6366f1', '#f59e0b', '#22c55e', '#ef4444', '#14b8a6',
  '#f97316', '#8b5cf6', '#06b6d4', '#84cc16', '#ec4899', '#64748b',
  '#a855f7', '#eab308', '#10b981', '#f43f5e', '#3b82f6',
  '#d946ef', '#0ea5e9', '#65a30d', '#dc2626',
]

// Выполнение плана по категориям: 7 ступеней цвета (value — в долях, 1 = 100 %)
export function catPlanColor(value) {
  if (value >= 1.1) return '#15803d'
  if (value >= 1.05) return '#16a34a'
  if (value >= 1.0) return '#22c55e'
  if (value >= 0.95) return '#4ade80'
  if (value >= 0.9) return '#86efac'
  if (value >= 0.8) return '#eab308'
  return '#f97316'
}
