<template>
  <section class="lavina" :aria-label="$t('results.lavina.title')">
    <p v-if="!main" class="lavina__empty">{{ $t('results.lavina.empty') }}</p>

    <template v-else>
      <!-- Показатели: выполнение плана и пять карточек -->
      <div class="lavina__kpis">
        <article class="lavina__plan" :style="{ '--tone': planColor }">
          <span class="lavina__label">{{ $t('results.lavina.plan') }}</span>
          <div class="lavina__gauge" role="img" :aria-label="`${$t('results.lavina.plan')}: ${percent(planPct * 100)}`">
            <svg viewBox="0 0 200 112">
              <path d="M 20 100 A 80 80 0 0 1 180 100" class="lavina__gauge-track" pathLength="100" />
              <path
                d="M 20 100 A 80 80 0 0 1 180 100"
                class="lavina__gauge-fill"
                pathLength="100"
                :stroke-dasharray="`${Math.max(0.01, Math.min(1, planPct) * 100 * progress)} 100`"
              />
            </svg>
            <strong class="lavina__gauge-value">{{ percent(planPct * 100 * progress) }}</strong>
          </div>
        </article>

        <article v-for="kpi in kpis" :key="kpi.id" class="lavina__kpi" :style="{ '--tone': kpi.color }">
          <span class="lavina__kpi-icon" aria-hidden="true">
            <v-icon :icon="kpi.icon" size="20" />
          </span>
          <span class="lavina__label">{{ $t(`results.lavina.kpi.${kpi.id}`) }}</span>
          <strong class="lavina__kpi-value">{{ kpi.text }}</strong>
        </article>
      </div>

      <div class="lavina__row">
        <!-- Структура товарооборота: кольцо со всеми категориями и список -->
        <article class="lavina__panel lavina__panel--structure">
          <header class="lavina__head">
            <span class="lavina__icon" aria-hidden="true">
              <v-icon :icon="mdiChartDonut" size="20" />
            </span>
            <h3 class="lavina__title">{{ $t('results.lavina.structure') }}</h3>
            <b class="lavina__total">{{ money(revenueTotal) }} {{ $t('kpi.uah') }}</b>
          </header>

          <!-- Широкая панель: круг с выносками, как на прежней странице; узкая (телефон) — кольцо и список -->
          <div ref="structure" class="lavina__structure-wrap">
            <template v-if="!narrow">
              <svg
                class="lavina__callout"
                :viewBox="`0 0 ${callout.halfWidth * 2} ${callout.halfHeight * 2}`"
                role="img"
                :aria-label="$t('results.lavina.structure')"
              >
                <g :transform="`translate(${callout.halfWidth}, ${callout.halfHeight})`">
                  <path
                    v-for="segment in calloutSegments"
                    :key="segment.label"
                    :d="segment.path"
                    :fill="segment.color"
                    class="lavina__slice"
                    :class="{ 'lavina__slice--dim': hovered && hovered !== segment.label }"
                    :style="{ transform: hovered === segment.label ? segment.pop : null }"
                    @pointerenter="hovered = segment.label"
                    @pointerleave="hovered = null"
                  >
                    <title>{{ tooltip(segment) }}</title>
                  </path>

                  <g
                    v-for="label in callout.labels"
                    :key="`label-${label.label}`"
                    class="lavina__callout-label"
                    :class="{ 'lavina__callout-label--dim': hovered && hovered !== label.label, 'lavina__callout-label--active': hovered === label.label }"
                    @pointerenter="hovered = label.label"
                    @pointerleave="hovered = null"
                  >
                    <polyline :points="label.points" class="lavina__leader" />
                    <circle :cx="label.edgeX" :cy="label.edgeY" r="5" :fill="label.color" class="lavina__leader-dot" />
                    <text
                      v-for="(line, index) in label.texts"
                      :key="index"
                      :x="label.textX"
                      :y="line.y"
                      :text-anchor="label.anchor"
                      :class="`lavina__callout-${line.role}`"
                      :fill="line.role === 'name' ? label.color : null"
                    >
                      {{ line.text }}
                    </text>
                  </g>
                </g>
              </svg>

              <p v-if="hiddenCount" class="lavina__note lavina__note--center">
                {{ $t('results.lavina.smallNote', { n: hiddenCount, share: percent(hiddenShare * 100) }) }}
              </p>
            </template>

            <div v-else class="lavina__structure">
              <div class="lavina__donut">
                <svg viewBox="0 0 220 220" role="img" :aria-label="$t('results.lavina.structure')">
                  <path
                    v-for="segment in segments"
                    :key="segment.name"
                    :d="segment.path"
                    :fill="segment.color"
                    class="lavina__segment"
                    :class="{ 'lavina__segment--active': hovered === segment.name, 'lavina__segment--dim': hovered && hovered !== segment.name }"
                    @pointerenter="hovered = segment.name"
                    @pointerleave="hovered = null"
                  >
                    <title>{{ segment.name }}: {{ money(segment.value) }} {{ $t('kpi.uah') }} ({{ percent(segment.share * 100) }})</title>
                  </path>
                </svg>
                <div class="lavina__center">
                  <template v-if="activeSegment">
                    <b>{{ percent(activeSegment.share * 100) }}</b>
                    <span>{{ activeSegment.name }}</span>
                  </template>
                  <template v-else>
                    <b>{{ millions(revenueTotal) }}</b>
                    <span>{{ $t('results.lavina.categories', { n: categories.length }) }}</span>
                  </template>
                </div>
              </div>

              <div class="lavina__legend">
                <div class="lavina__legend-head" aria-hidden="true">
                  <span>{{ $t('results.lavina.category') }}</span>
                  <span>{{ $t('results.lavina.revenue') }}</span>
                  <span>{{ $t('results.lavina.share') }}</span>
                  <span>{{ $t('results.lavina.avgPrice') }}</span>
                </div>
                <ol class="lavina__list">
                  <li
                    v-for="item in visibleCategories"
                    :key="item.name"
                    class="lavina__item"
                    :class="{ 'lavina__item--active': hovered === item.name }"
                    @pointerenter="hovered = item.name"
                    @pointerleave="hovered = null"
                  >
                    <span class="lavina__name" :title="item.name">
                      <i :style="{ background: item.color }" aria-hidden="true"></i>
                      {{ item.name }}
                    </span>
                    <span class="lavina__num">{{ money(item.value) }}</span>
                    <span class="lavina__num lavina__num--share">{{ percent(item.share * 100) }}</span>
                    <span class="lavina__num lavina__num--muted">{{ item.avgPrice === null ? '—' : money(item.avgPrice) }}</span>
                  </li>
                </ol>
                <button v-if="hiddenCount" type="button" class="lavina__more" @click="showAll = !showAll">
                  {{ showAll ? $t('results.lavina.collapse') : $t('results.lavina.more', { n: hiddenCount, share: percent(hiddenShare * 100) }) }}
                </button>
              </div>
            </div>
          </div>
        </article>

        <!-- Выполнение плана по категориям: узкая колонка справа, строка в два ряда (название, под ним столбик) -->
        <article class="lavina__panel lavina__panel--plans">
          <header class="lavina__head">
            <span class="lavina__icon" aria-hidden="true">
              <v-icon :icon="mdiBullseyeArrow" size="20" />
            </span>
            <h3 class="lavina__title">{{ $t('results.lavina.catPlan') }}</h3>
          </header>

          <p v-if="!planRows.length" class="lavina__empty">{{ $t('results.lavina.empty') }}</p>

          <ol v-else class="lavina__plans">
            <li v-for="row in planRows" :key="row.name" class="lavina__plan-row">
              <span class="lavina__plan-name" :title="row.name">{{ row.name }}</span>
              <span class="lavina__plan-track" aria-hidden="true">
                <i class="lavina__plan-target" :style="{ left: `${planTarget}%` }"></i>
                <i class="lavina__plan-bar" :style="{ width: `${row.width * progress}%`, background: row.color }"></i>
              </span>
              <b class="lavina__plan-value">{{ percent(row.value * 100) }}</b>
            </li>
          </ol>

          <p v-if="planRows.length" class="lavina__note">{{ $t('results.lavina.targetNote') }}</p>
        </article>
      </div>
    </template>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import {
  mdiAccountGroupOutline,
  mdiBullseyeArrow,
  mdiCashMultiple,
  mdiChartDonut,
  mdiCreditCardOutline,
  mdiPercentOutline,
  mdiReceiptTextOutline,
} from '@mdi/js'
import { useResultsStore } from '@/stores/results'
import { useScopeStore } from '@/stores/scope'
import { calloutLayout, ringPath } from '@/utils/calloutPie'
import { CAT_COLORS, catPlanColor } from '@/utils/resultsColors'
import { animateProgress } from '@/utils/tween'
import numberFormatMixin from '@/mixins/numberFormat'

// Цвета — из прежней страницы итогов (блок «Лавина»)
// Выполнение плана Лавины: от 100 % зелёный, от 90 % оранжевый, ниже — красный
function lavinaPlanColor(value) {
  if (value >= 1) return '#22c55e'
  if (value >= 0.9) return '#f59e0b'
  return '#ef4444'
}

// Карточки показателей: поле lavina_main, вид значения и цвет карточки
const KPIS = [
  { id: 'revenue', field: 'revenue', kind: 'money', icon: mdiCashMultiple, color: '#6366f1' },
  { id: 'traffic', field: 'avg_traffic', kind: 'money', icon: mdiAccountGroupOutline, color: '#14b8a6' },
  { id: 'conversion', field: 'conversion', kind: 'percent', icon: mdiPercentOutline, color: '#3b82f6' },
  { id: 'check', field: 'avg_check', kind: 'money', icon: mdiReceiptTextOutline, color: '#f59e0b' },
  { id: 'credit', field: 'credit_pct', kind: 'percent', icon: mdiCreditCardOutline, color: '#22c55e' },
]

// В списке структуры сразу видны категории с долей от 1 %, остальные — по кнопке (в кольце видны все)
const MIN_SHARE = 0.01

// Круг с выносками — как на прежней странице: сплошной круг радиуса 360, первый сектор сверху.
// CALLOUT_POP — насколько выдвигается сектор под курсором
const CALLOUT_R = 360
const CALLOUT_POP = 16
// Уже этой ширины панели текст выносок мельче 12 px — вместо круга с выносками показываются кольцо и список
const COMPACT_BELOW = 820

// Кольцо: центр, внешний и внутренний радиус в координатах viewBox
const C = 110
const OUTER = 100
const INNER = 64

const isNumber = (value) => typeof value === 'number' && Number.isFinite(value)

function point(radius, angle) {
  return `${(C + radius * Math.sin(angle)).toFixed(2)} ${(C - radius * Math.cos(angle)).toFixed(2)}`
}

// Сектор кольца от угла start до end (радианы, по часовой от 12 часов)
function arc(start, end) {
  const large = end - start > Math.PI ? 1 : 0
  return [
    `M ${point(OUTER, start)}`,
    `A ${OUTER} ${OUTER} 0 ${large} 1 ${point(OUTER, end)}`,
    `L ${point(INNER, end)}`,
    `A ${INNER} ${INNER} 0 ${large} 0 ${point(INNER, start)}`,
    'Z',
  ].join(' ')
}

export default {
  name: 'ResultsLavina',

  mixins: [numberFormatMixin],

  data() {
    return {
      mdiBullseyeArrow,
      mdiChartDonut,
      // Категория под курсором: подсвечивается и в кольце, и в списке
      hovered: null,
      showAll: false,
      progress: 0,
      // Ширина панели структуры: от неё зависит вид диаграммы
      structureWidth: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['period']),

    locale() {
      return this.$i18n.locale
    },

    main() {
      return useResultsStore().rowsOf('lavina_main', this.period)[0] || null
    },

    planPct() {
      return this.main && isNumber(this.main.plan_pct) ? this.main.plan_pct : 0
    },

    planColor() {
      return lavinaPlanColor(this.planPct)
    },

    kpis() {
      return KPIS.map((kpi) => {
        const value = this.main ? this.main[kpi.field] : null
        const shown = isNumber(value) ? value * this.progress : null
        return { ...kpi, text: shown === null ? '—' : kpi.kind === 'percent' ? this.percent(shown * 100) : this.money(shown) }
      })
    },

    // Категории товарооборота по убыванию; цвет — по месту (catColors), как на прежней странице
    categories() {
      const rows = useResultsStore()
        .rowsOf('lavina_cat_revenue', this.period)
        .filter((row) => isNumber(row.revenue) && row.revenue > 0)
        .sort((a, b) => b.revenue - a.revenue)
      const total = rows.reduce((sum, row) => sum + row.revenue, 0)
      return rows.map((row, index) => ({
        name: row.category,
        value: row.revenue,
        share: total ? row.revenue / total : 0,
        avgPrice: isNumber(row.avg_price) ? row.avg_price : null,
        color: CAT_COLORS[index % CAT_COLORS.length],
      }))
    },

    revenueTotal() {
      return this.categories.reduce((sum, item) => sum + item.value, 0)
    },

    segments() {
      let angle = 0
      const full = Math.PI * 2 * this.progress
      return this.categories.map((item) => {
        const start = angle
        angle += item.share * full
        // Крошечный сектор всё равно рисуется, хотя бы тонкой линией
        const end = Math.max(angle, start + 0.004)
        return { ...item, path: arc(start, Math.min(end, Math.PI * 2 - 0.0001)) }
      })
    },

    activeSegment() {
      return this.categories.find((item) => item.name === this.hovered) || null
    },

    narrow() {
      return this.structureWidth > 0 && this.structureWidth < COMPACT_BELOW
    },

    // Круг с выносками: подписи — у категорий от 1 %, как на прежней странице
    callout() {
      const items = this.categories.map((item) => ({ ...item, label: item.name }))
      return calloutLayout(
        items,
        {
          r: CALLOUT_R,
          minShare: MIN_SHARE,
          format: { value: (value) => this.money(value), share: (share) => this.percent(share * 100) },
        },
      )
    },

    // Секторы с анимацией появления (растут по кругу) и сдвигом наружу для сектора под курсором
    calloutSegments() {
      const start = this.callout.segments.length ? this.callout.segments[0].start : 0
      const turn = (angle) => start + (angle - start) * this.progress
      return this.callout.segments.map((segment) => ({
        ...segment,
        // Не больше полного круга без капли: дуга ровно в 360° рисуется как точка (одна категория на весь круг)
        path: ringPath(turn(segment.start), Math.min(Math.max(turn(segment.end), turn(segment.start) + 0.002), segment.start + Math.PI * 2 - 0.0001), CALLOUT_R),
        pop: `translate(${(Math.cos(segment.midA) * CALLOUT_POP).toFixed(1)}px, ${(Math.sin(segment.midA) * CALLOUT_POP).toFixed(1)}px)`,
      }))
    },

    visibleCategories() {
      return this.showAll ? this.categories : this.categories.filter((item) => item.share >= MIN_SHARE)
    },

    hiddenCount() {
      return this.categories.filter((item) => item.share < MIN_SHARE).length
    },

    hiddenShare() {
      return this.categories.filter((item) => item.share < MIN_SHARE).reduce((sum, item) => sum + item.share, 0)
    },

    // Выполнение плана по категориям (lavina_cat_plan), цвета — 7 ступеней плана прежней страницы.
    // Шкала — до наибольшего значения, но не меньше 105 %, чтобы отметка 100 % всегда была видна
    planScale() {
      const rows = useResultsStore().rowsOf('lavina_cat_plan', this.period).filter((row) => isNumber(row.plan_pct))
      return Math.max(1.05, ...rows.map((row) => row.plan_pct)) * 1.04
    },

    planTarget() {
      return (1 / this.planScale) * 100
    },

    planRows() {
      return useResultsStore()
        .rowsOf('lavina_cat_plan', this.period)
        .filter((row) => isNumber(row.plan_pct))
        .sort((a, b) => b.plan_pct - a.plan_pct)
        .map((row) => ({
          name: row.category,
          value: row.plan_pct,
          width: (Math.max(0, row.plan_pct) / this.planScale) * 100,
          color: catPlanColor(row.plan_pct),
        }))
    },
  },

  watch: {
    period: {
      immediate: true,
      handler() {
        this.showAll = false
        if (this.stopTween) this.stopTween()
        this.stopTween = animateProgress((progress) => (this.progress = progress), { delay: 150 })
      },
    },
  },

  // Ширину панели структуры замеряем, когда панель есть на странице (её нет, пока нет данных за период)
  mounted() {
    this.observe()
  },

  updated() {
    this.observe()
  },

  beforeUnmount() {
    if (this.stopTween) this.stopTween()
    if (this.observer) this.observer.disconnect()
  },

  methods: {
    observe() {
      const element = this.$refs.structure
      if (!element || element === this.observed) return
      if (this.observer) this.observer.disconnect()
      this.observer = new ResizeObserver(([entry]) => (this.structureWidth = Math.floor(entry.contentRect.width)))
      this.observer.observe(element)
      this.observed = element
      this.structureWidth = Math.floor(element.getBoundingClientRect().width)
    },

    tooltip(segment) {
      const price = segment.avgPrice === null ? '' : `, ${this.$t('results.lavina.avgPrice')} ${this.money(segment.avgPrice)}`
      return `${segment.name}: ${this.money(segment.value)} ${this.$t('kpi.uah')} (${this.percent(segment.share * 100)})${price}`
    },
  },
}
</script>

<style lang="scss" scoped>
