    linear-gradient(rgb(var(--v-theme-surface)), rgb(var(--v-theme-surface))) padding-box,
    linear-gradient(135deg, color-mix(in srgb, var(--tone) 55%, transparent), rgba(var(--v-theme-on-surface), 0.08)) border-box;
  box-shadow: 0 1px 2px rgba(var(--v-theme-on-surface), 0.05), 0 14px 32px -22px rgba(var(--v-theme-on-surface), 0.4);
  text-align: center;
}

