  &__kpis {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    align-items: stretch;
    gap: $spacer * 4;
  }

  &__plan {
    @extend %card;
  }

  &__kpi {
    @extend %card;

    // Полоска цвета показателя снизу, как на прежней странице
    &::after {
      content: '';
      position: absolute;
      right: 0;
      bottom: 0;
      left: 0;
      height: 3px;
      background: var(--tone);
    }
  }

  &__label {
    color: rgba(var(--v-theme-on-surface), 0.55);
    font-size: 0.7rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  &__gauge {
