    background: color-mix(in srgb, var(--tone) 14%, transparent);
    color: var(--tone);
  }

  &__kpi-value {
    color: var(--tone);
    font-size: 1.45rem;
    font-weight: 800;
    letter-spacing: -0.03em;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  &__row {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: $spacer * 5;
  }

  &__panel {
    @include panel;

    display: flex;
    flex-direction: column;
    gap: $spacer * 4;
    padding: $spacer * 5;
  }

  &__head {
    display: flex;
    align-items: center;
    gap: $spacer * 2.5;
  }

  &__icon {
    display: inline-flex;
    flex: none;
