    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: $radius-md + 2px;
    background: rgb(var(--v-theme-brand-yellow));
    color: rgb(var(--v-theme-brand-ink));
    box-shadow: 0 6px 12px -6px rgba(var(--v-theme-brand-yellow), 1);
  }

  &__title {
    flex: 1;
    min-width: 0;
