    gap: $spacer * 2;
    min-width: 0;
  }

  // Круг с выносками
  &__callout {
    display: block;
    width: 100%;
    max-height: 640px;
    overflow: visible;
    font-family: $font-family;
  }

  &__slice {
    stroke: rgb(var(--v-theme-surface));
    stroke-width: 3;
    cursor: pointer;
    transition: transform 0.3s $ease-out-expo, opacity 0.2s ease;

    &--dim {
      opacity: 0.35;
