<template>
  <section class="cmp-bd" :class="{ 'cmp-bd--single': !changing }" :aria-label="$t('compare.breakdown')" :style="{ '--n': periods.length }">
    <!-- Показатель деталізації -->
    <div class="cmp-bd__metrics" role="radiogroup" :aria-label="$t('compare.metrics')">
      <button
        v-for="item in metrics"
        :key="item.id"
        type="button"
        role="radio"
        class="cmp-bd__metric"
        :class="{ 'cmp-bd__metric--active': item.id === current.id }"
        :aria-checked="item.id === current.id"
        @click="setMetric(item.id)"
      >
        <v-icon :icon="item.icon" size="15" />
        {{ $t(item.title) }}
      </button>
    </div>

    <div class="cmp-bd__head" aria-hidden="true">
      <span>{{ $t(network ? 'compare.byManagers' : 'compare.byStores') }}</span>
      <span v-for="time in periods" :key="time" class="cmp-bd__col">{{ time }}</span>
      <span v-if="changing" class="cmp-bd__col">{{ $t('compare.change') }} {{ first }} → {{ last }}</span>
    </div>

    <transition-group tag="ol" name="cmp-bd-move" class="cmp-bd__list">
      <li
        v-for="row in rows"
        :key="row.id"
        class="cmp-bd__row"
        :class="[`cmp-bd__row--${row.trend}`, { 'cmp-bd__row--current': row.current }]"
        :style="{ '--tone': row.color }"
        role="button"
        tabindex="0"
        :title="$t('compare.drill')"
        @click="open(row)"
        @keydown.enter.prevent="open(row)"
      >
        <span class="cmp-bd__name">
          <i aria-hidden="true"></i>
          {{ row.name }}
        </span>
        <span v-for="(value, index) in row.values" :key="periods[index]" class="cmp-bd__num" :class="{ 'cmp-bd__num--last': index === periods.length - 1 }" :data-period="periods[index]">{{ format(value) }}</span>
        <span v-if="changing" class="cmp-bd__change">
          <span class="cmp-bd__scale" aria-hidden="true">
            <i class="cmp-bd__zero"></i>
            <i class="cmp-bd__fill" :style="fillStyle(row)"></i>
          </span>
          <b>{{ row.deltaText }}</b>
        </span>
      </li>
    </transition-group>

    <p class="cmp-bd__hint">{{ $t('compare.drill') }}</p>
  </section>
</template>

<script>
import { mapActions, mapState } from 'pinia'
import { useCompareStore } from '@/stores/compare'
import { changeOf, metricsFor, signedChange, trendOf } from '@/utils/compare'
import { numberFormat } from '@/utils/format'

// Деталізація: выбранный показатель по каждому РМ (вся сеть) или по каждому магазину РМ во всех выбранных периодах
// и изменение от первого выбранного периода к последнему. Полоска — изменение от центра: вправо рост, влево падение.
// Строки отсортированы по изменению (при одном периоде изменения нет — по значению). Нажатие на строку — переход
// к этому РМ или магазину
export default {
  name: 'CompareBreakdown',

  emits: ['drill'],

  computed: {
    ...mapState(useCompareStore, ['network', 'managers', 'manager', 'source', 'stores', 'store', 'periods', 'metric']),

    // Общие показатели: у РМ и магазинов нет каналов продаж (интернет-магазин, мономаркет)
    metrics() {
      return metricsFor()
    },

    current() {
      return this.metrics.find((item) => item.id === this.metric) || this.metrics[0]
    },

    first() {
      return this.periods[0]
    },

    last() {
      return this.periods[this.periods.length - 1]
    },

    // Изменение есть, только когда выбрано больше одного периода
    changing() {
      return this.periods.length > 1
    },

    rows() {
      const metric = this.current
      const pick = (row) => (row && typeof row[metric.fact] === 'number' ? row[metric.fact] : null)
      let list
      if (this.network) {
        list = this.managers
          .filter((item) => item.source && item.source.status === 'ready')
          .map((item) => ({ id: item.id, name: item.name, color: item.color, values: this.periods.map((time) => pick(item.source.totals[time])) }))
      } else {
        const find = (time, name) => (this.source.stores[time] || []).find((row) => row.company === name)
        list = this.stores.map((name) => ({
          id: name,
          name,
          color: this.manager.color,
          current: name === this.store,
          values: this.periods.map((time) => pick(find(time, name))),
        }))
      }
      const withChange = list.map((row) => {
        const size = this.changing ? changeOf(row.values[0], row.values[row.values.length - 1], metric.percent) : null
        return { ...row, size, trend: trendOf(size) }
      })
      const order = this.changing ? (row) => row.size : (row) => row.values[0]
      withChange.sort((x, y) => (order(y) ?? -Infinity) - (order(x) ?? -Infinity))
      const span = Math.max(0.001, ...withChange.map((row) => Math.abs(row.size || 0)))
      return withChange.map((row) => ({ ...row, span, deltaText: this.deltaText(row.size) }))
    },
  },

  methods: {
    ...mapActions(useCompareStore, ['setMetric', 'setManager', 'setStore']),

    format(value) {
      if (value === null || value === undefined) return '—'
      const metric = this.current
      const text = numberFormat(this.$i18n.locale, { minimumFractionDigits: metric.digits, maximumFractionDigits: metric.digits }).format(value)
      return metric.suffix ? `${text}${metric.suffix}` : text
    },

    deltaText(size) {
      return signedChange(size, this.$i18n.locale, this.current.percent && this.$t('compare.points'))
    },

    // Полоска изменения от центра шкалы (ширина меняется плавно через CSS)
    fillStyle(row) {
      if (row.size === null) return { left: '50%', width: 0 }
      const width = (Math.abs(row.size) / row.span) * 50
      return row.size >= 0 ? { left: '50%', width: `${width}%` } : { left: `${50 - width}%`, width: `${width}%` }
    },

    // Переход: из сети — к РМ, из РМ — к магазину (повторное нажатие на выбранный магазин — снова все магазины)
    open(row) {
      if (this.network) this.setManager(row.id)
      else this.setStore(row.current ? null : row.id)
      this.$emit('drill')
    },
  },
}
</script>

